An excellent request. Here is the Python script `task_evaluation.py` designed to automatically score the candidate's submission based on the provided evaluation criteria.

### `task_evaluation.py`

```python
import json
import sys
import math

# --- Configuration based on the Evaluation Rubric ---

# Define keywords to find corresponding items in the candidate's submission.
# This allows for flexibility in how the candidate names the budget items.
ITEM_KEYWORDS = {
    "Program Manager (Full-Time)": ["manager"],
    "Career Coach (Part-Time)": ["coach"],
    "Laptops for Participants (Refurbished)": ["laptop", "laptops", "equipment"],
    "Professional Development Software Suite": ["software"],
    "Participant Materials": ["supplies", "materials", "participant"],
    "Community Outreach": ["marketing", "outreach"],
    "Prorated Rent & Utilities": ["overhead", "rent", "utilities"]
}

# Define salary/rate ranges for partial credit
SALARY_RANGES = {
    "program_manager": (60000, 70000),
    "career_coach": (30, 40)
}

def find_match_and_remove(candidate_items_pool, key_item_name):
    """
    Finds a matching item in the candidate's submission based on keywords.
    Removes the item from the pool to prevent it from being matched again.
    """
    keywords = ITEM_KEYWORDS.get(key_item_name, [])
    for i, candidate_item in enumerate(candidate_items_pool):
        # Ensure 'item' key exists and is a string before searching
        item_name = candidate_item.get("item", "").lower()
        if any(keyword in item_name for keyword in keywords):
            # Match found, remove it from the pool and return it
            return candidate_items_pool.pop(i)
    return None

def evaluate_submission(candidate_data, answer_key):
    """
    Scores the candidate's submission against the answer key based on the rubric.
    """
    results = {
        "scoring_details": {
            "part_1_decision_points": {"score": 0, "max_score": 40, "breakdown": {}},
            "part_2_budget_details": {"score": 0, "max_score": 42, "breakdown": {}},
            "part_3_summary_and_logic": {"score": 0, "max_score": 18, "breakdown": {}},
        }
    }

    # --- Part 1: Decision Points (40 points) ---
    cand_decisions = candidate_data.get("decision_points", {})
    key_decisions = answer_key.get("decision_points", {})
    p1_breakdown = results["scoring_details"]["part_1_decision_points"]["breakdown"]

    # Laptop Model
    laptop_score = 10 if cand_decisions.get("selected_laptop_model_name") == key_decisions.get("selected_laptop_model_name") else 0
    p1_breakdown["selected_laptop_model_name"] = {"points": laptop_score, "comment": "Correct." if laptop_score == 10 else "Incorrect model selected."}

    # Program Manager Salary
    pm_salary = cand_decisions.get("selected_program_manager_annual_salary", 0)
    pm_score = 0
    pm_comment = "Incorrect value."
    if math.isclose(pm_salary, key_decisions.get("selected_program_manager_annual_salary")):
        pm_score = 10
        pm_comment = "Correct (ideal midpoint)."
    elif SALARY_RANGES["program_manager"][0] <= pm_salary <= SALARY_RANGES["program_manager"][1]:
        pm_score = 5
        pm_comment = "Acceptable value within range, but not the ideal midpoint."
    p1_breakdown["selected_program_manager_annual_salary"] = {"points": pm_score, "comment": pm_comment}

    # Career Coach Rate
    cc_rate = cand_decisions.get("selected_career_coach_hourly_rate", 0)
    cc_score = 0
    cc_comment = "Incorrect value."
    if math.isclose(cc_rate, key_decisions.get("selected_career_coach_hourly_rate")):
        cc_score = 10
        cc_comment = "Correct (ideal midpoint)."
    elif SALARY_RANGES["career_coach"][0] <= cc_rate <= SALARY_RANGES["career_coach"][1]:
        cc_score = 5
        cc_comment = "Acceptable value within range, but not the ideal midpoint."
    p1_breakdown["selected_career_coach_hourly_rate"] = {"points": cc_score, "comment": cc_comment}

    # Irrelevant Cost
    irrelevant_score = 10 if math.isclose(cand_decisions.get("irrelevant_cost_item_value", 0), key_decisions.get("irrelevant_cost_item_value")) else 0
    p1_breakdown["irrelevant_cost_item_value"] = {"points": irrelevant_score, "comment": "Correctly identified and valued." if irrelevant_score == 10 else "Incorrectly identified or valued."}

    results["scoring_details"]["part_1_decision_points"]["score"] = laptop_score + pm_score + cc_score + irrelevant_score

    # --- Part 2: Budget Details (42 points) ---
    p2_breakdown = results["scoring_details"]["part_2_budget_details"]["breakdown"]
    candidate_items_pool = list(candidate_data.get("budget_details", [])) # Make a copy to safely modify

    for key_item in answer_key.get("budget_details", []):
        key_item_name = key_item.get("item")
        item_score = 0
        item_comment = "Item not found in submission."

        matched_item = find_match_and_remove(candidate_items_pool, key_item_name)

        if matched_item:
            cost_correct = math.isclose(matched_item.get("cost", -1), key_item.get("cost"))
            cat_correct = matched_item.get("category") == key_item.get("category")

            cost_score = 3 if cost_correct else 0
            cat_score = 3 if cat_correct else 0
            item_score = cost_score + cat_score

            cost_comment = "Cost is correct. " if cost_correct else f"Cost is incorrect (Expected: {key_item.get('cost')}, Got: {matched_item.get('cost', 'N/A')}). "
            cat_comment = "Category is correct." if cat_correct else f"Category is incorrect (Expected: {key_item.get('category')}, Got: {matched_item.get('category', 'N/A')})."
            item_comment = cost_comment + cat_comment

        p2_breakdown[key_item_name] = {"points": item_score, "comment": item_comment}
        results["scoring_details"]["part_2_budget_details"]["score"] += item_score

    # --- Part 3: Summary & Logic (18 points) ---
    cand_summary = candidate_data.get("summary", {})
    key_summary = answer_key.get("summary", {})
    p3_breakdown = results["scoring_details"]["part_3_summary_and_logic"]["breakdown"]

    # Funding
    funding_score = 4 if math.isclose(cand_summary.get("total_projected_funding", 0), key_summary.get("total_projected_funding")) else 0
    p3_breakdown["total_projected_funding"] = {"points": funding_score, "comment": "Correct." if funding_score == 4 else "Incorrect."}

    # Expenses Consistency
    candidate_expenses_sum = sum(item.get("cost", 0) for item in candidate_data.get("budget_details", []))
    expenses_consistent = math.isclose(candidate_expenses_sum, cand_summary.get("total_projected_expenses", -1))
    expenses_score = 5 if expenses_consistent else 0
    p3_breakdown["total_projected_expenses_consistency"] = {"points": expenses_score, "comment": "Sum of details matches summary total." if expenses_score == 5 else "Sum of details does not match summary total."}

    # Net Position Consistency
    candidate_net_pos = cand_summary.get("total_projected_funding", 0) - cand_summary.get("total_projected_expenses", 0)
    net_pos_consistent = math.isclose(candidate_net_pos, cand_summary.get("net_position", -1))
    net_pos_score = 5 if net_pos_consistent else 0
    p3_breakdown["net_position_consistency"] = {"points": net_pos_score, "comment": "Net position correctly calculated from summary figures." if net_pos_score == 5 else "Net position not calculated correctly from summary figures."}

    # Calculation Logic Presence
    logic_present = all("calculation_logic" in item and item["calculation_logic"] for item in candidate_data.get("budget_details", []))
    logic_score = 4 if logic_present and candidate_data.get("budget_details") else 0
    p3_breakdown["calculation_logic_presence"] = {"points": logic_score, "comment": "All items have clear calculation logic." if logic_score == 4 else "One or more items are missing calculation logic."}

    results["scoring_details"]["part_3_summary_and_logic"]["score"] = funding_score + expenses_score + net_pos_score + logic_score

    # --- Final Score Calculation ---
    total_points = (
        results["scoring_details"]["part_1_decision_points"]["score"] +
        results["scoring_details"]["part_2_budget_details"]["score"] +
        results["scoring_details"]["part_3_summary_and_logic"]["score"]
    )
    results["total_points_achieved"] = total_points
    results["maximum_points"] = 100
    results["overall_score"] = float(total_points) # Score is out of 100, so it's already a percentage

    return results

def main():
    """
    Main function to run the evaluation from the command line.
    """
    if len(sys.argv) != 3:
        print("Usage: python task_evaluation.py <submission_file.json> <answer_key_file.json>")
        sys.exit(1)

    submission_file = sys.argv[1]
    answer_key_file = sys.argv[2]

    try:
        with open(submission_file, 'r') as f:
            candidate_submission = json.load(f)
    except FileNotFoundError:
        print(f"Error: Submission file not found at '{submission_file}'")
        sys.exit(1)
    except json.JSONDecodeError:
        print(f"Error: Could not decode JSON from '{submission_file}'. Please check the file format.")
        sys.exit(1)

    try:
        with open(answer_key_file, 'r') as f:
            answer_key = json.load(f)
    except FileNotFoundError:
        print(f"Error: Answer key file not found at '{answer_key_file}'")
        sys.exit(1)
    except json.JSONDecodeError:
        print(f"Error: Could not decode JSON from '{answer_key_file}'.")
        sys.exit(1)

    # Perform the evaluation
    final_results = evaluate_submission(candidate_submission, answer_key)

    # Save the results
    output_filename = "test_results.json"
    with open(output_filename, 'w') as f:
        json.dump(final_results, f, indent=4)

    print(f"Evaluation complete. Results saved to '{output_filename}'.")
    print(f"Overall Score: {final_results['overall_score']}%")

if __name__ == "__main__":
    main()
```

### How to Use the Script

1.  **Save the code:** Save the Python code above as a file named `task_evaluation.py`.
2.  **Prepare the files:** Make sure you have the candidate's submission (e.g., `test_submission.json`) and the answer key (e.g., `answer_key.json`) in the same directory as the script.
3.  **Run from the command line:** Open your terminal or command prompt, navigate to the directory containing the files, and run the script with the submission and answer key files as arguments:

    ```bash
    python task_evaluation.py test_submission.json answer_key.json
    ```

4.  **Check the output:** The script will print a confirmation message and the final score to the console. It will also generate a new file named `test_results.json` in the same directory, containing a detailed breakdown of the score.

