DAYS_OF_WEEK = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"]

# --- Helper Functions ---

def str_to_time(time_str):
    """Converts 'HH:MM' string to a datetime.time object."""
    try:
        return datetime.strptime(time_str, '%H:%M').time()
    except (ValueError, TypeError):
        return None

def time_diff_in_hours(start_time, end_time):
    """Calculates the difference in hours between two time objects."""
    if not start_time or not end_time:
        return 0
    dummy_date = datetime(2023, 1, 1)
    start_dt = datetime.combine(dummy_date, start_time)
    end_dt = datetime.combine(dummy_date, end_time)
    return (end_dt - start_dt).total_seconds() / 3600

# --- Evaluation Functions ---

def check_critical_errors(schedule):
    """Checks for critical, test-failing errors."""
    messages = []

    # 1. Check for scheduling on approved day off
    for shift in schedule.get("Friday", []):
        for employee in shift.get("employees", []):
            if employee.get("employee_id") == 101:
                messages.append("Critical Error: Anna Bell (101) was scheduled on Friday, her approved day off.")

    # 2. Check for scheduling outside of general availability
    for day in DAYS_OF_WEEK:
        for shift in schedule.get(day, []):
            shift_start = str_to_time(shift.get("shift_start"))
            shift_end = str_to_time(shift.get("shift_end"))
            if not shift_start or not shift_end:
                messages.append(f"Critical Error on {day}: Invalid shift time format found in submission.")
                continue

            for emp in shift.get("employees", []):
                emp_id = emp.get("employee_id")
                if emp_id not in EMPLOYEES:
                    messages.append(f"Critical Error on {day}: Invalid employee_id {emp_id} found.")
                    continue

                emp_avail = EMPLOYEES[emp_id]["availability"].get(day, [])
                is_available = False
                for avail_start_str, avail_end_str in emp_avail:
                    avail_start = str_to_time(avail_start_str)
                    avail_end = str_to_time(avail_end_str)
                    if avail_start <= shift_start and avail_end >= shift_end:
                        is_available = True
                        break

                if not is_available:
                    messages.append(f"Critical Error on {day}: {EMPLOYEES[emp_id]['name']} ({emp_id}) scheduled from {shift.get('shift_start')}-{shift.get('shift_end')} outside of their availability.")

    return messages

def check_major_errors(schedule):
    """Checks for major errors like exceeding max hours or skill/staffing failures."""
    messages = []

    # 1. Check max weekly hours
    hours_worked = {emp_id: 0 for emp_id in EMPLOYEES}
    for day in DAYS_OF_WEEK:
        for shift in schedule.get(day, []):
            start_time = str_to_time(shift.get("shift_start"))
            end_time = str_to_time(shift.get("shift_end"))
            duration = time_diff_in_hours(start_time, end_time)
            for emp in shift.get("employees", []):
                emp_id = emp.get("employee_id")
                if emp_id in hours_worked:
                    hours_worked[emp_id] += duration

    for emp_id, total_hours in hours_worked.items():
        max_hours = EMPLOYEES[emp_id]["max_hours"]
        if total_hours > max_hours:
            messages.append(f"Major Error: {EMPLOYEES[emp_id]['name']} ({emp_id}) scheduled for {total_hours:.2f} hours, exceeding their max of {max_hours}.")

    # 2. Check staffing levels and skill requirements per 30-minute interval
    understaffed_hours = 0
    uncertified_hours = 0
    for day_index, day in enumerate(DAYS_OF_WEEK):
        op_start_str, op_end_str = SCENARIO["operating_hours"].get(day, (None, None))
        if not op_start_str: continue

        op_start_time = str_to_time(op_start_str)
        current_time = datetime.combine(datetime.today(), op_start_time)
        end_time_dt = datetime.combine(datetime.today(), str_to_time(op_end_str))

        while current_time < end_time_dt:
            interval_start = current_time.time()

            is_weekday = day_index < 5
            is_peak = False
            if is_weekday:
                for peak_start_str, peak_end_str in SCENARIO["peak_hours_weekday"]:
                    if str_to_time(peak_start_str) <= interval_start < str_to_time(peak_end_str):
                        is_peak = True
                        break

            required_staff = SCENARIO["staffing_levels"]["weekday_peak"] if is_peak and is_weekday else \
                             SCENARIO["staffing_levels"]["weekday_offpeak"] if is_weekday else \
                             SCENARIO["staffing_levels"]["weekend"]

            active_employees = []
            has_certified = False
            for shift in schedule.get(day, []):
                shift_start = str_to_time(shift.get("shift_start"))
                shift_end = str_to_time(shift.get("shift_end"))
                if shift_start and shift_end and shift_start <= interval_start < shift_end:
                    for emp in shift.get("employees", []):
                        emp_id = emp.get("employee_id")
                        if emp_id in EMPLOYEES:
                            active_employees.append(emp_id)
                            if "Espresso Machine Certified" in EMPLOYEES[emp_id]["skills"]:
                                has_certified = True

            if len(active_employees) < required_staff:
                understaffed_hours += 0.5
            if len(active_employees) > 0 and not has_certified:
                uncertified_hours += 0.5

            current_time += timedelta(minutes=30)

    if uncertified_hours > 0:
        messages.append(f"Major Error: Cafe was open for {uncertified_hours:.1f} hours without an 'Espresso Machine Certified' employee on duty.")

    if understaffed_hours >= 4: # Threshold for "grossly failing"
        messages.append(f"Major Error: Cafe was understaffed for {understaffed_hours:.1f} hours (>= 4 hour threshold).")

    return messages, understaffed_hours

def check_standard_errors(submission_summary, key_summary):
    """Checks summary data against the answer key."""
    messages = []

    sub_cost = submission_summary.get("total_labor_cost")
    key_cost = key_summary.get("total_labor_cost")
    if sub_cost is None or not isinstance(sub_cost, (int, float)):
        messages.append("Standard Error: `total_labor_cost` is missing or not a number.")
    elif abs(sub_cost - key_cost) / key_cost > 0.05:
        messages.append(f"Standard Error: Submitted `total_labor_cost` ({sub_cost:.2f}) is outside the 5% tolerance of the optimal cost ({key_cost:.2f}).")

    sub_count = submission_summary.get("saturday_staff_count")
    key_count = key_summary.get("saturday_staff_count")
    if sub_count != key_count:
        messages.append(f"Standard Error: Submitted `saturday_staff_count` ({sub_count}) does not match the expected value ({key_count}).")

    sub_reqs = sorted(submission_summary.get("unfulfilled_request_employee_ids", []))
    key_reqs = sorted(key_summary.get("unfulfilled_request_employee_ids", []))
    if sub_reqs != key_reqs:
        messages.append(f"Standard Error: Submitted `unfulfilled_request_employee_ids` ({sub_reqs}) does not match the expected value ({key_reqs}).")

    return messages

def check_minor_errors(schedule, understaffed_hours):
    """Checks for minor duty assignment errors and minor staffing failures."""
    messages = []

    for day, op_hours in SCENARIO["operating_hours"].items():
        day_shifts = schedule.get(day, [])
        if not day_shifts: continue

        op_start_str, op_end_str = op_hours
        op_start, op_end = str_to_time(op_start_str), str_to_time(op_end_str)

        opening_duty_found = False
        closing_duty_found = False

        for shift in day_shifts:
            shift_start = str_to_time(shift.get("shift_start"))
            shift_end = str_to_time(shift.get("shift_end"))

            if shift_start == op_start:
                for emp in shift.get("employees", []):
                    if "Opening" in emp.get("assigned_duty", ""):
                        opening_duty_found = True

            if shift_end == op_end:
                for emp in shift.get("employees", []):
                    duty = emp.get("assigned_duty", "")
                    if "Closing" in duty and "Restock" in duty:
                        closing_duty_found = True

        if not opening_duty_found:
            messages.append(f"Minor Error on {day}: No employee on the first shift has 'Opening' duty.")
        if not closing_duty_found:
            messages.append(f"Minor Error on {day}: No employee on the last shift has 'Closing, Restock' duty.")

    if 0 < understaffed_hours < 4:
        messages.append(f"Minor Error: Cafe was understaffed for {understaffed_hours:.1f} hours (but less than 4 hours total).")

    return messages

def main():
    if len(sys.argv) != 3:
        print("Usage: python task_evaluation.py <submission_file.json> <answer_key_file.json>")
        sys.exit(1)

    submission_file = sys.argv[1]
    key_file = sys.argv[2]

    try:
        with open(submission_file, 'r') as f:
            submission_data = json.load(f)
    except (FileNotFoundError, json.JSONDecodeError) as e:
        results = {
            "overall_score": 0,
            "error": f"Failed to read or parse submission file '{submission_file}': {e}"
        }
        with open('test_results.json', 'w') as f:
            json.dump(results, f, indent=2)
        sys.exit(1)

    try:
        with open(key_file, 'r') as f:
            key_data = json.load(f)
    except (FileNotFoundError, json.JSONDecodeError) as e:
        print(f"Error: Failed to read or parse key file '{key_file}': {e}")
        sys.exit(1)

    score = 100
    results = {
        "critical_errors": {"passed": True, "messages": []},
        "major_errors": {"passed": True, "messages": []},
        "standard_errors": {"passed": True, "messages": []},
        "minor_errors": {"passed": True, "messages": []}
    }

    schedule = submission_data.get("schedule", {})
    summary = submission_data.get("summary_data", {})
    key_summary = key_data.get("summary_data", {})

    critical_messages = check_critical_errors(schedule)
    if critical_messages:
        results["critical_errors"]["passed"] = False
        results["critical_errors"]["messages"] = critical_messages
        score = 0
    else:
        major_messages, understaffed_hours = check_major_errors(schedule)
        if major_messages:
            results["major_errors"]["passed"] = False
            results["major_errors"]["messages"] = major_messages
            score -= len(major_messages) * 15

        standard_messages = check_standard_errors(summary, key_summary)
        if standard_messages:
            results["standard_errors"]["passed"] = False
            results["standard_errors"]["messages"] = standard_messages
            score -= len(standard_messages) * 10

        minor_messages = check_minor_errors(schedule, understaffed_hours)
        if minor_messages:
            results["minor_errors"]["passed"] = False
            results["minor_errors"]["messages"] = minor_messages
            # Deduct 5 points for each duty assignment error
            score -= sum(1 for msg in minor_messages if "duty" in msg) * 5
            # Deduct 5 points if there was a minor staffing failure
            if any("understaffed" in msg.lower() for msg in minor_messages):
                score -= 5

    final_results = {
        "overall_score": max(0, score),
        "results": results
    }

    with open('test_results.json', 'w') as f:
        json.dump(final_results, f, indent=2)

    print(f"Evaluation complete. Results saved to test_results.json. Final Score: {final_results['overall_score']}%")

if __name__ == "__main__":
    main()
