```python
import sys
import json
import math

def load_json_file(filepath):
    """
    Loads a JSON file and returns its content.
    Exits the script with an error message if the file is not found or is invalid.
    """
    try:
        with open(filepath, 'r') as f:
            return json.load(f)
    except FileNotFoundError:
        print(f"Error: File not found at {filepath}")
        sys.exit(1)
    except json.JSONDecodeError:
        print(f"Error: Could not decode JSON from {filepath}. Check for syntax errors.")
        sys.exit(1)

def evaluate_submission(submission, answer_key):
    """
    Compares the candidate's submission against the answer key and scores it
    based on the predefined rubric.
    """
    results = {
        "overall_score": 0,
        "score_breakdown": {
            "technical_compliance": {"score": 0, "max_score": 10, "details": {}},
            "data_processing_and_calculation": {"score": 0, "max_score": 60, "details": {}},
            "analytical_skills": {"score": 0, "max_score": 30, "details": {}}
        }
    }
    total_score = 0

    # Helper for float comparison
    def is_close(a, b, rel_tol=1e-9, abs_tol=0.01):
        if not all(isinstance(i, (int, float)) for i in [a, b]):
            return False
        return math.isclose(a, b, rel_tol=rel_tol, abs_tol=abs_tol)

    # Helper to make lists of dicts comparable regardless of order
    def set_of_frozen_dicts(list_of_dicts):
        if not isinstance(list_of_dicts, list):
            return set()
        # Ensure all items in dicts are hashable
        return {frozenset(d.items()) for d in list_of_dicts}

    # 1. Technical Compliance (10 points)
    tech_score = 0
    # 1a. Check top-level keys (5 points)
    submission_keys = set(submission.keys())
    answer_keys = set(answer_key.keys())
    if submission_keys == answer_keys:
        tech_score += 5
        results["score_breakdown"]["technical_compliance"]["details"]["top_level_keys"] = {
            "score": 5, "max_score": 5, "comment": "Correct. All required top-level keys are present."
        }
    else:
        missing = answer_keys - submission_keys
        extra = submission_keys - answer_keys
        results["score_breakdown"]["technical_compliance"]["details"]["top_level_keys"] = {
            "score": 0, "max_score": 5, "comment": f"Incorrect. Missing: {list(missing)}, Extra: {list(extra)}"
        }
    # 1b. Check nested structure (5 points)
    sub_budget = submission.get("q1_budget_draft", {})
    ans_budget = answer_key.get("q1_budget_draft", {})
    if isinstance(sub_budget, dict) and set(sub_budget.keys()) == set(ans_budget.keys()):
        tech_score += 5
        results["score_breakdown"]["technical_compliance"]["details"]["nested_structure"] = {
            "score": 5, "max_score": 5, "comment": "Correct. All required monthly keys are present in 'q1_budget_draft'."
        }
    else:
        results["score_breakdown"]["technical_compliance"]["details"]["nested_structure"] = {
            "score": 0, "max_score": 5, "comment": "Incorrect or missing monthly keys in 'q1_budget_draft'."
        }
    results["score_breakdown"]["technical_compliance"]["score"] = tech_score
    total_score += tech_score

    # 2. Data Processing & Calculation (60 points)
    calc_score = 0
    calc_details = {}
    calc_rubric = {
        "january": {"max_score": 15, "points": {"base": 2, "agency_fees": 5, "monthly_total": 4}},
        "february": {"max_score": 20, "points": {"base": 3, "agency_fees": 6, "monthly_total": 5}},
        "march": {"max_score": 15, "points": {"base": 2, "agency_fees": 5, "monthly_total": 4}}
    }

    for month, rubric in calc_rubric.items():
        month_score = 0
        month_details = {}
        sub_month_data = sub_budget.get(month, {})
        ans_month_data = ans_budget.get(month, {})

        for item, ans_value in ans_month_data.items():
            sub_value = sub_month_data.get(item)
            points = 0

            item_points_map = {
                "agency_fees": rubric["points"]["agency_fees"],
                "monthly_total": rubric["points"]["monthly_total"]
            }
            item_max_points = item_points_map.get(item, rubric["points"]["base"])

            if is_close(sub_value, ans_value):
                points = item_max_points
                comment = "Correct."
            else:
                comment = f"Incorrect. Submitted: {sub_value}, Expected: {ans_value}."

            month_score += points
            month_details[item] = {"score": points, "max_score": item_max_points, "comment": comment}

        calc_score += month_score
        calc_details[month] = {"score": month_score, "max_score": rubric["max_score"], "details": month_details}

    # 2d. Quarterly Grand Total (10 points)
    qgt_score = 0
    qgt_max_score = 10
    sub_qgt = submission.get("quarterly_grand_total")
    ans_qgt = answer_key.get("quarterly_grand_total")
    if is_close(sub_qgt, ans_qgt):
        qgt_score = qgt_max_score
        comment = "Correct."
    else:
        comment = f"Incorrect. Submitted: {sub_qgt}, Expected: {ans_qgt}."

    calc_score += qgt_score
    calc_details["quarterly_grand_total"] = {"score": qgt_score, "max_score": qgt_max_score, "comment": comment}
    results["score_breakdown"]["data_processing_and_calculation"]["score"] = calc_score
    results["score_breakdown"]["data_processing_and_calculation"]["details"] = calc_details
    total_score += calc_score

    # 3. Analytical Skills (30 points)
    analytical_score = 0
    analytical_details = {}

    # 3a. Data Integrity Flags (20 points)
    flags_score = 0
    flags_details = {}
    sub_flags = set_of_frozen_dicts(submission.get("data_integrity_flags", []))

    # Find the specific flags in the answer key to check against
    duplicate_row_flag = next((frozenset(f.items()) for f in answer_key["data_integrity_flags"] if "duplicate row" in f["issue_description"]), None)
    negative_value_flag = next((frozenset(f.items()) for f in answer_key["data_integrity_flags"] if "negative expense" in f["issue_description"]), None)

    flag_1_score = 15 if duplicate_row_flag and duplicate_row_flag in sub_flags else 0
    flag_2_score = 5 if negative_value_flag and negative_value_flag in sub_flags else 0
    flags_score = flag_1_score + flag_2_score

    flags_details["duplicate_row_flag"] = {"score": flag_1_score, "max_score": 15, "comment": "Correctly identified and flagged the duplicate row." if flag_1_score > 0 else "Did not identify the duplicate row."}
    flags_details["negative_value_flag"] = {"score": flag_2_score, "max_score": 5, "comment": "Correctly identified and flagged the negative value." if flag_2_score > 0 else "Did not identify the negative value."}
    analytical_details["data_integrity_flags"] = {"score": flags_score, "max_score": 20, "details": flags_details}
    analytical_score += flags_score

    # 3b. Justification Notes (10 points)
    notes_score = 0
    notes_details = {}
    sub_notes = set_of_frozen_dicts(submission.get("justification_notes", []))
    ans_notes = set_of_frozen_dicts(answer_key.get("justification_notes", []))

    correct_notes_found = sub_notes.intersection(ans_notes)
    correct_notes_score = len(correct_notes_found) * 2
    notes_details["correct_notes_included"] = {"score": correct_notes_score, "max_score": 8, "comment": f"Found {len(correct_notes_found)} of {len(ans_notes)} required notes."}

    distractor_score = 2 if len(sub_notes) == len(correct_notes_found) else 0
    notes_details["distractors_excluded"] = {"score": distractor_score, "max_score": 2, "comment": "Correctly excluded distractor notes." if distractor_score > 0 else "Incorrectly included one or more distractor notes."}

    notes_score = correct_notes_score + distractor_score
    analytical_details["justification_notes"] = {"score": notes_score, "max_score": 10, "details": notes_details}
    analytical_score += notes_score

    results["score_breakdown"]["analytical_skills"]["score"] = analytical_score
    results["score_breakdown"]["analytical_skills"]["details"] = analytical_details
    total_score += analytical_score

    # Finalize
    results["overall_score"] = total_score
    return results

def main():
    """
    Main function to run the evaluation script from the command line.
    """
    if len(sys.argv) != 3:
        print("Usage: python task_evaluation.py <submission_file.json> <answer_key_file.json>")
        sys.exit(1)

    submission_path = sys.argv[1]
    answer_key_path = sys.argv[2]

    submission_data = load_json_file(submission_path)
    answer_key_data = load_json_file(answer_key_path)

    results = evaluate_submission(submission_data, answer_key_data)

    try:
        with open("test_results.json", 'w') as f:
            json.dump(results, f, indent=4)
        print("Evaluation complete. Results saved to test_results.json")
    except IOError:
        print("Error: Could not write results to test_results.json")
        sys.exit(1)

if __name__ == "__main__":
    main()
```

