      }
    ]
  },
  "question_2": {
    "description": "Determine the standard volume discount rates.",
    "answer": [
      {
        "license_tier": "1-10",
        "discount_percentage": 0
      },
      {
        "license_tier": "11-50",
        "discount_percentage": 0
      },
      {
        "license_tier": "51-100",
        "discount_percentage": 0
      }
    ]
  },
  "question_3": {
    "description": "Calculate the final annual price for the two customer scenarios.",
    "answer": [
      {
        "customer_name": "Global Corp Inc.",
        "total_annual_price": 0.00,
        "justification": "Your brief explanation for the final price calculation."
      },
      {
        "customer_name": "Mid-Size Creative Agency",
        "total_annual_price": 0.00,
        "justification": "Your brief explanation for the final price calculation."
      }
    ]
  }
}
```

---

### **Field Formatting Rules**

Adhere strictly to the following formats for each field to ensure your submission is graded correctly.

*   **`annual_list_price`**:
    *   **Type**: Number
    *   **Format**: Must include two decimal places (e.g., `100.00`, `250.50`).

*   **`discount_percentage`**:
    *   **Type**: Number
    *   **Format**: Must be an integer representing the percentage value (e.g., `5` for 5%, `10` for 10%). Do not use the decimal form (e.g., `0.05`).

*   **`total_annual_price`**:
    *   **Type**: Number
    *   **Format**: Must include two decimal places (e.g., `27000.00`, `4275.00`).

*   **`justification`**:
    *   **Type**: String
    *   **Format**: A brief (1-2 sentences) text explanation of how you arrived at the `total_annual_price`. You should reference the specific discounts applied (e.g., "Applied 10% volume discount...").

*   **All other pre-filled string values** (e.g., `"Basic"`, `"1-10"`, `"Global Corp Inc."`):
    *   **Do not modify these values.** They must match the provided template exactly.

grading:
An excellent request. Here is the Python script `task_evaluation.py` that automates the scoring of the Administrative Services Manager practical exam based on the provided evaluation criteria.

This script is designed to be robust, providing not only a final score but also detailed feedback on each section of the candidate's submission, mirroring the logic an expert human evaluator would use.

### `task_evaluation.py`

```python
import sys
import json
from datetime import datetime

# --- Helper Functions ---

def load_json_file(filepath):
    """
    Loads a JSON file and returns its content.
    Returns None if the file is not found or contains invalid JSON.
    """
    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            return json.load(f)
    except FileNotFoundError:
        print(f"Error: File not found at {filepath}")
        return None
    except json.JSONDecodeError:
        print(f"Error: Invalid JSON format in {filepath}. The file may be empty or malformed.")
        return None

def is_valid_date_format(date_string):
    """Checks if a date string is in YYYY-MM-DD format."""
    if not isinstance(date_string, str):
        return False
    try:
        datetime.strptime(date_string, '%Y-%m-%d')
        return True
    except ValueError:
        return False

def is_date_in_q4(date_string):
    """Checks if a date is within Q4 2023."""
    if not is_valid_date_format(date_string):
        return False
    d = datetime.strptime(date_string, '%Y-%m-%d').date()
    start_q4 = datetime.strptime('2023-10-01', '%Y-%m-%d').date()
    end_q4 = datetime.strptime('2023-12-31', '%Y-%m-%d').date()
    return start_q4 <= d <= end_q4

# --- Evaluation Functions based on Rubric ---

def evaluate_problem_analysis(submission):
    """Evaluates the problem_analysis section (Max 30 points)."""
    score = 0
    feedback = {}

    cost_problem_desc = ""
    desk_problem_desc = ""

    problems = submission.get('problem_analysis', [])
    if not isinstance(problems, list) or len(problems) != 2:
        feedback['structure_error'] = f"Expected 2 problems in a list, but found {len(problems)}."
        return 0, feedback

    for problem in problems:
        desc = problem.get('description', '').lower()
        if any(keyword in desc for keyword in ['cost', 'fee', 'spend', 'supply', 'paper', 'vendor']):
            cost_problem_desc = desc
        elif any(keyword in desc for keyword in ['desk', 'reception', 'chaotic', 'visitor']):
            desk_problem_desc = desc

    # Score Problem 1: Cost/Supply Issue (15 pts)
    cost_score = 0
    cost_feedback = "No relevant cost/supply problem identified."
    if cost_problem_desc:
        if 'furniture' in cost_problem_desc or 'chair' in cost_problem_desc:
            cost_score = 0
            cost_feedback = "Major Error: Focused on the one-time furniture expense (red herring) instead of recurring operational costs."
        elif ('rush' in cost_problem_desc or 'shipping' in cost_problem_desc) and ('stockout' in cost_problem_desc or 'ran out' in cost_problem_desc):
            cost_score = 15
            cost_feedback = "Excellent: Correctly identified rush fees as the key cost driver and linked it to inefficient ordering/stockouts."
        elif 'cost' in cost_problem_desc or 'fee' in cost_problem_desc:
            cost_score = 10
            cost_feedback = "Good: Identified high costs but did not specify rush fees or link them to service issues like stockouts."
        else:
            cost_score = 5
            cost_feedback = "Fair: Vaguely mentioned cost or supply issues without specific evidence from the data."

    score += cost_score
    feedback['problem_1_cost_issue'] = {'score': cost_score, 'feedback': cost_feedback}

    # Score Problem 2: Front Desk Issue (15 pts)
    desk_score = 0
    desk_feedback = "No relevant front desk problem identified."
    if desk_problem_desc:
        if any(keyword in desk_problem_desc for keyword in ['process', 'procedure', 'standardized', 'system', 'workflow']):
            desk_score = 15
            desk_feedback = "Excellent: Correctly identified the lack of a formal process as the root cause of the 'chaotic' feedback."
        elif 'chaotic' in desk_problem_desc:
            desk_score = 10
            desk_feedback = "Good: Identified the 'chaotic' front desk symptom but did not diagnose the root cause (lack of process)."
        else:
            desk_score = 0
            desk_feedback = "Missed: Failed to identify the front desk issue from the provided feedback."

    score += desk_score
    feedback['problem_2_desk_issue'] = {'score': desk_score, 'feedback': desk_feedback}

    return score, feedback

def evaluate_goal(goal_obj, goal_type):
    """Evaluates a single goal object (cost or desk) (Max 30 points)."""
    score = 0
    feedback = {}

    title = goal_obj.get('goal_title', '').lower()
    desc = goal_obj.get('goal_description', '').lower()
    metric = goal_obj.get('metric_for_success', '').lower()

    # Goal Quality (10 pts)
    quality_score = 0
    if goal_type == 'cost' and any(k in title+desc for k in ['cost', 'spend', 'supply', 'fee', 'waste', 'streamline']):
        quality_score = 10
    elif goal_type == 'desk' and any(k in title+desc for k in ['desk', 'reception', 'process', 'standardize', 'implement']):
        quality_score = 10
    elif title or desc:
        quality_score = 5
    score += quality_score
    feedback['quality'] = {'score': quality_score, 'feedback': 'Goal is clear, actionable, and linked to the problem.' if quality_score == 10 else 'Goal is relevant but vague.'}

    # Metric for Success (10 pts)
    metric_score = 0
    if goal_type == 'cost':
        if '$0' in metric and ('rush' in metric or 'shipping' in metric):
            metric_score = 10
        elif '%' in metric or 'reduce' in metric:
            metric_score = 5
    elif goal_type == 'desk':
        if any(k in metric for k in ['document', 'procedure', 'implement', 'train']):
            metric_score = 10
        elif 'complaint' in metric:
            metric_score = 5
    score += metric_score
    feedback['metric'] = {'score': metric_score, 'feedback': 'Metric is specific and highly quantifiable.' if metric_score == 10 else 'Metric is measurable but could be stronger.' if metric_score == 5 else 'Metric is vague or not measurable.'}

    # Action Steps & Roles (10 pts)
    steps_score = 0
    steps = goal_obj.get('action_steps', [])
    if not isinstance(steps, list) or not steps:
        steps_feedback = "No action steps provided."
    else:
        step_descs = " ".join([s.get('step_description', '').lower() for s in steps])
        roles = [s.get('assigned_to_role', '') for s in steps]

        if goal_type == 'cost':
            logic_ok = 'inventory' in step_descs and ('reorder' in step_descs or 'level' in step_descs) and 'consolidate' in step_descs
            roles_ok = all(r == 'Admin Assistant' for r in roles if r)
            if logic_ok and roles_ok:
                steps_score = 10
                steps_feedback = "Action steps are logical and correctly assigned to the appropriate role."
            else:
                steps_score = 5
                steps_feedback = "Action steps are relevant but may be illogical in sequence or have questionable role assignments."
        elif goal_type == 'desk':
            logic_ok = 'draft' in step_descs and ('designate' in step_descs or 'area' in step_descs) and 'train' in step_descs
            roles_ok = 'Admin Assistant' in roles and 'Mailroom Clerk' in roles and 'Receptionist' in roles
            if logic_ok and roles_ok:
                steps_score = 10
                steps_feedback = "Action steps are practical and demonstrate a strong understanding of team roles."
            else:
                steps_score = 5
                steps_feedback = "Action steps are relevant but may be illogical or have questionable role assignments."

    score += steps_score
    feedback['action_steps'] = {'score': steps_score, 'feedback': steps_feedback}

    return score, feedback

def evaluate_goals_section(submission):
    """Finds and evaluates the two goals (Max 60 points)."""
    score = 0
    feedback = {}

    goals = submission.get('department_goals', [])
    if not isinstance(goals, list) or len(goals) != 2:
        feedback['structure_error'] = f"Expected 2 goals in a list, but found {len(goals)}."
        return 0, feedback

    cost_goal, desk_goal = None, None
    for goal in goals:
        title_desc = str(goal.get('goal_title', '')) + str(goal.get('goal_description', ''))
        title_desc = title_desc.lower()
        if any(k in title_desc for k in ['cost', 'spend', 'supply', 'fee', 'waste']):
            cost_goal = goal
        elif any(k in title_desc for k in ['desk', 'reception', 'chaotic', 'visitor']):
            desk_goal = goal

    if cost_goal:
        cost_score, cost_feedback = evaluate_goal(cost_goal, 'cost')
        score += cost_score
        feedback['goal_1_cost'] = cost_feedback
    else:
        feedback['goal_1_cost'] = {'score': 0, 'feedback': 'Cost-related goal not identified or is poorly described.'}

    if desk_goal:
        desk_score, desk_feedback = evaluate_goal(desk_goal, 'desk')
        score += desk_score
        feedback['goal_2_desk'] = desk_feedback
    else:
        feedback['goal_2_desk'] = {'score': 0, 'feedback': 'Desk-related goal not identified or is poorly described.'}

    return score, feedback

def evaluate_formatting(submission):
    """Evaluates deadlines and JSON structure (Max 10 points)."""
    feedback_list = []
    errors = 0

    goals = submission.get('department_goals', [])
    if not isinstance(goals, list) or not goals:
        return 0, ["No 'department_goals' array found to check formatting."]

    for i, goal in enumerate(goals):
        if not isinstance(goal, dict): continue
        overall_deadline_str = goal.get('overall_deadline')
        if not is_date_in_q4(overall_deadline_str):
            errors += 1
            feedback_list.append(f"Goal {i+1}: Overall deadline '{overall_deadline_str}' is invalid or not in Q4 2023.")
        else:
            overall_deadline_date = datetime.strptime(overall_deadline_str, '%Y-%m-%d').date()
            action_steps = goal.get('action_steps', [])
            if not isinstance(action_steps, list): continue
            for j, step in enumerate(action_steps):
                if not isinstance(step, dict): continue
                step_deadline_str = step.get('step_deadline')
                if not is_valid_date_format(step_deadline_str):
                    errors += 1
                    feedback_list.append(f"Goal {i+1}, Step {j+1}: Step deadline '{step_deadline_str}' has an invalid format.")
                else:
                    step_deadline_date = datetime.strptime(step_deadline_str, '%Y-%m-%d').date()
                    if step_deadline_date > overall_deadline_date:
                        errors += 1
                        feedback_list.append(f"Goal {i+1}, Step {j+1}: Step deadline ({step_deadline_str}) is after the overall goal deadline ({overall_deadline_str}).")

    if errors == 0:
        score = 10
        feedback_list.append("All deadlines are correctly formatted and logical.")
    elif errors <= 2:
        score = 5
        feedback_list.append("Minor issues found with deadline formatting or logic.")
    else:
        score = 0
        feedback_list.append("Multiple errors found with deadlines.")

    return score, feedback_list

# --- Main Execution ---

def main():
    """Main function to run the evaluation script."""
    if len(sys.argv) != 3:
        print("Usage: python task_evaluation.py <submission_file.json> <answer_key_file.json>")
        sys.exit(1)

    submission_path = sys.argv[1]
    # The answer key is not used in the logic but is required by the command
    answer_key_path = sys.argv[2] 

    submission = load_json_file(submission_path)

    if submission is None:
        results = {
            'overall_score': 0,
            'passing_status': 'Fail',
            'evaluation_details': {
                'error': f'Could not read or parse the submission file: {submission_path}. The file is missing, empty, or contains invalid JSON.'
            }
        }
    else:
        total_score = 0
        evaluation_details = {}

        # 1. Evaluate Problem Analysis (30 pts)
        problem_score, problem_feedback = evaluate_problem_analysis(submission)
        total_score += problem_score
        evaluation_details['problem_analysis'] = {
            'score': problem_score,
            'max_score': 30,
            'feedback': problem_feedback
        }

        # 2. Evaluate Goals (60 pts)
        goals_score, goals_feedback = evaluate_goals_section(submission)
        total_score += goals_score
        evaluation_details['department_goals'] = {
            'score': goals_score,
            'max_score': 60,
            'feedback': goals_feedback
        }

        # 3. Evaluate Formatting (10 pts)
        format_score, format_feedback = evaluate_formatting(submission)
        total_score += format_score
        evaluation_details['formatting_and_deadlines'] = {
            'score': format_score,
            'max_score': 10,
            'feedback': format_feedback
        }

        # Final Results
        results = {
            'overall_score': total_score,
            'passing_status': 'Pass' if total_score >= 80 else 'Fail',
            'evaluation_details': evaluation_details
        }

    # Save results to file
    try:
        with open('test_results.json', 'w', encoding='utf-8') as f:
            json.dump(results, f, indent=4)
        print(f"Evaluation complete. Results saved to test_results.json. Overall Score: {results.get('overall_score', 0)}/100")
    except IOError as e:
        print(f"Error writing results to file: {e}")

if __name__ == "__main__":
    main()
```

submission:
You must submit your answers in a single JSON file. No other supplementary files are required.

### **File Name**

Your submission file must be named exactly:
`test_submission.json`

### **Answer Format**

Your `test_submission.json` file must contain a single JSON object that strictly follows the structure, keys, and data formats specified below. Copy the template into a text editor and replace the placeholder values (e.g., `"YOUR_EMAIL_HERE"`, `0.00`, `""`) with your calculated answers.

#### **Data Format Rules:**

*   **Numbers:** All numerical values must be formatted as numbers (not strings) with exactly two decimal places (e.g., `1234.56`, `0.00`, `2500.00`).
*   **Strings:** Text values must be enclosed in double quotes.
*   **`affordableOptions` Key:** The value for this key must be one of the following four exact strings: `"Chartify"`, `"DataViz Pro"`, `"Both"`, or `"Neither"`.

---

### **Required JSON Submission Template**

```json
{
  "candidateId": "YOUR_EMAIL_HERE",
  "budgetAnalysis": {
    "varianceReport": [
      {
        "category": "Software Licenses",
        "budgeted": 15000.00,
        "actual": 0.00,
