grading:
An excellent request. Here is a robust Python script, `task_evaluation.py`, designed to automatically evaluate the candidate's submission based on the provided rubric and generate a detailed results file.

This script is built to be resilient, handling potential issues like missing files, malformed JSON, and missing keys in the candidate's submission, ensuring a fair and accurate evaluation every time.

---

### `task_evaluation.py`

```python
import sys
import json
import math

# --- SCORING CONSTANTS BASED ON THE EVALUATION RUBRIC ---

# Points awarded for each correct item
POINTS = {
    'ACTUAL': 4,
    'VARIANCE': 3,
    'VARIANCE_PERCENTAGE': 3,
    'FLAGGED_VENDOR': 10,
    'FLAGGED_AMOUNT': 5,
    'PROJECTED_TOTAL': 15,
    'TOTAL_REMAINING_BUDGET': 10,
    'AFFORDABLE_OPTIONS': 5,
    'REMAINING_BUDGET_AFTER_PURCHASE': 5
}

# Maximum possible score for each section
MAX_SCORES = {
    'VARIANCE_REPORT_CATEGORY': 10,
    'VARIANCE_REPORT': 50,
    'FLAGGED_TRANSACTION': 15,
    'END_OF_QUARTER_FORECAST': 15,
    'DECISION_ANALYSIS': 20
}

# Tolerance for comparing floating-point numbers (e.g., 123.45 vs 123.45001)
# A relative tolerance of 0.5% is used.
FLOAT_TOLERANCE = 0.005

def load_json_file(filepath):
    """Loads a JSON file and returns its content, or exits on error."""
    try:
        with open(filepath, 'r') as f:
            return json.load(f)
    except FileNotFoundError:
        print(f"Error: File not found at '{filepath}'")
        sys.exit(1)
    except json.JSONDecodeError:
        print(f"Error: Could not decode JSON from '{filepath}'. The file may be malformed.")
        sys.exit(1)

def evaluate_variance_report(sub_report, key_report):
    """
    Scores the varianceReport section.
    - 4 points for correct 'actual'.
    - 3 points for 'variance' if calculated correctly based on the candidate's 'actual'.
    - 3 points for 'variancePercentage' if calculated correctly based on the candidate's 'variance'.
    """
    total_score = 0
    details = []

    # Create lookup maps for easy access, handling potential malformed lists
    sub_map = {item.get('category'): item for item in sub_report if isinstance(item, dict)}
    key_map = {item.get('category'): item for item in key_report if isinstance(item, dict)}

    for category, key_item in key_map.items():
        category_score = 0
        sub_item = sub_map.get(category)

        if sub_item and isinstance(sub_item, dict):
            # Score 'actual' against the answer key
            if math.isclose(sub_item.get('actual', -1), key_item.get('actual', -2), rel_tol=FLOAT_TOLERANCE):
                category_score += POINTS['ACTUAL']

            # Score 'variance' based on candidate's 'actual' and key's 'budgeted'
            key_budgeted = key_item.get('budgeted', 0)
            sub_actual = sub_item.get('actual', 0)
            expected_variance = key_budgeted - sub_actual
            if math.isclose(sub_item.get('variance', -1), expected_variance, rel_tol=FLOAT_TOLERANCE):
                category_score += POINTS['VARIANCE']

            # Score 'variancePercentage' based on candidate's 'variance' and key's 'budgeted'
            sub_variance = sub_item.get('variance', 0)
            if key_budgeted != 0:
                expected_percentage = (sub_variance / key_budgeted) * 100
                if math.isclose(sub_item.get('variancePercentage', -1), expected_percentage, rel_tol=FLOAT_TOLERANCE):
                    category_score += POINTS['VARIANCE_PERCENTAGE']
            # Handle edge case where budget is 0
            elif sub_item.get('variancePercentage') == 0:
                category_score += POINTS['VARIANCE_PERCENTAGE']

        details.append({'category': category, 'score': category_score, 'max_score': MAX_SCORES['VARIANCE_REPORT_CATEGORY']})
        total_score += category_score

    return total_score, details

def evaluate_flagged_transaction(sub_flagged, key_flagged):
    """Scores the flaggedTransaction section."""
    score = 0
    if not isinstance(sub_flagged, dict) or not isinstance(key_flagged, dict):
        return 0

    # Score vendor name (case-insensitive comparison)
    if sub_flagged.get('vendor', '').lower() == key_flagged.get('vendor', '').lower():
        score += POINTS['FLAGGED_VENDOR']

    # Score amount
    if math.isclose(sub_flagged.get('amount', -1), key_flagged.get('amount', -2), rel_tol=FLOAT_TOLERANCE):
        score += POINTS['FLAGGED_AMOUNT']

    return score

def evaluate_forecast(sub_forecast, key_forecast):
    """Scores the endOfQuarterForecast section."""
    score = 0
    if not isinstance(sub_forecast, dict) or not isinstance(key_forecast, dict):
        return 0

    if math.isclose(sub_forecast.get('projectedTotal', -1), key_forecast.get('projectedTotal', -2), rel_tol=FLOAT_TOLERANCE):
        score += POINTS['PROJECTED_TOTAL']

    return score

def evaluate_decision(sub_decision, key_decision):
    """Scores the decisionAnalysis section."""
    scores = {
        'totalRemainingBudget': 0,
        'affordableOptions': 0,
        'remainingBudgetAfterPurchase': 0
    }
    if not isinstance(sub_decision, dict) or not isinstance(key_decision, dict):
        return scores

    # Score totalRemainingBudget
    if math.isclose(sub_decision.get('totalRemainingBudget', -1), key_decision.get('totalRemainingBudget', -2), rel_tol=FLOAT_TOLERANCE):
        scores['totalRemainingBudget'] = POINTS['TOTAL_REMAINING_BUDGET']

    # Score affordableOptions (case-insensitive comparison)
    if sub_decision.get('affordableOptions', '').lower() == key_decision.get('affordableOptions', '').lower():
        scores['affordableOptions'] = POINTS['AFFORDABLE_OPTIONS']

    # Score remainingBudgetAfterPurchase
    if math.isclose(sub_decision.get('remainingBudgetAfterPurchase', -1), key_decision.get('remainingBudgetAfterPurchase', -2), rel_tol=FLOAT_TOLERANCE):
        scores['remainingBudgetAfterPurchase'] = POINTS['REMAINING_BUDGET_AFTER_PURCHASE']

    return scores

def main():
    """Main function to run the evaluation script."""
    if len(sys.argv) != 3:
        print("Usage: python task_evaluation.py <submission_file.json> <answer_key_file.json>")
        sys.exit(1)

    submission_file = sys.argv[1]
    answer_key_file = sys.argv[2]

    submission_data = load_json_file(submission_file)
    answer_key_data = load_json_file(answer_key_file)

    # --- Perform Evaluation ---

    # Safely get nested dictionaries
    sub_budget_analysis = submission_data.get('budgetAnalysis', {})
    key_budget_analysis = answer_key_data.get('budgetAnalysis', {})

    vr_score, vr_details = evaluate_variance_report(
        sub_budget_analysis.get('varianceReport', []),
        key_budget_analysis.get('varianceReport', [])
    )

    ft_score = evaluate_flagged_transaction(
        sub_budget_analysis.get('flaggedTransaction', {}),
        key_budget_analysis.get('flaggedTransaction', {})
    )

    f_score = evaluate_forecast(
        submission_data.get('endOfQuarterForecast', {}),
        answer_key_data.get('endOfQuarterForecast', {})
    )

    d_scores = evaluate_decision(
        submission_data.get('decisionAnalysis', {}),
        answer_key_data.get('decisionAnalysis', {})
    )
    d_total_score = sum(d_scores.values())

    # --- Aggregate Results ---

    overall_score = vr_score + ft_score + f_score + d_total_score

    results = {
        "overall_score": float(overall_score),
        "breakdown": {
            "budgetAnalysis": {
                "varianceReport": {
                    "score": float(vr_score),
                    "max_score": MAX_SCORES['VARIANCE_REPORT'],
                    "details": vr_details
                },
                "flaggedTransaction": {
                    "score": float(ft_score),
                    "max_score": MAX_SCORES['FLAGGED_TRANSACTION']
                }
            },
            "endOfQuarterForecast": {
                "projectedTotal": {
                    "score": float(f_score),
                    "max_score": MAX_SCORES['END_OF_QUARTER_FORECAST']
                }
            },
            "decisionAnalysis": {
                "total_score": float(d_total_score),
                "max_score": MAX_SCORES['DECISION_ANALYSIS'],
                "details": {
                    "totalRemainingBudget": {
                        "score": float(d_scores['totalRemainingBudget']),
                        "max_score": POINTS['TOTAL_REMAINING_BUDGET']
                    },
                    "affordableOptions": {
                        "score": float(d_scores['affordableOptions']),
                        "max_score": POINTS['AFFORDABLE_OPTIONS']
                    },
                    "remainingBudgetAfterPurchase": {
                        "score": float(d_scores['remainingBudgetAfterPurchase']),
                        "max_score": POINTS['REMAINING_BUDGET_AFTER_PURCHASE']
                    }
                }
            }
        }
    }

    # --- Save Results to File ---

    output_filename = 'test_results.json'
    with open(output_filename, 'w') as f:
        json.dump(results, f, indent=4)

    print(f"Evaluation complete. Results saved to '{output_filename}'.")
    print(f"Overall Score: {overall_score}/100")

if __name__ == '__main__':
    main()
```

### How to Use the Script

1.  **Save the code:** Save the script above as `task_evaluation.py`.
2.  **Prepare the files:**
    *   Create a candidate submission file, for example, `test_submission.json`.
    *   Create the answer key file, for example, `answer_key.json`, using the correct answers from the `<evaluation_information>` section.
3.  **Run from the command line:** Open your terminal or command prompt, navigate to the folder containing the files, and run the script:
    ```bash
    python task_evaluation.py test_submission.json answer_key.json
    ```
4.  **Check the output:** The script will print the overall score to the console and create a `test_results.json` file in the same directory with a detailed breakdown of the candidate's performance.

