          {"account": "Ending Retained Earnings", "amount": "number"}
        ],
        "total_liabilities_and_equity": "number"
      }
    }
  },
  "financial_analysis": {
    "calculations": [
      {"ratio_name": "Net Profit Margin", "value": "number (2 decimal places)"},
      {"ratio_name": "Current Ratio", "value": "number (2 decimal places)"}
    ],
    "commentary": "string"
  }
}
```

### **Field-Specific Formatting Rules**

1.  **`exam_candidate_id`**:
    *   **Type**: `string`
    *   **Instruction**: Replace `"ENTER_YOUR_EMAIL_HERE"` with your email address.

2.  **Monetary Values (all `amount` and total fields)**:
    *   **Type**: `number`
    *   **Instruction**: All financial figures must be entered as numbers, not text. For example, `25000` is correct; `"25000"` is incorrect.
    *   **Negative Values**: Use a negative sign (`-`) for any values that represent a loss, a subtraction, or a contra-account.
        *   A net loss must be negative (e.g., `-5100`).
        *   `Dividends` on the Statement of Retained Earnings must be entered as a negative number to indicate a reduction.
        *   `Accumulated Depreciation - Equipment` on the Balance Sheet must be entered as a negative number.

3.  **Financial Ratios (`value` fields)**:
    *   **Type**: `number`
    *   **Instruction**: Calculate the ratio and enter the result as a number rounded to **exactly two decimal places**. For example, if your calculation results in `5.6219`, you must enter `5.62`. If the result is `-0.0582`, you must enter `-0.06`.

4.  **`commentary`**:
    *   **Type**: `string`
    *   **Instruction**: Complete the sentence provided in the template. Replace the blank (`____`) with the numerical value of your calculated Current Ratio, rounded to two decimal places. The final string should look like this: `"For every $1.00 of current liabilities, the company has $5.62 of current assets."`

**Final Check:** Before submitting, ensure that the value for `total_assets` exactly equals the value for `total_liabilities_and_equity`. An unbalanced Balance Sheet is a critical error.

grading:
An excellent request. Here is a robust Python script, `task_evaluation.py`, that automatically scores the candidate's submission based on the provided answer key and the detailed evaluation rubric.

This script is designed to be run from the command line and encapsulates all the scoring logic, including checks for internal consistency (e.g., does the candidate's Net Income calculation match their own figures?) and critical links between financial statements.

### `task_evaluation.py`

```python
import json
import sys
import os

class TestEvaluator:
    """
    Evaluates a candidate's practical accounting exam submission against an answer key.
    The scoring is based on a predefined rubric totaling 100 points.
    """

    def __init__(self, submission_path, key_path):
        """
        Initializes the evaluator by loading submission and answer key files.

        Args:
            submission_path (str): The file path for the candidate's submission JSON.
            key_path (str): The file path for the answer key JSON.
        """
        self.submission = self._load_json(submission_path)
        self.key = self._load_json(key_path)
        self.results = {
            "overall_score": 0,
            "candidate_id": self.submission.get("exam_candidate_id", "N/A"),
            "scoring_details": {}
        }
        self.total_score = 0

    def _load_json(self, filepath):
        """Safely loads a JSON file."""
        if not os.path.exists(filepath):
            print(f"Error: File not found at {filepath}")
            sys.exit(1)
        try:
            with open(filepath, 'r') as f:
                return json.load(f)
        except json.JSONDecodeError:
            print(f"Error: Could not decode JSON from {filepath}. Please check the file format.")
            sys.exit(1)
        except Exception as e:
            print(f"An unexpected error occurred while reading {filepath}: {e}")
            sys.exit(1)

    def evaluate(self):
        """
        Runs the full evaluation process by scoring each section of the exam.
        """
        # Evaluate each section and accumulate score
        self._evaluate_income_statement()
        self._evaluate_sre()
        self._evaluate_balance_sheet()
        self._evaluate_analysis()

        self.results["overall_score"] = self.total_score
        return self.results

    def _evaluate_income_statement(self):
        """Scores the Income Statement section (Max 30 points)."""
        score = 0
        breakdown = {}

        sub_is = self.submission['financial_statements']['income_statement']
        key_is = self.key['financial_statements']['income_statement']

        # 1. Revenue (5 points)
        if sub_is['revenues'][0]['amount'] == key_is['revenues'][0]['amount']:
            score += 5
            breakdown['Consulting Revenue'] = "Correct (5/5)"
        else:
            breakdown['Consulting Revenue'] = f"Incorrect (0/5). Submitted: {sub_is['revenues'][0]['amount']}, Expected: {key_is['revenues'][0]['amount']}"

        # 2. Expenses (15 points total, 3 per account)
        sub_expenses = {item['account']: item['amount'] for item in sub_is.get('expenses', [])}
        key_expenses = {item['account']: item['amount'] for item in key_is.get('expenses', [])}

        for account, amount in key_expenses.items():
            if sub_expenses.get(account) == amount:
                score += 3
                breakdown[account] = "Correct (3/3)"
            else:
                breakdown[account] = f"Incorrect (0/3). Submitted: {sub_expenses.get(account)}, Expected: {amount}"

        # 3. Net Income Calculation Check (10 points) - Internal Consistency
        sub_revenue_total = sum(r['amount'] for r in sub_is.get('revenues', []))
        sub_expense_total = sum(e['amount'] for e in sub_is.get('expenses', []))
        calculated_ni = sub_revenue_total - sub_expense_total

        if sub_is.get('net_income') == calculated_ni:
            score += 10
            breakdown['Net Income Calculation'] = "Consistent (10/10)"
        else:
            breakdown['Net Income Calculation'] = f"Inconsistent (0/10). Submitted: {sub_is.get('net_income')}, Calculated from own figures: {calculated_ni}"

        self.total_score += score
        self.results['scoring_details']['income_statement'] = {
            "score": score, "max_score": 30, "breakdown": breakdown
        }

    def _evaluate_sre(self):
        """Scores the Statement of Retained Earnings section (Max 20 points)."""
        score = 0
        breakdown = {}

        sub_sre = self.submission['financial_statements']['statement_of_retained_earnings']
        key_sre = self.key['financial_statements']['statement_of_retained_earnings']
        sub_is_ni = self.submission['financial_statements']['income_statement'].get('net_income')

        # 1. Beginning Retained Earnings (3 points)
        if sub_sre.get('beginning_retained_earnings') == key_sre.get('beginning_retained_earnings'):
            score += 3
            breakdown['Beginning Retained Earnings'] = "Correct (3/3)"
        else:
            breakdown['Beginning Retained Earnings'] = f"Incorrect (0/3). Submitted: {sub_sre.get('beginning_retained_earnings')}, Expected: {key_sre.get('beginning_retained_earnings')}"

        # 2. Net Income Carry-forward (5 points) - Link Check
        if sub_sre.get('net_income') == sub_is_ni:
            score += 5
            breakdown['Net Income Link'] = "Correctly linked (5/5)"
        else:
            breakdown['Net Income Link'] = f"Link broken (0/5). IS Net Income: {sub_is_ni}, SRE Net Income: {sub_sre.get('net_income')}"

        # 3. Dividends (2 points)
        if sub_sre.get('dividends') == key_sre.get('dividends'):
            score += 2
            breakdown['Dividends'] = "Correct (2/2)"
        else:
            breakdown['Dividends'] = f"Incorrect (0/2). Submitted: {sub_sre.get('dividends')}, Expected: {key_sre.get('dividends')}"

        # 4. Ending Retained Earnings Calculation (10 points) - Internal Consistency
        calculated_ere = sub_sre.get('beginning_retained_earnings', 0) + sub_sre.get('net_income', 0) + sub_sre.get('dividends', 0)
        if sub_sre.get('ending_retained_earnings') == calculated_ere:
            score += 10
            breakdown['Ending Retained Earnings Calculation'] = "Consistent (10/10)"
        else:
            breakdown['Ending Retained Earnings Calculation'] = f"Inconsistent (0/10). Submitted: {sub_sre.get('ending_retained_earnings')}, Calculated from own figures: {calculated_ere}"

        self.total_score += score
        self.results['scoring_details']['statement_of_retained_earnings'] = {
            "score": score, "max_score": 20, "breakdown": breakdown
        }

    def _evaluate_balance_sheet(self):
        """Scores the Balance Sheet section (Max 40 points)."""
        score = 0
        breakdown = {}

        sub_bs = self.submission['financial_statements']['balance_sheet']
        key_bs = self.key['financial_statements']['balance_sheet']

        # Helper to convert list of dicts to a dict for easy lookup
        def list_to_dict(items):
            return {item['account']: item['amount'] for item in items}

        # 1. Assets (10 points total, 2 per account)
        sub_assets = {**list_to_dict(sub_bs['assets']['current_assets']), **list_to_dict(sub_bs['assets']['non_current_assets'])}
        key_assets = {**list_to_dict(key_bs['assets']['current_assets']), **list_to_dict(key_bs['assets']['non_current_assets'])}
        for account, amount in key_assets.items():
            if sub_assets.get(account) == amount:
                score += 2
                breakdown[account] = "Correct (2/2)"
            else:
                breakdown[account] = f"Incorrect (0/2). Submitted: {sub_assets.get(account)}, Expected: {amount}"

        # 2. Liabilities & Equity (12 points total, 3 per account)
        sub_le = {**list_to_dict(sub_bs['liabilities_and_equity']['current_liabilities']), **list_to_dict(sub_bs['liabilities_and_equity']['equity'])}
        key_le = {**list_to_dict(key_bs['liabilities_and_equity']['current_liabilities']), **list_to_dict(key_bs['liabilities_and_equity']['equity'])}
        for account, amount in key_le.items():
            if sub_le.get(account) == amount:
                score += 3
                breakdown[account] = "Correct (3/3)"
            else:
                breakdown[account] = f"Incorrect (0/3). Submitted: {sub_le.get(account)}, Expected: {amount}"

        # 3. Total Assets Calculation (5 points) - Internal Consistency
        calculated_total_assets = sum(sub_assets.values())
        if sub_bs['assets'].get('total_assets') == calculated_total_assets:
            score += 5
            breakdown['Total Assets Calculation'] = "Consistent (5/5)"
        else:
            breakdown['Total Assets Calculation'] = f"Inconsistent (0/5). Submitted: {sub_bs['assets'].get('total_assets')}, Calculated: {calculated_total_assets}"

        # 4. Total L&E Calculation (5 points) - Internal Consistency
        calculated_total_le = sum(sub_le.values())
        if sub_bs['liabilities_and_equity'].get('total_liabilities_and_equity') == calculated_total_le:
            score += 5
            breakdown['Total L&E Calculation'] = "Consistent (5/5)"
        else:
            breakdown['Total L&E Calculation'] = f"Inconsistent (0/5). Submitted: {sub_bs['liabilities_and_equity'].get('total_liabilities_and_equity')}, Calculated: {calculated_total_le}"

        # 5. Balance Check (8 points) - Critical Check
        if sub_bs['assets'].get('total_assets') == sub_bs['liabilities_and_equity'].get('total_liabilities_and_equity'):
            score += 8
            breakdown['Balance Sheet Balance'] = "Balanced (8/8)"
        else:
            breakdown['Balance Sheet Balance'] = "Unbalanced (0/8)"

        self.total_score += score
        self.results['scoring_details']['balance_sheet'] = {
            "score": score, "max_score": 40, "breakdown": breakdown
        }

    def _evaluate_analysis(self):
        """Scores the Financial Analysis section (Max 10 points)."""
        score = 0
        breakdown = {}

        sub_an = self.submission['financial_analysis']
        key_an = self.key['financial_analysis']

        sub_ratios = {item['ratio_name']: item['value'] for item in sub_an.get('calculations', [])}
        key_ratios = {item['ratio_name']: item['value'] for item in key_an.get('calculations', [])}

        # 1. Ratios (6 points total, 3 per ratio)
        for name, value in key_ratios.items():
            if sub_ratios.get(name) == value:
                score += 3
                breakdown[name] = "Correct (3/3)"
            else:
                breakdown[name] = f"Incorrect (0/3). Submitted: {sub_ratios.get(name)}, Expected: {value}"

        # 2. Commentary (4 points)
        if sub_an.get('commentary') == key_an.get('commentary'):
            score += 4
            breakdown['Commentary'] = "Correct (4/4)"
        else:
            breakdown['Commentary'] = f"Incorrect (0/4). Submitted: '{sub_an.get('commentary')}', Expected: '{key_an.get('commentary')}'"

        self.total_score += score
        self.results['scoring_details']['financial_analysis'] = {
            "score": score, "max_score": 10, "breakdown": breakdown
        }

    def save_results(self, output_path="test_results.json"):
        """Saves the evaluation results to a JSON file."""
        try:
            with open(output_path, 'w') as f:
                json.dump(self.results, f, indent=4)
            print(f"Evaluation complete. Results saved to {output_path}")
        except Exception as e:
            print(f"Error: Could not save results to {output_path}. Reason: {e}")
            sys.exit(1)


def main():
    """
    Main function to handle command-line arguments and run the evaluation.
    """
    if len(sys.argv) != 3:
        print("Usage: python task_evaluation.py <submission_file.json> <answer_key_file.json>")
        sys.exit(1)

    submission_file = sys.argv[1]
    answer_key_file = sys.argv[2]

    evaluator = TestEvaluator(submission_file, answer_key_file)
    evaluator.evaluate()
    evaluator.save_results()

if __name__ == "__main__":
    main()
```

### How to Use the Script

1.  **Save the code:** Save the Python code above as `task_evaluation.py`.
2.  **Prepare the files:**
    *   Create a file named `test_submission.json` with a candidate's answers. You can use the provided template and fill it in, or even use the correct answer key as a test case to ensure it scores 100%.
    *   Create a file named `answer_key.json` with the correct answers (the "golden file" from the evaluation information).
3.  **Run from the command line:** Open your terminal or command prompt, navigate to the folder containing the three files (`task_evaluation.py`, `test_submission.json`, `answer_key.json`), and run the script:

    ```bash
    python task_evaluation.py test_submission.json answer_key.json
    ```

4.  **Check the output:** The script will create a new file named `test_results.json` in the same folder. This file will contain the candidate's overall score and a detailed breakdown of their performance in each section, making it easy to provide targeted feedback.

