### **`task_evaluation.py`**

```python
import json
import sys
from typing import Dict, Any

def load_json_file(filepath: str) -> Dict[str, Any]:
    """
    Loads a JSON file from the given path and returns its content as a dictionary.
    Handles file not found and JSON decoding errors.
    """
    try:
        with open(filepath, 'r') as f:
            return json.load(f)
    except FileNotFoundError:
        print(f"Error: The file '{filepath}' was not found.")
        sys.exit(1)
    except json.JSONDecodeError:
        print(f"Error: The file '{filepath}' is not a valid JSON file.")
        sys.exit(1)

def evaluate_submission(submission: Dict[str, Any], answer_key: Dict[str, Any]) -> Dict[str, Any]:
    """
    Compares the candidate's submission with the answer key and generates a detailed result.

    Args:
        submission: A dictionary containing the candidate's answers.
        answer_key: A dictionary containing the correct answers.

    Returns:
        A dictionary with the detailed evaluation results and overall score.
    """
    detailed_results = {
        "q1_budget": {},
        "january_variance_analysis": {}
    }
    total_fields = 0
    correct_fields = 0

    # --- Evaluate Q1 Budget ---
    budget_key = "q1_budget"
    for category, months in answer_key.get(budget_key, {}).items():
        detailed_results[budget_key][category] = {}
        for month, expected_value in months.items():
            total_fields += 1
            # Use .get() to safely access potentially missing keys in the submission
            submitted_value = submission.get(budget_key, {}).get(category, {}).get(month, None)

            is_correct = (submitted_value == expected_value)
            if is_correct:
                correct_fields += 1

            detailed_results[budget_key][category][month] = {
                "submitted": submitted_value,
                "expected": expected_value,
                "is_correct": is_correct
            }

    # --- Evaluate January Variance Analysis ---
    variance_key = "january_variance_analysis"
    for category, fields in answer_key.get(variance_key, {}).items():
        detailed_results[variance_key][category] = {}
        for field, expected_value in fields.items():
            total_fields += 1
            submitted_value = submission.get(variance_key, {}).get(category, {}).get(field, None)

            is_correct = (submitted_value == expected_value)
            if is_correct:
                correct_fields += 1

            detailed_results[variance_key][category][field] = {
                "submitted": submitted_value,
                "expected": expected_value,
                "is_correct": is_correct
            }

    # --- Calculate Final Score and Summary ---
    overall_score = (correct_fields / total_fields) * 100 if total_fields > 0 else 0

    final_results = {
        "overall_score": round(overall_score, 2),
        "summary": {
            "total_fields": total_fields,
            "correct_fields": correct_fields,
            "incorrect_fields": total_fields - correct_fields
        },
        "detailed_results": detailed_results
    }

    return final_results

def main():
    """
    Main function to run the evaluation script from the command line.
    """
    # --- Argument Handling ---
    if len(sys.argv) != 3:
        print("Usage: python task_evaluation.py <submission_file.json> <answer_key_file.json>")
        sys.exit(1)

    submission_filepath = sys.argv[1]
    answer_key_filepath = sys.argv[2]

    # --- Load Data ---
    print(f"Loading submission from: {submission_filepath}")
    submission_data = load_json_file(submission_filepath)

    print(f"Loading answer key from: {answer_key_filepath}")
    answer_key_data = load_json_file(answer_key_filepath)

    # --- Perform Evaluation ---
    print("Evaluating submission...")
    results = evaluate_submission(submission_data, answer_key_data)

    # --- Save Results ---
    output_filepath = "test_results.json"
    try:
        with open(output_filepath, 'w') as f:
            json.dump(results, f, indent=4)
        print(f"Evaluation complete. Results saved to '{output_filepath}'")
    except IOError:
        print(f"Error: Could not write results to '{output_filepath}'.")
        sys.exit(1)

if __name__ == "__main__":
    main()
```

### **How to Use the Script**

1.  **Save the script:** Save the code above as a file named `task_evaluation.py`.
2.  **Prepare the files:**
    *   Create a file named `test_submission.json` with the candidate's answers.
    *   Create a file named `answer_key.json` with the correct answers (you can use the JSON from the "Answer Key for Automated Checking" section for this).
    *   Place all three files (`task_evaluation.py`, `test_submission.json`, `answer_key.json`) in the same directory.
3.  **Run from the command line:** Open your terminal or command prompt, navigate to the directory where you saved the files, and run the script with the following command:

    ```bash
    python task_evaluation.py test_submission.json answer_key.json
    ```

4.  **Check the output:** The script will create a new file named `test_results.json` in the same directory. This file will contain the detailed score and a breakdown of the candidate's performance.

