### **`task_evaluation.py`**

```python
import json
import sys
import os

def load_json_file(filepath):
    """
    Loads and parses a JSON file.

    Args:
        filepath (str): The path to the JSON file.

    Returns:
        dict: The parsed JSON data as a Python dictionary.
        None: If the file is not found or contains invalid JSON.
    """
    if not os.path.exists(filepath):
        print(f"Error: File not found at '{filepath}'")
        return None
    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            return json.load(f)
    except json.JSONDecodeError:
        print(f"Error: Could not decode JSON from '{filepath}'. Please ensure it is valid.")
        return None
    except Exception as e:
        print(f"An unexpected error occurred while reading '{filepath}': {e}")
        return None

def compare_values(submitted_val, expected_val):
    """
    Compares a submitted value against an expected value.
    Handles numeric comparison with tolerance for floating point representation.
    """
    if isinstance(expected_val, (int, float)):
        # Ensure submitted value is also numeric before comparison
        if not isinstance(submitted_val, (int, float)):
            return False
        # Compare numeric values. Direct comparison is fine as per spec.
        return submitted_val == expected_val
    # For other types (like strings), use direct comparison
    return submitted_val == expected_val

def evaluate_submission(submission_data, answer_key_data):
    """
    Compares the candidate's submission to the answer key and calculates the score.

    Args:
        submission_data (dict): The candidate's submission data.
        answer_key_data (dict): The correct answer key data.

    Returns:
        dict: A dictionary containing the detailed evaluation results and overall score.
    """
    total_points_achieved = 0
    total_points_possible = 12
    results = {
        "detailed_results": {}
    }

    # --- 1. Evaluate Variance Analysis (6 points) ---
    results["detailed_results"]["variance_analysis_q3"] = []
    sub_variance_map = {item.get('category'): item for item in submission_data.get('variance_analysis_q3', [])}
    key_variance_list = answer_key_data.get('variance_analysis_q3', [])

    for key_item in key_variance_list:
        category = key_item.get('category')
        sub_item = sub_variance_map.get(category, {})
        category_result = {"category": category}

        # Evaluate 'variance'
        sub_var = sub_item.get('variance')
        key_var = key_item.get('variance')
        is_correct_var = compare_values(sub_var, key_var)
        points_var = 1 if is_correct_var else 0
        total_points_achieved += points_var
        category_result['variance'] = {
            "submitted": sub_var, "expected": key_var,
            "is_correct": is_correct_var, "points": points_var
        }

        # Evaluate 'variance_driver_value'
        sub_driver = sub_item.get('variance_driver_value')
        key_driver = key_item.get('variance_driver_value')
        is_correct_driver = compare_values(sub_driver, key_driver)
        points_driver = 1 if is_correct_driver else 0
        total_points_achieved += points_driver
        category_result['variance_driver_value'] = {
            "submitted": sub_driver, "expected": key_driver,
            "is_correct": is_correct_driver, "points": points_driver
        }
        results["detailed_results"]["variance_analysis_q3"].append(category_result)

    # --- 2. Evaluate Budget Preparation (5 points) ---
    results["detailed_results"]["budget_preparation_q4"] = {}
    sub_budget_prep = submission_data.get('budget_preparation_q4', {})
    key_budget_prep = answer_key_data.get('budget_preparation_q4', {})

    for category, key_values in key_budget_prep.items():
        sub_values = sub_budget_prep.get(category, {})

        sub_budget = sub_values.get('calculated_budget')
        key_budget = key_values.get('calculated_budget')

        is_correct = compare_values(sub_budget, key_budget)
        points = 1 if is_correct else 0
        total_points_achieved += points

        results["detailed_results"]["budget_preparation_q4"][category] = {
            "calculated_budget": {
                "submitted": sub_budget, "expected": key_budget,
                "is_correct": is_correct, "points": points
            }
        }

    # --- 3. Evaluate Total Q4 Budget (1 point) ---
    sub_total = submission_data.get('total_q4_budget')
    key_total = answer_key_data.get('total_q4_budget')
    is_correct_total = compare_values(sub_total, key_total)
    points_total = 1 if is_correct_total else 0
    total_points_achieved += points_total
    results["detailed_results"]["total_q4_budget"] = {
        "submitted": sub_total, "expected": key_total,
        "is_correct": is_correct_total, "points": points_total
    }

    # --- 4. Finalize Score ---
    overall_score = (total_points_achieved / total_points_possible) * 100 if total_points_possible > 0 else 0
    results['overall_score'] = round(overall_score, 2)
    results['total_points_achieved'] = total_points_achieved
    results['total_points_possible'] = total_points_possible

    return results

def main():
    """
    Main function to run the evaluation script from the command line.
    """
    if len(sys.argv) != 3:
        print("Usage: python task_evaluation.py <submission_file.json> <answer_key_file.json>")
        sys.exit(1)

    submission_file = sys.argv[1]
    answer_key_file = sys.argv[2]
    output_file = "test_results.json"

    print(f"Loading submission from: {submission_file}")
    submission_data = load_json_file(submission_file)
    if submission_data is None:
        sys.exit(1)

    print(f"Loading answer key from: {answer_key_file}")
    answer_key_data = load_json_file(answer_key_file)
    if answer_key_data is None:
        sys.exit(1)

    print("Evaluating submission...")
    evaluation_results = evaluate_submission(submission_data, answer_key_data)

    try:
        with open(output_file, 'w', encoding='utf-8') as f:
            json.dump(evaluation_results, f, indent=2)
        print(f"Evaluation complete. Results saved to '{output_file}'")
    except Exception as e:
        print(f"Error: Could not write results to '{output_file}'. Reason: {e}")
        sys.exit(1)

if __name__ == "__main__":
    main()
```

### **How to Use the Script**

1.  Save the code above as a file named `task_evaluation.py`.
2.  Place the candidate's submission file (e.g., `test_submission.json`) and the answer key file (e.g., `answer_key.json`) in the same directory as the script.
3.  Open a terminal or command prompt in that directory.
4.  Run the script by providing the submission and answer key files as arguments:

    ```bash
    python task_evaluation.py test_submission.json answer_key.json
    ```

