### **`task_evaluation.py`**

```python
import sys
import json

def load_json_file(filepath):
    """
    Loads and parses a JSON file.
    Handles FileNotFoundError and JSONDecodeError gracefully.
    """
    try:
        with open(filepath, 'r') as f:
            return json.load(f)
    except FileNotFoundError:
        print(f"Error: The file '{filepath}' was not found.")
        sys.exit(1)
    except json.JSONDecodeError:
        print(f"Error: The file '{filepath}' is not a valid JSON file.")
        sys.exit(1)

def compare_and_score(candidate_data, answer_key_data):
    """
    Recursively compares the candidate's data against the answer key.
    Returns a detailed results dictionary, achieved points, and total possible points.
    """
    results = {}
    achieved_points = 0
    total_points = 0

    for key, correct_value in answer_key_data.items():
        # Use .get() to safely access keys that might be missing in the submission
        candidate_value = candidate_data.get(key)

        if isinstance(correct_value, dict):
            # If the value is a dictionary, recurse deeper
            # If the candidate's value for this key isn't a dict, treat it as empty
            nested_candidate_data = candidate_value if isinstance(candidate_value, dict) else {}

            nested_results, nested_achieved, nested_total = compare_and_score(
                nested_candidate_data, correct_value
            )
            results[key] = nested_results
            achieved_points += nested_achieved
            total_points += nested_total
        else:
            # This is a leaf node (a value to be scored)
            total_points += 1
            is_correct = (candidate_value == correct_value)
            if is_correct:
                achieved_points += 1

            results[key] = {
                "candidate_answer": candidate_value,
                "correct_answer": correct_value,
                "is_correct": is_correct
            }

    return results, achieved_points, total_points

def main():
    """
    Main function to run the evaluation script.
    """
    # 1. Check for correct command-line arguments
    if len(sys.argv) != 3:
        print("Usage: python task_evaluation.py <submission_file.json> <answer_key_file.json>")
        sys.exit(1)

    submission_filepath = sys.argv[1]
    answer_key_filepath = sys.argv[2]

    # 2. Load submission and answer key files
    submission_data = load_json_file(submission_filepath)
    answer_key_data = load_json_file(answer_key_filepath)

    # 3. Perform the evaluation by comparing the two data structures
    detailed_results, achieved_points, total_points = compare_and_score(submission_data, answer_key_data)

    # 4. Calculate the overall score as a percentage
    if total_points == 0:
        overall_score = 0.0
    else:
        overall_score = (achieved_points / total_points) * 100

    # 5. Assemble the final results object
    final_results = {
        "overall_score": round(overall_score, 2),
        "summary": {
            "achieved_points": achieved_points,
            "total_points": total_points,
            "passed": overall_score >= 80.0 # Based on a typical 80% pass mark
        },
        "detailed_results": detailed_results
    }

    # 6. Save the results to 'test_results.json'
    output_filename = "test_results.json"
    try:
        with open(output_filename, 'w') as f:
            json.dump(final_results, f, indent=2)
        print(f"Evaluation complete. Results saved to '{output_filename}'")
    except IOError as e:
        print(f"Error: Could not write results to file '{output_filename}'.\n{e}")
        sys.exit(1)

if __name__ == "__main__":
    main()
```

### **How to Use the Script**

1.  **Save the code:** Save the Python code above as `task_evaluation.py`.
2.  **Prepare the files:**
    *   Create a file named `test_submission.json` with the candidate's answers.
    *   Create a file named `answer_key.json` with the correct answers (as provided in the evaluator's guide).
    *   Place all three files (`task_evaluation.py`, `test_submission.json`, `answer_key.json`) in the same directory.
3.  **Run from the command line:** Open a terminal or command prompt, navigate to the directory containing the files, and run the script with the submission and answer key files as arguments:

    ```bash
    python task_evaluation.py test_submission.json answer_key.json
    ```

4.  **Check the output:** The script will create a new file named `test_results.json` in the same directory. This file will contain the detailed score breakdown and the final percentage score.

