```python
import sys
import json

def evaluate_submission(submission_filepath, key_filepath):
    """
    Reads a candidate's submission and an answer key, evaluates the submission,
    and returns a dictionary with the results.

    Args:
        submission_filepath (str): The path to the candidate's submission JSON file.
        key_filepath (str): The path to the answer key JSON file.

    Returns:
        dict: A dictionary containing the evaluation results. If an error occurs
              during file processing, it returns a dictionary with an "error" key.
    """
    try:
        with open(submission_filepath, 'r', encoding='utf-8') as f:
            submission_data = json.load(f)
    except FileNotFoundError:
        return {"error": f"Submission file not found: {submission_filepath}"}
    except json.JSONDecodeError:
        return {"error": f"Invalid JSON in submission file: {submission_filepath}"}

    try:
        with open(key_filepath, 'r', encoding='utf-8') as f:
            key_data = json.load(f)
    except FileNotFoundError:
        return {"error": f"Answer key file not found: {key_filepath}"}
    except json.JSONDecodeError:
        return {"error": f"Invalid JSON in answer key file: {key_filepath}"}

    # --- Data Preparation ---
    # Use the answer key as the source of truth for what needs to be evaluated.
    key_transactions = key_data.get('transaction_analysis', [])

    # Create a dictionary from the candidate's submission for easy lookup.
    # This handles cases where 'transaction_analysis' key might be missing or not a list.
    submission_list = submission_data.get('transaction_analysis', [])
    if not isinstance(submission_list, list):
        submission_list = []

    submission_dict = {
        tx.get('transaction_id'): tx for tx in submission_list if isinstance(tx, dict) and 'transaction_id' in tx
    }

    # --- Evaluation ---
    total_possible_points = 0
    total_achieved_points = 0
    detailed_results = []

    fields_to_compare = [
        'is_compliant', 
        'issue_category', 
        'issue_description', 
        'corrected_amount', 
        'corrected_gl_account'
    ]

    for correct_tx in key_transactions:
        tx_id = correct_tx.get('transaction_id')
        if not tx_id:
            continue # Skip malformed entries in the answer key

        # Get candidate's answer for this transaction_id, or an empty dict if missing
        candidate_tx = submission_dict.get(tx_id, {}) 

        tx_points_achieved = 0
        tx_points_possible = len(fields_to_compare)
        total_possible_points += tx_points_possible

        comparison_details = {}

        for field in fields_to_compare:
            candidate_answer = candidate_tx.get(field) # Use .get() to avoid KeyError
            correct_answer = correct_tx.get(field)
            is_correct = False

            # Special handling for numeric fields to avoid float precision issues
            if field == 'corrected_amount':
                try:
                    # Ensure both are numbers before comparing
                    cand_val = float(candidate_answer) if candidate_answer is not None else None
                    corr_val = float(correct_answer) if correct_answer is not None else None

                    if cand_val is not None and corr_val is not None:
                        if abs(cand_val - corr_val) < 0.01:
                            is_correct = True
                    elif cand_val == corr_val: # Handles case where both are None
                        is_correct = True
                except (ValueError, TypeError):
                    # Candidate provided a non-numeric value or a type that can't be cast to float
                    is_correct = False
            else: # Standard comparison for string fields
                if candidate_answer == correct_answer:
                    is_correct = True

            if is_correct:
                tx_points_achieved += 1

            comparison_details[field] = {
                "candidate_answer": candidate_answer,
                "correct_answer": correct_answer,
                "is_correct": is_correct
            }

        total_achieved_points += tx_points_achieved

        detailed_results.append({
            "transaction_id": tx_id,
            "points_achieved": tx_points_achieved,
            "points_possible": tx_points_possible,
            "comparison": comparison_details
        })

    # --- Final Score Calculation ---
    if total_possible_points > 0:
        overall_score = (total_achieved_points / total_possible_points) * 100
    else:
        overall_score = 0.0

    final_results = {
        "overall_score": round(overall_score, 2),
        "summary": {
            "total_points_achieved": total_achieved_points,
            "total_points_possible": total_possible_points
        },
        "detailed_results": detailed_results
    }

    return final_results

def main():
    """
    Main function to run the script from the command line.
    It expects two arguments: the submission file and the answer key file.
    """
    if len(sys.argv) != 3:
        print("Usage: python task_evaluation.py <submission_file.json> <answer_key_file.json>")
        sys.exit(1)

    submission_filepath = sys.argv[1]
    key_filepath = sys.argv[2]
    output_filepath = "test_results.json"

    results = evaluate_submission(submission_filepath, key_filepath)

    # If evaluation returned an error, print it and exit
    if "error" in results:
        print(f"An error occurred: {results['error']}")
        sys.exit(1)

    try:
        with open(output_filepath, 'w', encoding='utf-8') as f:
            json.dump(results, f, indent=4)
        print(f"Evaluation complete. Results saved to {output_filepath}")
    except IOError as e:
        print(f"Error writing results to file: {e}")
        sys.exit(1)

if __name__ == "__main__":
    main()
```

