```python
import sys
import json

# --- Scoring Configuration ---
# This section translates the evaluation rubric into a machine-readable format.

# The maximum possible score for the entire exam.
MAX_POINTS = 33

# Points awarded for a perfectly correct answer for each field.
POINTS_MAP = {
    "employee_id": 1,
    "performance_category": 3,
    "recommended_action": 3,
    "supporting_quantitative_evidence_code": 2,
    "supporting_qualitative_evidence_code": 2
}

# Defines acceptable alternatives (for partial credit) and explicitly incorrect answers
# (which override other scoring). This captures the nuances of the rubric.
SCORING_RULES = {
    "E101": {
        "recommended_action": {
            "alternatives": {},
            "invalid": {"Recommend for Promotion": 0}
        },
        "supporting_quantitative_evidence_code": {
            "alternatives": {"PD-B-Q4-CloseTime": 1}
        },
        "supporting_qualitative_evidence_code": {
            "alternatives": {"QN-B3": 1}
        }
    },
    "E102": {
        "recommended_action": {
            "alternatives": {}
        },
        "supporting_quantitative_evidence_code": {
            "alternatives": {"PD-C-Q3-Accuracy": 1},
            # Any non-accuracy metric is explicitly wrong, demonstrating poor judgment.
            "invalid": {
                "PD-C-Q3-CloseTime": 0,
                "PD-C-Q4-CloseTime": 0,
                "PD-C-Q3-Reports": 0,
                "PD-C-Q4-Reports": 0
            }
        },
        "supporting_qualitative_evidence_code": {
            "alternatives": {"QN-C3": 1, "QN-C2": 1},
            # The marathon note is irrelevant and should not be chosen.
            "invalid": {"QN-C4": 0}
        }
    },
    "E103": {
        "recommended_action": {
            "alternatives": {"Formal Warning": 1}
        },
        "supporting_quantitative_evidence_code": {
            "alternatives": {"PD-D-Q4-CloseTime": 1, "PD-D-Q4-Reports": 1}
        },
        "supporting_qualitative_evidence_code": {
            "alternatives": {"QN-D4": 1},
            # Choosing the employee's excuse is incorrect.
            "invalid": {"QN-D3": 0}
        }
    }
}

def load_json_file(filepath):
    """Loads and parses a JSON file, with error handling."""
    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            return json.load(f)
    except FileNotFoundError:
        print(f"Error: File not found at {filepath}")
        sys.exit(1)
    except json.JSONDecodeError:
        print(f"Error: Could not decode JSON from {filepath}. Please check for syntax errors.")
        sys.exit(1)

def structure_data_by_employee_id(data_list):
    """Converts a list of employee objects to a dict keyed by employee_id for easy lookup."""
    if not isinstance(data_list, list):
        print("Warning: Submission data is not a list. Scoring may be inaccurate.")
        return {}
    return {item.get('employee_id'): item for item in data_list}

def calculate_field_score(employee_id, field, submitted_value, correct_value):
    """
    Calculates the score for a single field based on the rubric.
    The logic prioritizes:
    1. Explicitly invalid answers (score 0).
    2. Perfectly correct answers (full points).
    3. Acceptable alternatives (partial points).
    """
    rules = SCORING_RULES.get(employee_id, {}).get(field, {})
    invalid_rules = rules.get("invalid", {})
    alternative_rules = rules.get("alternatives", {})

    # 1. Check for explicitly invalid answers first.
    if submitted_value in invalid_rules:
        return invalid_rules[submitted_value]

    # 2. Check for the perfectly correct answer.
    if submitted_value == correct_value:
        return POINTS_MAP.get(field, 0)

    # 3. Check for acceptable alternatives.
    if submitted_value in alternative_rules:
        return alternative_rules[submitted_value]

    # If none of the above, the answer is incorrect.
    return 0

def evaluate_submission(submission_data, key_data):
    """
    Evaluates the candidate's submission against the answer key, generating a detailed
    score report.
    """
    structured_submission = structure_data_by_employee_id(submission_data.get("performance_review_submission", []))
    structured_key = structure_data_by_employee_id(key_data.get("performance_review_submission", []))

    total_score = 0
    results_by_employee = {}

    # Iterate through employees defined in the answer key to ensure all are checked.
    for employee_id, correct_answers in structured_key.items():
        employee_score = 0
        field_results = {}

        candidate_answers = structured_submission.get(employee_id, {})

        # Score each field for the current employee.
        for field, correct_value in correct_answers.items():
            submitted_value = candidate_answers.get(field)

            score = calculate_field_score(employee_id, field, submitted_value, correct_value)

            employee_score += score
            field_results[field] = {
                "score": score,
                "submitted": submitted_value,
                "expected": correct_value
            }

        total_score += employee_score
        results_by_employee[employee_id] = {
            "score": employee_score,
            "max_score": sum(POINTS_MAP.values()),
            "fields": field_results
        }

    # Calculate overall percentage score.
    overall_percentage = (total_score / MAX_POINTS) * 100 if MAX_POINTS > 0 else 0

    final_results = {
        "overall_score": round(overall_percentage, 2),
        "total_points_achieved": total_score,
        "total_points_possible": MAX_POINTS,
        "results_by_employee": results_by_employee
    }

    return final_results

def main():
    """Main function to orchestrate the script execution."""
    if len(sys.argv) != 3:
        print("Usage: python task_evaluation.py <submission_file.json> <answer_key_file.json>")
        sys.exit(1)

    submission_filepath = sys.argv[1]
    key_filepath = sys.argv[2]

    # Load data from files.
    submission_data = load_json_file(submission_filepath)
    key_data = load_json_file(key_filepath)

    # Perform the evaluation.
    results = evaluate_submission(submission_data, key_data)

    # Save the results to a new JSON file.
    output_filepath = "test_results.json"
    try:
        with open(output_filepath, 'w', encoding='utf-8') as f:
            json.dump(results, f, indent=4)
        print(f"Evaluation complete. Results saved to {output_filepath}")
    except IOError as e:
        print(f"Error: Could not write results to {output_filepath}: {e}")
        sys.exit(1)

if __name__ == "__main__":
    main()
```

