### **`task_evaluation.py`**

```python
import sys
import json
import argparse
import math
from pathlib import Path

# --- SCORING CONFIGURATION ---
# This section defines the scoring rules based on the evaluator's guide.
# It can be easily modified if the scoring criteria change.

# Paths to the fields in the JSON structure
PATHS = {
    # Critical Synthesis
    'projected_generation_mwh': 'revenue_calculations.projected_generation_mwh',
    'total_fuel_cost': 'expense_calculations.fuel.total_fuel_cost',
    'net_operating_income': 'q3_summary.net_operating_income',
    'total_maintenance_cost': 'expense_calculations.maintenance.total_maintenance_cost',
    # Core Calculations
    'total_revenue': 'q3_summary.total_revenue',
    'total_operating_expenses': 'q3_summary.total_operating_expenses',
    'total_salaries_cost': 'expense_calculations.salaries.total_salaries_cost',
    'total_consumables_cost': 'expense_calculations.consumables.total_consumables_cost',
}

# Points awarded for each scored item
SCORING_WEIGHTS = {
    'critical_synthesis': {
        'projected_generation_mwh': 15,
        'total_fuel_cost': 15,
        'net_operating_income': 10,
        'total_maintenance_cost': 10,
    },
    'core_calculations': {
        'total_revenue': 10,
        'total_operating_expenses': 10,
        'total_salaries_cost': 5,
        'total_consumables_cost': 5,
    },
    'foundational_inputs': {
        'points_tier': [20, 15, 10, 0],  # For 0, 1-2, 3-4, >4 errors
        'fields': [
            'revenue_calculations.plant_capacity_mw',
            'revenue_calculations.total_hours_in_q3',
            'revenue_calculations.projected_availability_percent',
            'revenue_calculations.ppa_rate_per_mwh',
            'expense_calculations.fuel.baseline_fuel_efficiency_tonnes_per_mwh',
            'expense_calculations.fuel.new_fuel_cost_per_tonne',
            'expense_calculations.maintenance.baseline_q3_maintenance_cost',
            'expense_calculations.maintenance.additional_overhaul_cost',
            'expense_calculations.salaries.baseline_q3_salaries_cost',
            'expense_calculations.salaries.inflation_adjustment_percent',
            'expense_calculations.consumables.baseline_q3_consumables_cost',
            'expense_calculations.consumables.inflation_adjustment_percent',
        ]
    }
}

# --- HELPER FUNCTIONS ---

def get_nested_value(data, path):
    """
    Safely retrieves a value from a nested dictionary using a dot-separated path.
    Returns None if the path is invalid or a key is missing.
    """
    keys = path.split('.')
    value = data
    try:
        for key in keys:
            value = value[key]
        return value
    except (KeyError, TypeError):
        return None

def compare_values(submitted_val, correct_val):
    """
    Compares two values, handling None and using math.isclose for floats.
    An absolute tolerance of 0.01 is used to account for rounding.
    """
    if submitted_val is None or correct_val is None:
        return False
    if isinstance(submitted_val, (int, float)) and isinstance(correct_val, (int, float)):
        return math.isclose(submitted_val, correct_val, abs_tol=0.01)
    return submitted_val == correct_val

# --- EVALUATION LOGIC ---

def evaluate_submission(submission_data, key_data):
    """
    Evaluates the candidate's submission against the answer key.
    Returns a dictionary with the detailed results and the overall score.
    """
    results = {
        'candidate_name': get_nested_value(submission_data, 'candidate_name') or 'N/A',
        'overall_score': 0.0,
        'score_details': {}
    }
    total_score = 0

    # --- Category A & B: Direct Scoring ---
    for category, items in [('critical_synthesis', SCORING_WEIGHTS['critical_synthesis']),
                            ('core_calculations', SCORING_WEIGHTS['core_calculations'])]:

        category_score = 0
        category_max_points = sum(items.values())
        category_breakdown = {}

        for item_name, points in items.items():
            path = PATHS[item_name]
            submitted_value = get_nested_value(submission_data, path)
            correct_value = get_nested_value(key_data, path)

            points_awarded = points if compare_values(submitted_value, correct_value) else 0
            category_score += points_awarded

            category_breakdown[item_name] = {
                'submitted': submitted_value,
                'correct': correct_value,
                'points': float(points_awarded)
            }

        results['score_details'][category] = {
            'points_awarded': float(category_score),
            'max_points': float(category_max_points),
            'breakdown': category_breakdown
        }
        total_score += category_score

    # --- Category C: Foundational Inputs (Tiered Scoring) ---
    category = 'foundational_inputs'
    error_count = 0
    category_breakdown = {}

    for path in SCORING_WEIGHTS[category]['fields']:
        submitted_value = get_nested_value(submission_data, path)
        correct_value = get_nested_value(key_data, path)

        is_correct = compare_values(submitted_value, correct_value)
        if not is_correct:
            error_count += 1

        category_breakdown[path] = {
            'submitted': submitted_value,
            'correct': correct_value,
            'status': 'Correct' if is_correct else 'Incorrect'
        }

    # Apply tiered scoring
    if error_count == 0:
        points_awarded = SCORING_WEIGHTS[category]['points_tier'][0]
    elif 1 <= error_count <= 2:
        points_awarded = SCORING_WEIGHTS[category]['points_tier'][1]
    elif 3 <= error_count <= 4:
        points_awarded = SCORING_WEIGHTS[category]['points_tier'][2]
    else:
        points_awarded = SCORING_WEIGHTS[category]['points_tier'][3]

    total_score += points_awarded

    results['score_details'][category] = {
        'points_awarded': float(points_awarded),
        'max_points': float(SCORING_WEIGHTS[category]['points_tier'][0]),
        'error_count': error_count,
        'breakdown': category_breakdown
    }

    results['overall_score'] = float(total_score)
    return results

# --- MAIN EXECUTION ---

def main():
    """
    Main function to parse arguments, run the evaluation, and save the results.
    """
    parser = argparse.ArgumentParser(
        description="Evaluate a candidate's JSON submission against an answer key."
    )
    parser.add_argument(
        "submission_file",
        type=Path,
        help="Path to the candidate's submission JSON file (e.g., test_submission.json)"
    )
    parser.add_argument(
        "key_file",
        type=Path,
        help="Path to the answer key JSON file (e.g., answer_key.json)"
    )
    args = parser.parse_args()

    # --- Load Files ---
    try:
        with open(args.submission_file, 'r') as f:
            submission_data = json.load(f)
    except (FileNotFoundError, json.JSONDecodeError) as e:
        print(f"Error reading submission file '{args.submission_file}': {e}", file=sys.stderr)
        sys.exit(1)

    try:
        with open(args.key_file, 'r') as f:
            key_data = json.load(f)
    except (FileNotFoundError, json.JSONDecodeError) as e:
        print(f"Error reading key file '{args.key_file}': {e}", file=sys.stderr)
        sys.exit(1)

    # --- Run Evaluation ---
    evaluation_results = evaluate_submission(submission_data, key_data)

    # --- Save Results ---
    output_file = Path('test_results.json')
    try:
        with open(output_file, 'w') as f:
            json.dump(evaluation_results, f, indent=2)
        print(f"Evaluation complete. Results saved to '{output_file}'")
    except IOError as e:
        print(f"Error writing results to '{output_file}': {e}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()
```

