```python
import json
import argparse
import sys
import math

# Define the scoring rubric based on the evaluation information.
# Total points add up to 100.
SCORING_RUBRIC = {
    "statistical_metrics": {
        "total_active_employees": 25,
        "new_hires": 15,
        "absenteeism_rate_pct": 30,
        "average_performance_score": 15,
    },
    "data_integrity": {
        "unmatched_update_records": 15,
    }
}

def load_json_file(filepath):
    """
    Loads a JSON file from the given path.
    Handles file not found and JSON decoding errors.
    """
    try:
        with open(filepath, 'r') as f:
            return json.load(f)
    except FileNotFoundError:
        print(f"Error: The file '{filepath}' was not found.", file=sys.stderr)
        sys.exit(1)
    except json.JSONDecodeError:
        print(f"Error: The file '{filepath}' is not a valid JSON file.", file=sys.stderr)
        sys.exit(1)

def evaluate_submission(submission_data, answer_key_data):
    """
    Compares the submission data against the answer key using the scoring rubric.

    Args:
        submission_data (dict): The candidate's submission data.
        answer_key_data (dict): The correct answer key data.

    Returns:
        dict: A dictionary containing the overall score and detailed results.
    """
    total_points_awarded = 0
    detailed_results = {
        "statistical_metrics": {},
        "data_integrity": {}
    }

    # Iterate through the main categories in the rubric (e.g., "statistical_metrics")
    for category, metrics in SCORING_RUBRIC.items():
        # Iterate through each specific metric in the category (e.g., "total_active_employees")
        for metric, points_possible in metrics.items():

            # Safely get candidate and correct answers to avoid KeyErrors
            candidate_answer = submission_data.get(category, {}).get(metric)
            correct_answer = answer_key_data.get(category, {}).get(metric)

            is_correct = False
            # Check for None to handle missing keys gracefully in the submission
            if candidate_answer is not None:
                # Use math.isclose for floating-point comparisons to handle precision issues.
                # Use direct equality for integers and other types.
                if isinstance(correct_answer, float):
                    # Ensure candidate answer is also a number before comparing
                    if isinstance(candidate_answer, (int, float)):
                        is_correct = math.isclose(candidate_answer, correct_answer, rel_tol=1e-9, abs_tol=1e-5)
                else:
                    is_correct = (candidate_answer == correct_answer)

            points_awarded = points_possible if is_correct else 0
            total_points_awarded += points_awarded

            # Store detailed results for this specific metric
            detailed_results[category][metric] = {
                "candidate_answer": candidate_answer,
                "correct_answer": correct_answer,
                "is_correct": is_correct,
                "points_awarded": points_awarded,
                "points_possible": points_possible
            }

    # The overall score is the sum of points, as the total is 100.
    final_report = {
        "overall_score": float(total_points_awarded),
        "detailed_results": detailed_results
    }
    return final_report

def main():
    """
    Main function to parse arguments, run the evaluation, and save the results.
    """
    parser = argparse.ArgumentParser(
        description="Evaluate a candidate's JSON submission against an answer key."
    )
    parser.add_argument(
        "submission_file",
        help="The path to the candidate's submission JSON file."
    )
    parser.add_argument(
        "answer_key_file",
        help="The path to the answer key JSON file."
    )
    args = parser.parse_args()

    # Load the data from the provided file paths
    submission_data = load_json_file(args.submission_file)
    answer_key_data = load_json_file(args.answer_key_file)

    # Perform the evaluation
    results = evaluate_submission(submission_data, answer_key_data)

    # Save the results to a new JSON file
    output_filename = "test_results.json"
    try:
        with open(output_filename, 'w') as f:
            json.dump(results, f, indent=4)
        print(f"Evaluation complete. Results saved to '{output_filename}'.")
    except IOError as e:
        print(f"Error: Could not write results to '{output_filename}'.\n{e}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()
```

