An excellent request. Here is the Python script `task_evaluation.py` designed to automatically evaluate the candidate's submission based on the provided scoring rubric.

### **Python Script: `task_evaluation.py`**

```python
import sys
import json

# --- Constants from the Evaluation Rubric ---
MAX_TOTAL_POINTS = 20
MAX_BUDGET_POINTS = 2
MAX_DECISION_POINTS_PER_ITEM = 3
INITIAL_FUNDS = {
    '101-SUP': 1500,
    '102-IM': 4000,
    '201-TECH': 2500
}

def evaluate_budget_summary(submission_data, answer_key_data):
    """
    Evaluates the budget_summary section of the submission.
    Scores 2 points for a perfect match, 1 for arithmetic consistency, 0 otherwise.
    """
    try:
        sub_summary = submission_data['budget_summary']
        key_summary = answer_key_data['budget_summary']
        sub_decisions = submission_data['allocation_decisions']

        correct_allocated = key_summary['total_allocated']
        correct_remaining = key_summary['final_remaining_balance']

        submitted_allocated = sub_summary['total_allocated']
        submitted_remaining = sub_summary['final_remaining_balance']

        if submitted_allocated == correct_allocated and submitted_remaining == correct_remaining:
            return {
                "points_achieved": 2,
                "comment": "Correct."
            }

        # Check for arithmetic consistency if not a perfect match
        calculated_allocated = sum(d.get('allocated_amount', 0) for d in sub_decisions)
        calculated_remaining = sub_summary.get('total_budget_available', 8000) - calculated_allocated

        if submitted_allocated == calculated_allocated and submitted_remaining == calculated_remaining:
            return {
                "points_achieved": 1,
                "comment": "Values are arithmetically consistent with the allocation decisions, but do not match the optimal solution."
            }

        return {
            "points_achieved": 0,
            "comment": "Values are incorrect and arithmetically inconsistent with the allocation decisions."
        }
    except (KeyError, TypeError) as e:
        return {
            "points_achieved": 0,
            "comment": f"Error processing budget_summary: Missing or invalid key. Details: {e}"
        }


def evaluate_allocation_decisions(submission_data, answer_key_data):
    """
    Evaluates each allocation decision based on the detailed rubric.
    Tracks a running budget to detect overspending errors.
    """
    results = {
        "points_achieved": 0,
        "max_points": 18,
        "details": []
    }

    try:
        sub_decisions = submission_data['allocation_decisions']
        key_decisions_map = {d['request_id']: d for d in answer_key_data['allocation_decisions']}

        # Sort submission to ensure deterministic evaluation order
        sorted_sub_decisions = sorted(sub_decisions, key=lambda x: x.get('request_id', ''))

        # Make a copy of initial funds to track depletion
        remaining_funds = INITIAL_FUNDS.copy()

        for c_dec in sorted_sub_decisions:
            req_id = c_dec.get('request_id')
            if not req_id or req_id not in key_decisions_map:
                results['details'].append({
                    "request_id": req_id or "Unknown",
                    "points_achieved": 0,
                    "max_points": MAX_DECISION_POINTS_PER_ITEM,
                    "comment": "Invalid or missing request_id."
                })
                continue

            a_dec = key_decisions_map[req_id]
            points = 0
            comment = ""
            is_fundamental_error = False

            # --- Check for 0-Point Fundamental Errors ---
            # 1. Overspending
            if c_dec.get('allocated_amount', 0) > 0:
                fund = c_dec.get('funding_source')
                amount = c_dec.get('allocated_amount')
                if fund in remaining_funds:
                    if remaining_funds[fund] < amount:
                        is_fundamental_error = True
                        comment = f"Fundamental Error: Decision causes overspending in fund {fund} (tried to spend {amount} with only {remaining_funds[fund]} available)."
                else:
                    is_fundamental_error = True
                    comment = f"Fundamental Error: Invalid funding source '{fund}' used for an allocation."

            # 2. Specific policy violations
            if not is_fundamental_error:
                if req_id == '005' and c_dec.get('decision') != 'Denied':
                    is_fundamental_error = True
                    comment = "Fundamental Error: Approved a non-priority item (beanbag chairs)."
                elif req_id in ['001', '006'] and c_dec.get('decision') == 'Denied':
                    is_fundamental_error = True
                    comment = f"Fundamental Error: Denied a critical operational need (request {req_id})."
                elif req_id == '004' and c_dec.get('decision') != 'Denied':
                    is_fundamental_error = True
                    comment = "Fundamental Error: Approved the kiln, which is unfundable and/or misaligned with priorities."

            # --- Assign Points Based on Checks ---
            if is_fundamental_error:
                points = 0
            else:
                # 3-Point: Perfect Match
                if c_dec == a_dec:
                    points = 3
                    comment = "Correct."
                # 2-Point: Minor Error (Correct decision type, wrong details)
                elif c_dec.get('decision') == a_dec.get('decision'):
                    points = 2
                    comment = "Minor Error: The main decision (e.g., 'Approved', 'Denied') was correct, but one or more details (amount, fund, justification) were incorrect."
                # 1-Point: Major Error (Wrong decision type, but not a fundamental error)
                else:
                    points = 1
                    comment = "Major Error: The decision was incorrect but did not constitute a fundamental violation of budget rules."

            # Update running budget *after* scoring the decision
            if not is_fundamental_error and c_dec.get('allocated_amount', 0) > 0:
                fund = c_dec.get('funding_source')
                amount = c_dec.get('allocated_amount')
                remaining_funds[fund] -= amount

            results['points_achieved'] += points
            results['details'].append({
                "request_id": req_id,
                "points_achieved": points,
                "max_points": MAX_DECISION_POINTS_PER_ITEM,
                "comment": comment
            })

    except (KeyError, TypeError) as e:
        # Handle malformed submission file
        results['comment'] = f"Error processing allocation_decisions: Missing or invalid key. Details: {e}"

    return results


def main():
    """
    Main function to run the evaluation script from the command line.
    """
    if len(sys.argv) != 3:
        print("Usage: python task_evaluation.py <submission_file.json> <answer_key_file.json>")
        sys.exit(1)

    submission_file = sys.argv[1]
    answer_key_file = sys.argv[2]
    output_file = "test_results.json"

    try:
        with open(submission_file, 'r') as f:
            submission_data = json.load(f)
        with open(answer_key_file, 'r') as f:
            answer_key_data = json.load(f)
    except FileNotFoundError as e:
        print(f"Error: File not found - {e.filename}")
        sys.exit(1)
    except json.JSONDecodeError as e:
        print(f"Error: Invalid JSON format in file. Details: {e}")
        sys.exit(1)

    # --- Perform Evaluation ---
    budget_results = evaluate_budget_summary(submission_data, answer_key_data)
    decision_results = evaluate_allocation_decisions(submission_data, answer_key_data)

    total_points_achieved = budget_results['points_achieved'] + decision_results['points_achieved']
    overall_score_percentage = (total_points_achieved / MAX_TOTAL_POINTS) * 100

    # --- Assemble Final Results ---
    final_results = {
        "overall_score": round(overall_score_percentage, 2),
        "total_points_achieved": total_points_achieved,
        "maximum_points": MAX_TOTAL_POINTS,
        "breakdown": {
            "budget_summary": {
                "points_achieved": budget_results['points_achieved'],
                "max_points": MAX_BUDGET_POINTS,
                "comment": budget_results['comment']
            },
            "allocation_decisions": decision_results
        }
    }

    # --- Save Results to File ---
    try:
        with open(output_file, 'w') as f:
            json.dump(final_results, f, indent=4)
        print(f"Evaluation complete. Results saved to '{output_file}'.")
    except IOError as e:
        print(f"Error: Could not write results to file. Details: {e}")
        sys.exit(1)


if __name__ == "__main__":
    main()
```

### **How to Use the Script**

1.  **Save the script:** Save the code above as a file named `task_evaluation.py`.
2.  **Prepare the files:**
    *   Create a file named `test_submission.json` with the candidate's submission.
    *   Create a file named `answer_key.json` with the ideal solution provided in the `<evaluation_information>` section.
3.  **Run from the command line:** Open a terminal or command prompt, navigate to the folder containing the three files, and run the script:

    ```bash
    python task_evaluation.py test_submission.json answer_key.json
    ```

4.  **Check the output:** The script will create a new file, `test_results.json`, in the same folder. This file will contain the detailed scoring breakdown and the final percentage score. For example, if the candidate submitted the perfect answer, the output file would look like this:

    **`test_results.json` (Example Output for a Perfect Score)**
