An excellent request. Here is the Python script `task_evaluation.py` that automates the scoring of the practical exam based on the provided rubric.

### `task_evaluation.py`

```python
import sys
import json

# --- Constants based on the Evaluation Rubric ---
PASSING_THRESHOLD = 80

# Points allocation
POINTS = {
    'problem_concern': 5,
    'problem_metric': 10,
    'problem_gap': 10,
    'personnel_id': 20,
    'personnel_qual': 15,
    'rec_action': 15,
    'rec_grant': 5,
    'rec_impact': 5,
    'rec_plan_step': 5, # 5 points per step
}

# --- Helper Functions ---

def load_json_file(filepath):
    """Loads a JSON file and returns its content, or None on error."""
    try:
        with open(filepath, 'r') as f:
            return json.load(f)
    except FileNotFoundError:
        print(f"Error: File not found at {filepath}")
        return None
    except json.JSONDecodeError:
        print(f"Error: Could not decode JSON from {filepath}")
        return None

def check_keywords(text, keywords, required_count=1):
    """Checks if a given text contains a minimum number of keywords."""
    if not isinstance(text, str):
        return False

    count = 0
    text_lower = text.lower()
    for keyword in keywords:
        if keyword in text_lower:
            count += 1
    return count >= required_count

# --- Scoring Functions ---

def score_problem_identification(submission, key):
    """Scores the 'problem_identification' section."""
    score = 0
    feedback = {}

    # Score primary_area_of_concern (5 points)
    concern_score = 0
    concern_text = submission.get('problem_identification', {}).get('primary_area_of_concern', '')
    if check_keywords(concern_text, ['k-2', 'literacy', 'foundational', 'reading'], required_count=2):
        concern_score = POINTS['problem_concern']
        comment = "Correctly identified the core problem in K-2 literacy."
    elif check_keywords(concern_text, ['reading', 'literacy']):
        concern_score = 3 # Partial credit as per rubric
        comment = "Vaguely identified a reading issue but missed the specific K-2 focus."
    else:
        comment = "Did not correctly identify the primary area of concern."
    feedback['primary_area_of_concern'] = {'score': concern_score, 'max_score': POINTS['problem_concern'], 'comment': comment}
    score += concern_score

    # Score greatest_performance_gap (20 points total)
    sub_gap = submission.get('problem_identification', {}).get('greatest_performance_gap', {})
    key_gap = key.get('problem_identification', {}).get('greatest_performance_gap', {})

    # Metric (10 points)
    metric_score = POINTS['problem_metric'] if sub_gap.get('metric') == key_gap.get('metric') else 0
    feedback['greatest_performance_gap_metric'] = {
        'score': metric_score, 'max_score': POINTS['problem_metric'],
        'comment': "Correct." if metric_score > 0 else f"Incorrect. Expected '{key_gap.get('metric')}'."
    }
    score += metric_score

    # Gap Value (10 points)
    gap_score = POINTS['problem_gap'] if sub_gap.get('gap_value') == key_gap.get('gap_value') else 0
    feedback['greatest_performance_gap_value'] = {
        'score': gap_score, 'max_score': POINTS['problem_gap'],
        'comment': "Correct." if gap_score > 0 else f"Incorrect. Expected {key_gap.get('gap_value')}."
    }
    score += gap_score

    return score, feedback

def score_personnel_analysis(submission, key):
    """Scores the 'personnel_analysis' section."""
    score = 0
    feedback = {}

    # Score selected_staff_id (20 points)
    staff_id_score = 0
    sub_staff_id = submission.get('personnel_analysis', {}).get('selected_staff_id')
    key_staff_id = key.get('personnel_analysis', {}).get('selected_staff_id')

    if sub_staff_id == key_staff_id: # Correct choice: S03
        staff_id_score = POINTS['personnel_id']
        comment = "Excellent choice. Identified the ideal internal candidate with the right qualifications."
    elif sub_staff_id == "S01": # Overworked specialist
        staff_id_score = 5
        comment = "Identified a qualified specialist but missed the context about their existing high workload."
    elif sub_staff_id == "S02": # Seniority trap
        staff_id_score = 0
        comment = "Incorrect. Prioritized seniority over specific, required qualifications for the task."
    else:
        comment = "Incorrect staff member selected."
    feedback['selected_staff_id'] = {'score': staff_id_score, 'max_score': POINTS['personnel_id'], 'comment': comment}
    score += staff_id_score

    # Score key_qualification_from_roster (15 points)
    qual_score = 0
    sub_qual = submission.get('personnel_analysis', {}).get('key_qualification_from_roster', '')

    if sub_qual in ["K-12 Reading Specialist", "Science of Reading Bootcamp 2022"]:
        qual_score = POINTS['personnel_qual']
        comment = "Correctly identified a key, relevant qualification."
    elif sub_qual == "K-6 General":
        qual_score = 5
        comment = "Identified a general qualification, but not the specific one that makes the candidate ideal."
    else:
        comment = "Did not identify a relevant qualification."
    feedback['key_qualification_from_roster'] = {'score': qual_score, 'max_score': POINTS['personnel_qual'], 'comment': comment}
    score += qual_score

    return score, feedback

def score_recommendation(submission, key):
    """Scores the 'recommendation' section."""
    score = 0
    feedback = {}

    # Score recommended_action (15 points)
    action_score = 0
    sub_action = submission.get('recommendation', {}).get('recommended_action')
    if sub_action == "Reassignment with Stipend":
        action_score = POINTS['rec_action']
        comment = "Correct. This is the most logical and budget-conscious action."
    elif sub_action == "Professional Development for All Staff":
        action_score = 5
        comment = "A plausible but less targeted action than required by the data."
    elif sub_action == "New Hire":
        action_score = 0
        comment = "Incorrect. This action ignores the significant budget constraint of $5,000."
    else:
        comment = "The recommended action is not the optimal choice."
    feedback['recommended_action'] = {'score': action_score, 'max_score': POINTS['rec_action'], 'comment': comment}
    score += action_score

    # Score grant_allocation_description (5 points)
    grant_desc = submission.get('recommendation', {}).get('grant_allocation_description', '')
    grant_score = POINTS['rec_grant'] if check_keywords(grant_desc, ['stipend']) else 0
    feedback['grant_allocation_description'] = {
        'score': grant_score, 'max_score': POINTS['rec_grant'],
        'comment': "Correctly described the use of the grant." if grant_score > 0 else "Did not specify the grant would be used for a stipend."
    }
    score += grant_score

    # Score impact_on_previous_role (5 points)
    impact_desc = submission.get('recommendation', {}).get('impact_on_previous_role', '')
    impact_score = POINTS['rec_impact'] if check_keywords(impact_desc, ['vacancy', '1st grade', 'first grade', 'fill']) else 0
    feedback['impact_on_previous_role'] = {
        'score': impact_score, 'max_score': POINTS['rec_impact'],
        'comment': "Correctly identified the resulting vacancy." if impact_score > 0 else "Failed to identify the operational impact (i.e., the 1st-grade vacancy)."
    }
    score += impact_score

    # Score implementation_plan (15 points)
    plan_score = 0
    plan_feedback = {}
    sub_plan = submission.get('recommendation', {}).get('implementation_plan', {})

    # Step 1
    step1_text = sub_plan.get('step_1', '')
    step1_score = POINTS['rec_plan_step'] if check_keywords(step1_text, ['meet', 'discuss', 'talk', 'sarah', 'davis', 's03']) else 0
    plan_feedback['step_1'] = {'score': step1_score, 'max_score': POINTS['rec_plan_step'], 'comment': "Logical first step." if step1_score > 0 else "First step is not logical or is missing."}
    plan_score += step1_score

    # Step 2
    step2_text = sub_plan.get('step_2', '')
    step2_score = POINTS['rec_plan_step'] if check_keywords(step2_text, ['hr', 'human resources', 'process', 'payment']) else 0
    plan_feedback['step_2'] = {'score': step2_score, 'max_score': POINTS['rec_plan_step'], 'comment': "Logical second step." if step2_score > 0 else "Second step is not logical or is missing."}
    plan_score += step2_score

    # Step 3
    step3_text = sub_plan.get('step_3', '')
    step3_score = POINTS['rec_plan_step'] if check_keywords(step3_text, ['post', 'vacancy', 'hiring', 'backfill']) else 0
    plan_feedback['step_3'] = {'score': step3_score, 'max_score': POINTS['rec_plan_step'], 'comment': "Logical third step." if step3_score > 0 else "Third step is not logical or is missing."}
    plan_score += step3_score

    feedback['implementation_plan'] = {'total_score': plan_score, 'details': plan_feedback}
    score += plan_score

    return score, feedback

# --- Main Execution ---

def main():
    """Main function to run the evaluation script."""
    if len(sys.argv) != 3:
        print("Usage: python task_evaluation.py <submission_file.json> <answer_key_file.json>")
        sys.exit(1)

    submission_file = sys.argv[1]
    key_file = sys.argv[2]

    submission_data = load_json_file(submission_file)
    key_data = load_json_file(key_file)

    if submission_data is None or key_data is None:
        sys.exit(1)

    # Initialize results structure
    results = {
        "candidate_name": submission_data.get("candidate_name", "N/A"),
        "overall_score": 0,
        "pass_status": "Fail",
        "scoring_details": {}
    }
    total_score = 0

    # Score each section
    problem_score, problem_feedback = score_problem_identification(submission_data, key_data)
    total_score += problem_score
    results["scoring_details"]["problem_identification"] = {
        "score": problem_score, "max_score": 25, "feedback": problem_feedback
    }

    personnel_score, personnel_feedback = score_personnel_analysis(submission_data, key_data)
    total_score += personnel_score
    results["scoring_details"]["personnel_analysis"] = {
        "score": personnel_score, "max_score": 35, "feedback": personnel_feedback
    }

    rec_score, rec_feedback = score_recommendation(submission_data, key_data)
    total_score += rec_score
    results["scoring_details"]["recommendation"] = {
        "score": rec_score, "max_score": 40, "feedback": rec_feedback
    }

    # Finalize overall score and pass status
    results["overall_score"] = total_score
    if total_score >= PASSING_THRESHOLD:
        results["pass_status"] = "Pass"

    # Save results to file
    output_filename = "test_results.json"
    with open(output_filename, 'w') as f:
        json.dump(results, f, indent=4)

    print(f"Evaluation complete. Results saved to {output_filename}")
    print(f"Candidate: {results['candidate_name']}")
    print(f"Final Score: {results['overall_score']}/100")
    print(f"Status: {results['pass_status']}")

if __name__ == "__main__":
    main()
```

### How to Run the Script

1.  **Save the code:** Save the script above as `task_evaluation.py`.
2.  **Prepare the files:** Make sure you have the candidate's submission (e.g., `test_submission.json`) and the `answer_key.json` in the same directory.
3.  **Execute from the command line:** Open your terminal or command prompt, navigate to the directory containing the files, and run the script with the submission and key files as arguments.

