An excellent choice for a practical evaluation. Here is the Python script `task_evaluation.py` that automates the scoring process based on the provided criteria.

### **`task_evaluation.py`**

```python
import sys
import json
import math

# --- Constants from the evaluation criteria ---
MAX_SCORE_BUDGET = 24
MAX_SCORE_FLAGS = 48
MAX_SCORE_SUMMARY = 28
TOTAL_MAX_SCORE = MAX_SCORE_BUDGET + MAX_SCORE_FLAGS + MAX_SCORE_SUMMARY

def load_json_file(filepath):
    """Loads a JSON file and returns its content, or an error message if it fails."""
    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            return json.load(f), None
    except FileNotFoundError:
        return None, f"Error: File not found at '{filepath}'."
    except json.JSONDecodeError:
        return None, f"Error: Invalid JSON format in '{filepath}'. Submission is ungradable."

def compare_values(a, b, is_numeric=False):
    """
    Compares two values. Uses math.isclose for numeric types with a tolerance
    for floating point inaccuracies (e.g., currency).
    """
    if is_numeric:
        try:
            # A tolerance of 0.01 is suitable for currency (1 cent)
            return math.isclose(float(a), float(b), rel_tol=1e-9, abs_tol=0.01)
        except (ValueError, TypeError):
            return False
    else:
        return a == b

def score_budget_analysis(submission_data, key_data):
    """Scores the 'budget_analysis' section based on the provided rubric."""
    score = 0
    details = []

    sub_analysis = {item.get('category'): item for item in submission_data.get('budget_analysis', []) if item.get('category')}
    key_analysis = key_data.get('budget_analysis', [])

    for key_item in key_analysis:
        category = key_item.get('category')
        item_score = 0
        status = "Missing or Incorrect"

        sub_item = sub_analysis.get(category)
        if sub_item:
            actual_correct = compare_values(sub_item.get('actual_amount'), key_item.get('actual_amount'), is_numeric=True)
            variance_correct = compare_values(sub_item.get('variance'), key_item.get('variance'), is_numeric=True)

            if actual_correct and variance_correct:
                item_score = 3
                status = "Correct"
            elif actual_correct:
                item_score = 1.5
                status = "Partially Correct (Actual amount correct, variance incorrect)"

        score += item_score
        details.append({
            "category": category,
            "points_awarded": item_score,
            "status": status
        })

    return score, details

def score_flagged_transactions(submission_data, key_data):
    """Scores the 'flagged_transactions' section, allowing for partial credit."""
    score = 0
    details = []

    # Create a mutable copy to track which submission flags have been matched
    sub_flags = list(submission_data.get('flagged_transactions', []))
    key_flags = key_data.get('flagged_transactions', [])

    for key_flag in key_flags:
        key_id = key_flag.get('transaction_id')
        item_score = 0
        status = "Not Found"

        match_found = False
        for i, sub_flag in enumerate(sub_flags):
            if sub_flag.get('transaction_id') == key_id:
                # Found a match by ID, now score it based on the rubric
                item_score += 4  # 4 points for correct transaction_id

                if sub_flag.get('reason_for_flag') == key_flag.get('reason_for_flag'):
                    item_score += 4
                if sub_flag.get('recommended_action') == key_flag.get('recommended_action'):
                    item_score += 4

                if item_score == 12:
                    status = "Correct"
                else:
                    status = f"Partially Correct (ID found, but details are wrong)"

                # Remove the matched item so it can't be scored again
                sub_flags.pop(i)
                match_found = True
                break  # Move to the next key_flag

        score += item_score
        details.append({
            "transaction_id": key_id,
            "points_awarded": item_score,
            "status": status
        })

    return score, details

def score_financial_summary(submission_data, key_data):
    """Scores the 'financial_summary' section."""
    score = 0
    details = {}

    sub_summary = submission_data.get('financial_summary', {})
    key_summary = key_data.get('financial_summary', {})

    fields_to_score = {
        "total_budgeted": {"points": 4, "is_numeric": True},
        "total_actual": {"points": 6, "is_numeric": True},
        "net_variance": {"points": 6, "is_numeric": True},
        "largest_overspend_category": {"points": 6, "is_numeric": False},
        "largest_overspend_amount": {"points": 6, "is_numeric": True}
    }

    for field, criteria in fields_to_score.items():
        sub_value = sub_summary.get(field)
        key_value = key_summary.get(field)

        if compare_values(sub_value, key_value, is_numeric=criteria["is_numeric"]):
            points_awarded = criteria["points"]
            status = "Correct"
        else:
            points_awarded = 0
            status = "Incorrect"

        score += points_awarded
        details[field] = {"points_awarded": points_awarded, "status": status}

    return score, details

def main():
    """Main function to orchestrate the evaluation script."""
    if len(sys.argv) != 3:
        print("Usage: python task_evaluation.py <submission_file.json> <answer_key_file.json>")
        sys.exit(1)

    submission_file = sys.argv[1]
    answer_key_file = sys.argv[2]
    output_file = "test_results.json"

    # Load submission and answer key files
    submission_data, sub_error = load_json_file(submission_file)
    answer_key_data, key_error = load_json_file(answer_key_file)

    # Critical error if the answer key is missing or invalid
    if key_error:
        print(key_error)
        sys.exit(1)

    # If submission is invalid, score as 0 and exit
    if sub_error:
        results = {
            "overall_score": 0,
            "scoring_details": {
                "prerequisite_check": {
                    "status": "FAIL",
                    "message": sub_error
                }
            }
        }
        with open(output_file, 'w', encoding='utf-8') as f:
            json.dump(results, f, indent=2)
        print(f"Evaluation failed due to invalid submission file. See {output_file} for details.")
        sys.exit(1)

    # --- Begin Scoring ---
    total_score = 0
    results = {
        "scoring_details": {
            "prerequisite_check": {
                "status": "PASS",
                "message": "Submission file is a valid JSON."
            }
        }
    }

    # Score Budget Analysis
    budget_score, budget_details = score_budget_analysis(submission_data, answer_key_data)
    total_score += budget_score
    results["scoring_details"]["budget_analysis"] = {
        "score": budget_score,
        "max_score": MAX_SCORE_BUDGET,
        "details": budget_details
    }

    # Score Flagged Transactions
    flags_score, flags_details = score_flagged_transactions(submission_data, answer_key_data)
    total_score += flags_score
    results["scoring_details"]["flagged_transactions"] = {
        "score": flags_score,
        "max_score": MAX_SCORE_FLAGS,
        "details": flags_details
    }

    # Score Financial Summary
    summary_score, summary_details = score_financial_summary(submission_data, answer_key_data)
    total_score += summary_score
    results["scoring_details"]["financial_summary"] = {
        "score": summary_score,
        "max_score": MAX_SCORE_SUMMARY,
        "details": summary_details
    }

    # Finalize overall score (out of 100)
    results["overall_score"] = total_score

    # Write results to the output file
    with open(output_file, 'w', encoding='utf-8') as f:
        json.dump(results, f, indent=2)

    print(f"Evaluation complete. Results saved to {output_file}.")
    print(f"Overall Score: {total_score}/{TOTAL_MAX_SCORE}")

if __name__ == "__main__":
    main()
```

An excellent choice. Automating the evaluation of this practical exam ensures consistency and efficiency. Here is the Python script `task_evaluation.py` that implements the provided scoring rubric.

### `task_evaluation.py`

```python
import sys
import json
from datetime import datetime, timedelta

# --- Helper Functions ---

def parse_time(time_str: str):
    """Parses an HH:MM string to a datetime.time object, handling potential errors."""
    try:
        return datetime.strptime(time_str, "%H:%M").time()
    except (ValueError, TypeError):
        return None

def get_shift_duration_hours(start_str: str, end_str: str) -> float:
    """Calculates shift duration in hours, handling overnight shifts."""
    try:
        start = datetime.strptime(start_str, "%H:%M")
        end = datetime.strptime(end_str, "%H:%M")
        if end < start:  # Handles shifts crossing midnight, e.g., 22:00-02:00
            end += timedelta(days=1)
        return (end - start).total_seconds() / 3600
    except (ValueError, TypeError):
        return 0.0

# --- Main Evaluation Class ---

class ExamEvaluator:
    """
    Evaluates a candidate's submission against an answer key based on a predefined rubric.
    """
    def __init__(self, submission_data: dict, answer_key_data: dict):
        self.submission = submission_data
        self.answer_key = answer_key_data
        self.results = {}
        self.score = 0
        # Staff roles are fixed for this exam context
        self.staff_roles = {
            "LD01": "Licensed Funeral Director",
            "LD02": "Licensed Funeral Director",
            "FA01": "Funeral Assistant",
            "FA02": "Funeral Assistant",
            "OC01": "On-Call Removal Tech"
        }

    def run_evaluation(self):
        """Executes all scoring methods and returns the final results."""
        self.score_json_format()
        self.score_office_coverage()
        self.score_hard_constraints()
        self.score_staffing_levels()
        self.score_break_policy()
        self.score_labor_cost()
        self.score_proficiency()

        self.results['overall_score'] = self.score
        return self.results

    # --- Scoring Methods based on the Rubric ---

    def score_json_format(self):
        points = 0
        max_points = 5
        feedback = []

        required_keys = ["weekly_schedule", "uncovered_shifts", "scheduling_notes", "total_estimated_hourly_labor_cost"]
        missing_keys = [key for key in required_keys if key not in self.submission]

        if missing_keys:
            feedback.append(f"Submission JSON is missing top-level keys: {', '.join(missing_keys)}")
        else:
            required_days = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"]
            schedule = self.submission.get("weekly_schedule", {})
            missing_days = [day for day in required_days if day not in schedule]
            if missing_days:
                feedback.append(f"weekly_schedule is missing days: {', '.join(missing_days)}")
            else:
                points = max_points
                feedback.append("JSON structure is valid.")

        self.score += points
        self.results['category_6_json_format'] = {
            "points_awarded": points,
            "max_points": max_points,
            "feedback": feedback
        }

    def score_office_coverage(self):
        points = 0
        max_points = 30
        feedback = []
        days_to_check = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday"]
        covered_days_count = 0

        schedule = self.submission.get("weekly_schedule", {})

        for day in days_to_check:
            day_covered = False
            for shift in schedule.get(day, []):
                emp_id = shift.get("employee_id")
                role = self.staff_roles.get(emp_id)
                task = shift.get("task", "").lower()

                if role == "Licensed Funeral Director" and "office coverage" in task:
                    shift_start = parse_time(shift.get("shift_start"))
                    shift_end = parse_time(shift.get("shift_end"))
                    if shift_start and shift_end and shift_start <= parse_time("09:00") and shift_end >= parse_time("17:00"):
                        day_covered = True
                        break

            if day_covered:
                covered_days_count += 1
            else:
                feedback.append(f"Missing required 9-5 'Office Coverage' by a Licensed Director on {day}.")

        if covered_days_count == len(days_to_check):
            points = max_points
            feedback.append("All weekday 'Office Coverage' shifts correctly scheduled.")
        else:
            feedback.append("Critical 'Office Coverage' requirement not met. This is an automatic fail condition.")

        self.score += points
        self.results['category_1_office_coverage'] = {
            "points_awarded": points,
            "max_points": max_points,
            "feedback": feedback
        }

    def score_hard_constraints(self):
        points = 0
        max_points = 20
        feedback = []

        # Constraint 1: Wednesday Evening Visitation (10 points)
        visitation_shifts = [s for s in self.submission.get("weekly_schedule", {}).get("Wednesday", []) if "visitation" in s.get("task", "").lower()]
        ld_on_visitation = [s.get("employee_id") for s in visitation_shifts if self.staff_roles.get(s.get("employee_id")) == "Licensed Funeral Director"]
        if not ld_on_visitation:
            feedback.append("No Licensed Director scheduled for Wednesday 'Visitation'.")
        elif "LD01" in ld_on_visitation:
            feedback.append("Incorrectly scheduled LD01 for Wednesday evening; LD01 is unavailable.")
        elif "LD02" in ld_on_visitation:
            points += 10
            feedback.append("Correctly scheduled LD02 for Wednesday evening visitation.")

        # Constraint 2: Chloe's (FA02) Availability (10 points)
        chloe_ok = True
        for day in ["Monday", "Tuesday", "Thursday"]:
            for shift in self.submission.get("weekly_schedule", {}).get(day, []):
                if shift.get("employee_id") == "FA02":
                    shift_start, shift_end = parse_time(shift.get("shift_start")), parse_time(shift.get("shift_end"))
                    if shift_start and shift_end and max(shift_start, parse_time("09:00")) < min(shift_end, parse_time("12:00")):
                        chloe_ok = False
                        feedback.append(f"Incorrectly scheduled FA02 (Chloe) on {day} during her unavailable time (9:00-12:00).")
                        break
            if not chloe_ok: break
        if chloe_ok:
            points += 10
            feedback.append("Correctly respected FA02 (Chloe's) availability constraints.")

        self.score += points
        self.results['category_2_hard_constraints'] = {"points_awarded": points, "max_points": max_points, "feedback": feedback}

    def score_staffing_levels(self):
        points = 0
        max_points = 15
        feedback = []
        schedule = self.submission.get("weekly_schedule", {})

        def check_staffing(day, start_time, end_time, expected_ld, expected_fa):
            ld, fa = 0, 0
            event_start, event_end = parse_time(start_time), parse_time(end_time)
            for shift in schedule.get(day, []):
                shift_start, shift_end = parse_time(shift.get("shift_start")), parse_time(shift.get("shift_end"))
                if shift_start and shift_end and max(shift_start, event_start) < min(shift_end, event_end):
                    role = self.staff_roles.get(shift.get("employee_id"))
                    if role == "Licensed Funeral Director": ld += 1
                    elif role == "Funeral Assistant": fa += 1
            return ld == expected_ld and fa == expected_fa, ld, fa

        # Graveside & Visitation (5 pts total)
        gs_ok, gs_ld, gs_fa = check_staffing("Monday", "14:00", "16:00", 1, 1)
        if gs_ok: points += 2.5; feedback.append("Correct staffing (1 LD, 1 FA) for Graveside Service.")
        else: feedback.append(f"Incorrect staffing for Graveside Service. Found {gs_ld} LD(s), {gs_fa} FA(s); expected 1 LD, 1 FA.")

        v_ok, v_ld, v_fa = check_staffing("Wednesday", "18:00", "21:00", 1, 1)
        if v_ok: points += 2.5; feedback.append("Correct staffing (1 LD, 1 FA) for Visitation.")
        else: feedback.append(f"Incorrect staffing for Visitation. Found {v_ld} LD(s), {v_fa} FA(s); expected 1 LD, 1 FA.")

        # Funeral Service (10 pts)
        fs_ok, fs_ld, fs_fa = check_staffing("Friday", "11:00", "17:30", 1, 2)
        if fs_ok: points += 10; feedback.append("Correct staffing (1 LD, 2 FAs) for Funeral Service.")
        else: feedback.append(f"Incorrect staffing for Funeral Service. Found {fs_ld} LD(s), {fs_fa} FA(s); expected 1 LD, 2 FAs.")

        self.score += points
        self.results['category_3_staffing_levels'] = {"points_awarded": points, "max_points": max_points, "feedback": feedback}

    def score_break_policy(self):
        points = 0
        max_points = 15
        feedback = []

        # Office Coverage Breaks (10 pts)
        office_break_pts = 0
        for day in ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday"]:
            for shift in self.submission.get("weekly_schedule", {}).get(day, []):
                if "office coverage" in shift.get("task", "").lower():
                    duration = get_shift_duration_hours(shift.get("shift_start"), shift.get("shift_end"))
                    if duration > 6 and shift.get("unpaid_break_minutes") == 30:
                        office_break_pts += 2
                    elif duration > 6:
                        feedback.append(f"Incorrect break for >6hr 'Office Coverage' on {day}. Expected 30, found {shift.get('unpaid_break_minutes')}.")
                    break
        points += office_break_pts
        if office_break_pts == 10: feedback.append("Correctly applied breaks to all weekday office shifts.")

        # Friday Funeral Breaks (5 pts)
        funeral_shifts = [s for s in self.submission.get("weekly_schedule", {}).get("Friday", []) if "funeral" in s.get("task", "").lower()]
        if len(funeral_shifts) == 3:
            correct_breaks = sum(1 for s in funeral_shifts if get_shift_duration_hours(s.get("shift_start"), s.get("shift_end")) > 6 and s.get("unpaid_break_minutes") == 30)
            if correct_breaks == 3:
                points += 5
                feedback.append("Correctly applied breaks to all staff for the Friday Funeral Service.")
            else:
                feedback.append(f"Incorrect breaks for Friday Funeral Service: {correct_breaks}/3 staff had correct breaks.")
        else:
            feedback.append("Could not assess Friday Funeral breaks due to incorrect number of staff scheduled.")

        self.score += points
        self.results['category_4_break_policy'] = {"points_awarded": points, "max_points": max_points, "feedback": feedback}

    def score_labor_cost(self):
        points = 0
        max_points = 10
        feedback = []

        submitted_cost = self.submission.get("total_estimated_hourly_labor_cost")
        optimal_cost = self.answer_key.get("total_estimated_hourly_labor_cost")

        if not isinstance(submitted_cost, (int, float)):
            feedback.append("Submitted labor cost is not a valid number.")
        else:
            if submitted_cost == optimal_cost:
                points = 10
                feedback.append(f"Submitted labor cost ${submitted_cost:.2f} is exactly correct.")
            elif abs(submitted_cost - optimal_cost) <= (optimal_cost * 0.02):
                points = 5
                feedback.append(f"Submitted labor cost ${submitted_cost:.2f} is within 2% of the optimal cost ${optimal_cost:.2f}.")
            else:
                feedback.append(f"Submitted labor cost ${submitted_cost:.2f} is not within 2% of the optimal cost ${optimal_cost:.2f}.")

        self.score += points
        self.results['category_5_labor_cost'] = {"points_awarded": points, "max_points": max_points, "feedback": feedback}

    def score_proficiency(self):
        points = 0
        max_points = 5
        feedback = []

        # Notes check (2.5 pts)
        notes = self.submission.get("scheduling_notes", "")
        if isinstance(notes, str) and len(notes.strip()) > 10:
            points += 2.5
            feedback.append("Provided clear scheduling notes.")
        else:
            feedback.append("Scheduling notes were missing or insufficient.")

        # Cost optimization check (2.5 pts)
        mon_office_shift = next((s for s in self.submission.get("weekly_schedule", {}).get("Monday", []) if "office coverage" in s.get("task", "").lower()), None)
        if mon_office_shift and mon_office_shift.get("employee_id") == "LD02":
            points += 2.5
            feedback.append("Demonstrated cost-optimization by using lower-cost staff where appropriate.")
        else:
            feedback.append("Did not demonstrate cost-optimization (e.g., used more expensive staff on Monday).")

        self.score += points
        self.results['category_7_proficiency'] = {"points_awarded": points, "max_points": max_points, "feedback": feedback}

# --- Main Script Execution ---

def main():
    """Main function to run the evaluation from the command line."""
    if len(sys.argv) != 3:
        print("Usage: python task_evaluation.py <submission_file.json> <answer_key_file.json>")
        sys.exit(1)

    submission_file = sys.argv[1]
    answer_key_file = sys.argv[2]

    try:
        with open(submission_file, 'r') as f:
            submission_data = json.load(f)
    except FileNotFoundError:
        print(f"Error: Submission file not found at '{submission_file}'")
        sys.exit(1)
    except json.JSONDecodeError:
        results = {
            "overall_score": 0,
            "error": "Candidate submission is not a valid JSON file.",
            "category_6_json_format": {
                "points_awarded": 0, "max_points": 5, "feedback": ["File is not valid JSON."]
            }
        }
        with open('test_results.json', 'w') as f:
            json.dump(results, f, indent=2)
        print("Evaluation complete. Results for invalid JSON saved to test_results.json")
        sys.exit(0)

    try:
        with open(answer_key_file, 'r') as f:
            answer_key_data = json.load(f)
    except FileNotFoundError:
        print(f"Error: Answer key file not found at '{answer_key_file}'")
        sys.exit(1)
    except json.JSONDecodeError:
        print(f"Error: Answer key file '{answer_key_file}' is not valid JSON.")
        sys.exit(1)

    evaluator = ExamEvaluator(submission_data, answer_key_data)
    results = evaluator.run_evaluation()

    with open('test_results.json', 'w') as f:
        json.dump(results, f, indent=2)

    print("Evaluation complete. Results saved to test_results.json")

if __name__ == "__main__":
    main()
```

An excellent request. Here is the Python script `task_evaluation.py` designed to automatically evaluate the candidate's submission against the provided answer key.

This script implements the scoring logic and critical failure conditions outlined in the evaluation information, providing a detailed, automated, and objective assessment of the candidate's performance.

---

### `task_evaluation.py`

```python
import sys
import json
from collections import Counter

def load_json_file(filepath):
    """Loads a JSON file and returns its content, or None if an error occurs."""
    try:
        with open(filepath, 'r') as f:
            return json.load(f)
    except FileNotFoundError:
        print(f"Error: File not found at {filepath}")
        return None
    except json.JSONDecodeError:
        print(f"Error: Could not decode JSON from {filepath}. Check for syntax errors.")
        return None

def sort_list_of_dicts(list_of_dicts, sort_key):
    """Sorts a list of dictionaries by a specified key for consistent comparison."""
    if not list_of_dicts or not isinstance(list_of_dicts, list):
        return []
    return sorted(list_of_dicts, key=lambda x: x.get(sort_key, ''))

def evaluate_submission(submission_data, key_data):
    """
    Evaluates the candidate's submission against the answer key.

    Returns a dictionary with the detailed results and overall score.
    """
    results = {
        "overall_score": 0,
        "critical_checks": {
            "ineligible_employee_scheduled": {"passed": True, "details": "No ineligible employees were scheduled."},
            "sick_employee_scheduled": {"passed": True, "details": "The employee who called out sick was correctly excluded from the schedule."},
            "correct_roulette_dealer": {"passed": True, "details": "The correctly skilled dealer was assigned to the Roulette table."},
            "minimum_staffing_maintained": {"passed": True, "details": "Minimum staffing levels were maintained by correctly forgoing breaks."}
        },
        "detailed_scores": {
            "shift_schedule_composition": {"score": 0, "max_score": 25, "details": "Evaluation pending."},
            "station_arrangement_logic": {"score": 0, "max_score": 25, "details": "Evaluation pending."},
            "attendance_log_accuracy": {"score": 0, "max_score": 25, "details": "Evaluation pending."},
            "shift_summary_accuracy": {"score": 0, "max_score": 25, "details": "Evaluation pending."}
        }
    }

    critical_failure = False

    # --- 1. CRITICAL CHECKS ---
    # If any of these fail, the final score will be 0.

    # Get scheduled employee IDs from submission
    scheduled_employees = submission_data.get('shift_schedule', [])
    scheduled_ids = {e.get('employee_id') for e in scheduled_employees}

    # Check 1: Ineligible employees scheduled (Time off, wrong availability)
    ineligible_ids = {'D101', 'D103', 'D106'}
    scheduled_ineligible = scheduled_ids.intersection(ineligible_ids)
    if scheduled_ineligible:
        critical_failure = True
        results["critical_checks"]["ineligible_employee_scheduled"]["passed"] = False
        results["critical_checks"]["ineligible_employee_scheduled"]["details"] = f"Critical Error: Ineligible employee(s) {list(scheduled_ineligible)} were scheduled."

    # Check 2: Sick employee scheduled
    sick_id = 'D102'
    if sick_id in scheduled_ids:
        critical_failure = True
        results["critical_checks"]["sick_employee_scheduled"]["passed"] = False
        results["critical_checks"]["sick_employee_scheduled"]["details"] = f"Critical Error: Employee {sick_id}, who called out sick, was scheduled."

    # Check 3: Correct Roulette dealer
    roulette_dealer_id = key_data['shift_summary']['roulette_dealer_id']
    if submission_data.get('shift_summary', {}).get('roulette_dealer_id') != roulette_dealer_id:
        critical_failure = True
        results["critical_checks"]["correct_roulette_dealer"]["passed"] = False
        results["critical_checks"]["correct_roulette_dealer"]["details"] = f"Critical Error: Roulette table (T4) was not assigned to the only qualified dealer ({roulette_dealer_id})."

    # Check 4: Minimum staffing maintained (by forgoing breaks)
    break_keys = {'break_1_start', 'break_1_duration_mins', 'break_2_start', 'break_2_duration_mins'}
    for employee in scheduled_employees:
        if any(key in employee for key in break_keys):
            critical_failure = True
            results["critical_checks"]["minimum_staffing_maintained"]["passed"] = False
            results["critical_checks"]["minimum_staffing_maintained"]["details"] = "Critical Error: Breaks were scheduled, which violates the minimum staffing rule with only 3 dealers available."
            break

    # --- 2. DETAILED SCORING ---
    # This section only runs if no critical failures were detected.
    if not critical_failure:
        total_score = 0

        # Score: Shift Schedule Composition (25 points)
        key_scheduled_ids = {e['employee_id'] for e in key_data['shift_schedule']}
        if scheduled_ids == key_scheduled_ids:
            results["detailed_scores"]["shift_schedule_composition"]["score"] = 25
            results["detailed_scores"]["shift_schedule_composition"]["details"] = "Correct set of employees scheduled for the shift."
        else:
            results["detailed_scores"]["shift_schedule_composition"]["details"] = f"Incorrect set of employees scheduled. Expected {sorted(list(key_scheduled_ids))}, but got {sorted(list(scheduled_ids))}."

        # Score: Station Arrangement (25 points)
        # For this basic exam, we expect a direct match with the key's simple structure.
        sub_arrangement = submission_data.get('station_arrangement', [])
        key_arrangement = key_data.get('station_arrangement', [])

        # Normalize by sorting inner assignment lists for comparison
        for slot in sub_arrangement:
            slot['assignments'] = sort_list_of_dicts(slot.get('assignments', []), 'table_id')

        if sub_arrangement == key_arrangement:
            results["detailed_scores"]["station_arrangement_logic"]["score"] = 25
            results["detailed_scores"]["station_arrangement_logic"]["details"] = "Station arrangement is correct, with proper table coverage and dealer assignments."
        else:
            results["detailed_scores"]["station_arrangement_logic"]["details"] = "Station arrangement is incorrect. It does not match the optimal assignment of dealers to tables."

        # Score: Attendance Log (25 points)
        sub_log = sort_list_of_dicts(submission_data.get('attendance_log', []), 'employee_id')
        key_log = sort_list_of_dicts(key_data.get('attendance_log', []), 'employee_id')
        if sub_log == key_log:
            results["detailed_scores"]["attendance_log_accuracy"]["score"] = 25
            results["detailed_scores"]["attendance_log_accuracy"]["details"] = "Attendance log is accurate and complete."
        else:
            results["detailed_scores"]["attendance_log_accuracy"]["details"] = "Attendance log is incorrect or incomplete."

        # Score: Shift Summary (25 points)
        sub_summary = submission_data.get('shift_summary', {})
        key_summary = key_data.get('shift_summary', {})
        # Normalize list within summary for comparison
        if 'unstaffed_tables_for_shift' in sub_summary:
            sub_summary['unstaffed_tables_for_shift'].sort()

        if sub_summary == key_summary:
            results["detailed_scores"]["shift_summary_accuracy"]["score"] = 25
            results["detailed_scores"]["shift_summary_accuracy"]["details"] = "Shift summary is accurate."
        else:
            results["detailed_scores"]["shift_summary_accuracy"]["details"] = "Shift summary contains incorrect data."

        # Calculate total score
        for category in results["detailed_scores"].values():
            total_score += category["score"]
        results["overall_score"] = total_score

    return results

def main():
    """Main function to run the evaluation script."""
    if len(sys.argv) != 3:
        print("Usage: python task_evaluation.py <submission_file.json> <answer_key_file.json>")
        sys.exit(1)

    submission_path = sys.argv[1]
    key_path = sys.argv[2]

    submission_data = load_json_file(submission_path)
    key_data = load_json_file(key_path)

    if submission_data is None or key_data is None:
        sys.exit(1)

    # Perform evaluation
    results = evaluate_submission(submission_data, key_data)

    # Save results to file
    try:
        with open('test_results.json', 'w') as f:
            json.dump(results, f, indent=2)
        print("Evaluation complete. Results saved to 'test_results.json'.")
    except IOError:
        print("Error: Could not write results to 'test_results.json'.")
        sys.exit(1)

if __name__ == "__main__":
    main()
```

### How to Use the Script

1.  **Save the code:** Save the Python code above as a file named `task_evaluation.py`.
2.  **Prepare the files:**
    *   Place the candidate's submission file (e.g., `test_submission.json`) in the same directory.
    *   Place the correct answer key file (e.g., `answer_key.json`) in the same directory. The content for the answer key should be taken from the `<evaluation_information>` section.
3.  **Run from the command line:** Open a terminal or command prompt, navigate to the directory containing the files, and run the script with the submission and key files as arguments:

    ```bash
    python task_evaluation.py test_submission.json answer_key.json
    ```

4.  **Check the output:** The script will print a confirmation message to the console and create a new file named `test_results.json` in the same folder.

