```python
import json
import sys
import os

def evaluate_submission(submission_file, key_file):
    """
    Compares a candidate's submission JSON file to an answer key JSON file
    and generates a detailed results JSON file.
    """
    # --- 1. Load JSON data from files ---
    try:
        with open(submission_file, 'r') as f:
            submission_data = json.load(f)
        with open(key_file, 'r') as f:
            answer_key_data = json.load(f)
    except FileNotFoundError as e:
        print(f"Error: File not found - {e.filename}")
        sys.exit(1)
    except json.JSONDecodeError as e:
        print(f"Error: Invalid JSON format in file. Details: {e}")
        sys.exit(1)

    # --- 2. Convert lists to dictionaries for efficient lookup by playerID ---
    # This handles cases where the candidate's submission is not in the same order as the key.
    try:
        submission_dict = {item['playerID']: item for item in submission_data}
        answer_key_dict = {item['playerID']: item for item in answer_key_data}
    except (TypeError, KeyError):
        print("Error: Input JSON files must be a list of objects, each with a 'playerID' key.")
        sys.exit(1)


    # --- 3. Compare submission against the key ---
    detailed_results = []
    correct_count = 0
    total_items = len(answer_key_dict)

    for player_id, correct_answer in answer_key_dict.items():
        submitted_answer = submission_dict.get(player_id)
        result_item = {
            "playerID": player_id,
            "is_correct": False,
            "submitted_answer": submitted_answer,
            "correct_answer": correct_answer,
            "discrepancies": []
        }

        if not submitted_answer:
            result_item["discrepancies"].append({
                "issue": "Record for this playerID was not found in the submission."
            })
        else:
            # The evaluation rule states the entire object must be a perfect match.
            # We can do a direct comparison of the dictionaries.
            if submitted_answer == correct_answer:
                result_item["is_correct"] = True
                correct_count += 1
            else:
                # If not a perfect match, find the specific differences for feedback.
                for key, correct_value in correct_answer.items():
                    submitted_value = submitted_answer.get(key)
                    if submitted_value != correct_value:
                        result_item["discrepancies"].append({
                            "field": key,
                            "submitted_value": submitted_value,
                            "correct_value": correct_value
                        })
                # Check for extra keys in submission that are not in the key
                for key in submitted_answer:
                    if key not in correct_answer:
                        result_item["discrepancies"].append({
                            "issue": f"Extra field '{key}' found in submission."
                        })


        detailed_results.append(result_item)

    # --- 4. Calculate overall score ---
    if total_items > 0:
        overall_score = (correct_count / total_items) * 100
    else:
        overall_score = 0.0

    final_results = {
        "overall_score": round(overall_score, 2),
        "summary": {
            "correct_records": correct_count,
            "total_records": total_items,
            "incorrect_records": total_items - correct_count
        },
        "detailed_results": detailed_results
    }

    # --- 5. Save results to a new JSON file ---
    output_filename = 'test_results.json'
    with open(output_filename, 'w') as f:
        json.dump(final_results, f, indent=2)

    print(f"Evaluation complete. Results saved to '{output_filename}'")


if __name__ == "__main__":
    # --- Argument Handling ---
    if len(sys.argv) != 3:
        print("Usage: python task_evaluation.py <submission_file.json> <answer_key_file.json>")
        sys.exit(1)

    submission_filepath = sys.argv[1]
    answer_key_filepath = sys.argv[2]

    evaluate_submission(submission_filepath, answer_key_filepath)
```

