          "assigned_role": "string",
          "primary_duty": "string"
        }
      ]
    },
    "Saturday": {
      "Morning": [],
      "Evening": [],
      "Night": []
    },
    "Sunday": {
      "Morning": [],
      "Evening": [],
      "Night": []
    }
  },
  "decision_points": {
    "decision_1_friday_evening_front_desk": 0,
    "decision_2_saturday_evening_second_front_desk": 0
  }
}
```

#### **3. Important Conventions**

*   **Arrays for Shifts**: Each shift (e.g., `"Morning"`) must have a value that is a JSON array `[]`.
*   **Multiple Employees**: If a shift requires more than one employee, add multiple JSON objects `{...}` inside the corresponding shift's array, separated by commas.
*   **Empty Shifts**: If a particular shift does not require any staff (e.g., no housekeepers are needed for an evening shift), the array for that shift must be empty (`[]`).
*   **No Supplementary Files**: No other files should be submitted. All answers must be contained within the `test_submission.json` file.
*   **No Extra Keys**: Do not add any keys or properties to the JSON structure that are not specified in the template.

