An excellent request. Here is the Python script `task_evaluation.py` that automatically scores the candidate's submission based on the provided answer key and evaluation criteria.

### Python Script: `task_evaluation.py`

```python
import sys
import json

# --- Configuration ---
# This reflects the scoring rubric provided in the evaluation information.
SCORING_RUBRIC = {
    "json_format": {"max_score": 5},
    "unfilled_shifts": {"max_score": 30},
    "tuesday_split_shift": {"max_score": 20},
    "saturday_window_clerk": {"max_score": 10},
    "standard_scheduling": {"max_score": 25},
    "scheduling_notes": {"max_score": 10},
}

# --- Helper Functions ---

def load_json_file(filepath):
    """Loads a JSON file and returns its content, or None on error."""
    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            return json.load(f)
    except FileNotFoundError:
        print(f"Error: File not found at {filepath}")
        return None
    except json.JSONDecodeError:
        print(f"Error: Could not decode JSON from {filepath}. File is malformed.")
        return None

def _dict_to_frozenset(d):
    """Converts a dictionary to a frozenset of its items for hashing."""
    return frozenset(d.items())

def _get_schedule_as_set(schedule_dict):
    """Converts a schedule dictionary into a set of (day, shift_frozenset) tuples."""
    schedule_set = set()
    if not isinstance(schedule_dict, dict):
        return schedule_set
    for day, shifts in schedule_dict.items():
        if not isinstance(shifts, list):
            continue
        for shift in shifts:
            if isinstance(shift, dict):
                schedule_set.add((day, _dict_to_frozenset(shift)))
    return schedule_set

def _get_unfilled_as_set(unfilled_list):
    """Converts a list of unfilled shift dicts into a set of frozensets."""
    if not isinstance(unfilled_list, list):
        return set()
    return {_dict_to_frozenset(shift) for shift in unfilled_list if isinstance(shift, dict)}

# --- Scoring Functions ---

def score_json_format(submission_data):
    """Scores the submission based on its JSON structure."""
    max_score = SCORING_RUBRIC["json_format"]["max_score"]

    if submission_data is None:
        return 0, max_score, "Submission file could not be read or is not valid JSON."

    required_keys = {"schedule", "unfilled_shifts", "scheduling_notes"}
    if not isinstance(submission_data, dict) or not required_keys.issubset(submission_data.keys()):
        comment = f"Submission is missing one or more top-level keys. Required: {required_keys}"
        return 0, max_score, comment

    schedule = submission_data.get("schedule")
    required_days = {"Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"}
    if not isinstance(schedule, dict) or not required_days.issubset(schedule.keys()):
        comment = f"The 'schedule' object is missing one or more days. Required: {required_days}"
        return 0, max_score, comment

    return max_score, max_score, "Submission format is valid."

def score_unfilled_shifts(submission_unfilled, key_unfilled):
    """Scores the identification of unfilled shifts."""
    max_score = SCORING_RUBRIC["unfilled_shifts"]["max_score"]

    sub_set = _get_unfilled_as_set(submission_unfilled)
    key_set = _get_unfilled_as_set(key_unfilled)

    points_per_shift = max_score / len(key_set) if key_set else 0

    correctly_identified = sub_set.intersection(key_set)
    score = len(correctly_identified) * points_per_shift

    comment = (f"Correctly identified {len(correctly_identified)} of {len(key_set)} unfilled shifts. "
               f"Missing: {len(key_set - sub_set)}. "
               f"Incorrectly added: {len(sub_set - key_set)}.")

    return score, max_score, comment

def score_tuesday_split_shift(submission_schedule, key_schedule):
    """Scores the correct handling of the Tuesday split shift."""
    max_score = SCORING_RUBRIC["tuesday_split_shift"]["max_score"]

    key_tuesday_shifts = key_schedule.get("Tuesday", [])
    split_shift_parts = [
        s for s in key_tuesday_shifts if s.get("employee_id") in [102, 103] and s.get("role") == "Window Clerk"
    ]

    if len(split_shift_parts) != 2:
        return 0, max_score, "CRITICAL ERROR IN ANSWER KEY: Could not find the two split shift parts."

    sub_tuesday_set = {shift for day, shift in _get_schedule_as_set(submission_schedule) if day == "Tuesday"}

    found_count = 0
    for part in split_shift_parts:
        if _dict_to_frozenset(part) in sub_tuesday_set:
            found_count += 1

    score = found_count * (max_score / 2)
    comment = f"Correctly scheduled {found_count} of the 2 parts of the Tuesday split shift."
    return score, max_score, comment

def score_saturday_window_clerk(submission_schedule, key_schedule):
    """Scores the correct assignment for the Saturday Window Clerk."""
    max_score = SCORING_RUBRIC["saturday_window_clerk"]["max_score"]

    key_saturday_shift = next((s for s in key_schedule.get("Saturday", []) if s.get("role") == "Window Clerk"), None)

    if not key_saturday_shift:
        return 0, max_score, "CRITICAL ERROR IN ANSWER KEY: Could not find Saturday Window Clerk shift."

    sub_saturday_set = {shift for day, shift in _get_schedule_as_set(submission_schedule) if day == "Saturday"}

    if _dict_to_frozenset(key_saturday_shift) in sub_saturday_set:
        score = max_score
        comment = "Correctly assigned the Saturday Window Clerk shift."
    else:
        score = 0
        comment = "Failed to correctly assign the Saturday Window Clerk shift."

    return score, max_score, comment

def score_standard_scheduling(submission_schedule, key_schedule):
    """Scores all other standard shift assignments."""
    max_score = SCORING_RUBRIC["standard_scheduling"]["max_score"]

    sub_all_shifts = _get_schedule_as_set(submission_schedule)
    key_all_shifts = _get_schedule_as_set(key_schedule)

    # Identify the "special" shifts that are scored elsewhere to avoid double-counting
    key_tuesday_shifts = key_schedule.get("Tuesday", [])
    tuesday_split_parts = {
        ("Tuesday", _dict_to_frozenset(s)) for s in key_tuesday_shifts 
        if s.get("employee_id") in [102, 103] and s.get("role") == "Window Clerk"
    }
    saturday_clerk_shift = {
        ("Saturday", _dict_to_frozenset(s)) for s in key_schedule.get("Saturday", [])
        if s.get("role") == "Window Clerk"
    }
    special_shifts = tuesday_split_parts.union(saturday_clerk_shift)

    key_standard_set = key_all_shifts - special_shifts
    sub_standard_set = sub_all_shifts - special_shifts

    errors = len(key_standard_set.symmetric_difference(sub_standard_set))
    points_deducted = errors * 2
    score = max(0, max_score - points_deducted)

    num_correct = len(key_standard_set.intersection(sub_standard_set))
    comment = (f"Found {num_correct} of {len(key_standard_set)} standard shifts correctly. "
               f"{errors} errors resulted in a deduction of {points_deducted} points.")

    return score, max_score, comment

def score_scheduling_notes(submission_notes):
    """Scores the quality of the scheduling notes based on keywords."""
    max_score = SCORING_RUBRIC["scheduling_notes"]["max_score"]

    if not isinstance(submission_notes, str) or not submission_notes.strip():
        return 0, max_score, "Scheduling note is missing or empty."

    note = submission_notes.lower()

    has_maria = "maria" in note or "102" in note
    has_wei = "wei" in note or "chen" in note or "103" in note
    has_concept = any(k in note for k in ["split", "cover", "gap", "morning", "portion"])

    if has_maria and has_wei and has_concept:
        score = max_score
        comment = "Note correctly and completely explains the split-shift logic."
    elif (has_maria or has_wei) and has_concept:
        score = max_score / 2
        comment = "Note partially explains the logic but is missing key details."
    else:
        score = 0
        comment = "Note does not adequately explain the required scheduling decision."

    return score, max_score, comment

# --- Main Evaluation Function ---

def evaluate(submission_path, key_path):
    """Reads submission and key files, scores the test, and saves results."""

    submission_data = load_json_file(submission_path)
    answer_key_data = load_json_file(key_path)

    if answer_key_data is None:
        print("Evaluation cannot proceed: answer key file could not be loaded.")
        return

    results = {"breakdown": {}}
    total_score = 0

    # 1. Score JSON Format
    score, max_s, comment = score_json_format(submission_data)
    results["breakdown"]["json_format"] = {"score": score, "max_score": max_s, "comment": comment}
    total_score += score

    # If format is invalid, we can't reliably score the rest.
    if score == 0:
        print("Critical error in submission format. Most scores will be 0.")
        for category in SCORING_RUBRIC:
            if category not in results["breakdown"]:
                results["breakdown"][category] = {
                    "score": 0, 
                    "max_score": SCORING_RUBRIC[category]["max_score"], 
                    "comment": "Not evaluated due to invalid file structure."
                }
    else:
        # Proceed with other scoring categories
        categories_to_score = [
            ("unfilled_shifts", score_unfilled_shifts, [submission_data.get("unfilled_shifts"), answer_key_data.get("unfilled_shifts")]),
            ("tuesday_split_shift", score_tuesday_split_shift, [submission_data.get("schedule"), answer_key_data.get("schedule")]),
            ("saturday_window_clerk", score_saturday_window_clerk, [submission_data.get("schedule"), answer_key_data.get("schedule")]),
            ("standard_scheduling", score_standard_scheduling, [submission_data.get("schedule"), answer_key_data.get("schedule")]),
            ("scheduling_notes", score_scheduling_notes, [submission_data.get("scheduling_notes")])
        ]

        for name, func, args in categories_to_score:
            score, max_s, comment = func(*args)
            results["breakdown"][name] = {"score": score, "max_score": max_s, "comment": comment}
            total_score += score

    results["overall_score"] = total_score

    output_filename = 'test_results.json'
    with open(output_filename, 'w', encoding='utf-8') as f:
        json.dump(results, f, indent=4)

    print(f"Evaluation complete. Results saved to {output_filename}")
    print(f"Overall Score: {total_score} / 100")

# --- Command-Line Interface ---

if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("Usage: python task_evaluation.py <submission_file.json> <answer_key_file.json>")
        sys.exit(1)

    submission_file = sys.argv[1]
    answer_key_file = sys.argv[2]

    evaluate(submission_file, answer_key_file)
```

