### `task_evaluation.py`

```python
import json
import sys
import os

# Define the scoring rubric as a constant
SCORING_RUBRIC = {
    "part_1_initial_budget": {
        "possible_points": 9,
        "line_items": 5,
        "projected_total_cost": 2,
        "remaining_contingency": 2,
    },
    "part_2_vendor_analysis": {
        "possible_points": 11,
        "vendor_a_total_cost": 3,
        "vendor_b_total_cost": 4,
        "selected_vendor_name": 4,
    },
    "part_3_final_budget": {
        "possible_points": 11,
        "updated_line_items": 5,
        "final_total_cost": 3,
        "final_contingency": 3,
    },
    "overall_quality": {
        "possible_points": 4,
        "calculation_strings": 2,
        "valid_submission": 2,
    },
    "total_possible_points": 35,
}

def load_json_file(filepath):
    """Loads a JSON file and returns its content, or an error message."""
    if not os.path.exists(filepath):
        return None, f"Error: File not found at '{filepath}'"
    try:
        with open(filepath, 'r') as f:
            return json.load(f), None
    except json.JSONDecodeError:
        return None, f"Error: Invalid JSON format in '{filepath}'"
    except Exception as e:
        return None, f"An unexpected error occurred while reading '{filepath}': {e}"

def evaluate_part1(submission, key):
    """Evaluates Part 1: Initial Budget."""
    points = 0
    results = {}

    # Score line items
    line_item_points = 0
    key_costs = {item['item_description']: item['cost'] for item in key.get('line_items', [])}
    sub_items = submission.get('line_items', [])
    if isinstance(sub_items, list):
        for item in sub_items:
            desc = item.get('item_description')
            cost = item.get('cost')
            if desc in key_costs and cost == key_costs[desc]:
                line_item_points += 1
    results['line_items_cost'] = {"achieved": line_item_points, "possible": SCORING_RUBRIC["part_1_initial_budget"]["line_items"]}
    points += line_item_points

    # Score projected_total_cost
    if submission.get('projected_total_cost') == key.get('projected_total_cost'):
        points += SCORING_RUBRIC["part_1_initial_budget"]["projected_total_cost"]
        results['projected_total_cost'] = {"achieved": SCORING_RUBRIC["part_1_initial_budget"]["projected_total_cost"], "possible": SCORING_RUBRIC["part_1_initial_budget"]["projected_total_cost"]}
    else:
        results['projected_total_cost'] = {"achieved": 0, "possible": SCORING_RUBRIC["part_1_initial_budget"]["projected_total_cost"]}

    # Score remaining_contingency
    if submission.get('remaining_contingency') == key.get('remaining_contingency'):
        points += SCORING_RUBRIC["part_1_initial_budget"]["remaining_contingency"]
        results['remaining_contingency'] = {"achieved": SCORING_RUBRIC["part_1_initial_budget"]["remaining_contingency"], "possible": SCORING_RUBRIC["part_1_initial_budget"]["remaining_contingency"]}
    else:
        results['remaining_contingency'] = {"achieved": 0, "possible": SCORING_RUBRIC["part_1_initial_budget"]["remaining_contingency"]}

    return points, results

def evaluate_part2(submission, key):
    """Evaluates Part 2: Vendor Analysis."""
    points = 0
    results = {}
    critical_failure = False

    # Score vendor_a_total_cost
    if submission.get('vendor_a_total_cost') == key.get('vendor_a_total_cost'):
        points += SCORING_RUBRIC["part_2_vendor_analysis"]["vendor_a_total_cost"]
        results['vendor_a_total_cost'] = {"achieved": SCORING_RUBRIC["part_2_vendor_analysis"]["vendor_a_total_cost"], "possible": SCORING_RUBRIC["part_2_vendor_analysis"]["vendor_a_total_cost"]}
    else:
        results['vendor_a_total_cost'] = {"achieved": 0, "possible": SCORING_RUBRIC["part_2_vendor_analysis"]["vendor_a_total_cost"]}

    # Score vendor_b_total_cost
    if submission.get('vendor_b_total_cost') == key.get('vendor_b_total_cost'):
        points += SCORING_RUBRIC["part_2_vendor_analysis"]["vendor_b_total_cost"]
        results['vendor_b_total_cost'] = {"achieved": SCORING_RUBRIC["part_2_vendor_analysis"]["vendor_b_total_cost"], "possible": SCORING_RUBRIC["part_2_vendor_analysis"]["vendor_b_total_cost"]}
    else:
        results['vendor_b_total_cost'] = {"achieved": 0, "possible": SCORING_RUBRIC["part_2_vendor_analysis"]["vendor_b_total_cost"]}

    # Score selected_vendor_name and check for critical failure
    selected_vendor = submission.get('selected_vendor_name')
    if selected_vendor == key.get('selected_vendor_name'):
        points += SCORING_RUBRIC["part_2_vendor_analysis"]["selected_vendor_name"]
        results['selected_vendor_name'] = {"achieved": SCORING_RUBRIC["part_2_vendor_analysis"]["selected_vendor_name"], "possible": SCORING_RUBRIC["part_2_vendor_analysis"]["selected_vendor_name"]}
    else:
        results['selected_vendor_name'] = {"achieved": 0, "possible": SCORING_RUBRIC["part_2_vendor_analysis"]["selected_vendor_name"]}
        if selected_vendor == "Bulk Tees Inc.":
            critical_failure = True

    return points, results, critical_failure

def evaluate_part3(submission, key):
    """Evaluates Part 3: Final Budget."""
    points = 0
    results = {}

    # Score updated_line_items
    key_items = {item['item_description']: item['cost'] for item in key.get('updated_line_items', [])}
    sub_items_list = submission.get('updated_line_items', [])

    if isinstance(sub_items_list, list):
        sub_items = {item.get('item_description'): item.get('cost') for item in sub_items_list}
        if key_items == sub_items:
            points += SCORING_RUBRIC["part_3_final_budget"]["updated_line_items"]
            results['updated_line_items'] = {"achieved": SCORING_RUBRIC["part_3_final_budget"]["updated_line_items"], "possible": SCORING_RUBRIC["part_3_final_budget"]["updated_line_items"]}
        else:
            results['updated_line_items'] = {"achieved": 0, "possible": SCORING_RUBRIC["part_3_final_budget"]["updated_line_items"]}
    else:
        results['updated_line_items'] = {"achieved": 0, "possible": SCORING_RUBRIC["part_3_final_budget"]["updated_line_items"]}

    # Score final_total_cost
    if submission.get('final_total_cost') == key.get('final_total_cost'):
        points += SCORING_RUBRIC["part_3_final_budget"]["final_total_cost"]
        results['final_total_cost'] = {"achieved": SCORING_RUBRIC["part_3_final_budget"]["final_total_cost"], "possible": SCORING_RUBRIC["part_3_final_budget"]["final_total_cost"]}
    else:
        results['final_total_cost'] = {"achieved": 0, "possible": SCORING_RUBRIC["part_3_final_budget"]["final_total_cost"]}

    # Score final_contingency
    if submission.get('final_contingency') == key.get('final_contingency'):
        points += SCORING_RUBRIC["part_3_final_budget"]["final_contingency"]
        results['final_contingency'] = {"achieved": SCORING_RUBRIC["part_3_final_budget"]["final_contingency"], "possible": SCORING_RUBRIC["part_3_final_budget"]["final_contingency"]}
    else:
        results['final_contingency'] = {"achieved": 0, "possible": SCORING_RUBRIC["part_3_final_budget"]["final_contingency"]}

    return points, results

def evaluate_overall(submission):
    """Evaluates overall submission quality."""
    points = 0
    results = {}

    # Score valid submission (candidate_name filled)
    if submission.get('candidate_name'):
        points += SCORING_RUBRIC["overall_quality"]["valid_submission"]
        results['valid_submission'] = {"achieved": SCORING_RUBRIC["overall_quality"]["valid_submission"], "possible": SCORING_RUBRIC["overall_quality"]["valid_submission"]}
    else:
        results['valid_submission'] = {"achieved": 0, "possible": SCORING_RUBRIC["overall_quality"]["valid_submission"]}

    # Score calculation strings (check for presence)
    calc_strings_ok = True
    for part_key in ['part_1_initial_budget', 'part_3_final_budget']:
        part_data = submission.get(part_key, {})
        line_items_key = 'line_items' if part_key == 'part_1_initial_budget' else 'updated_line_items'

        for item in part_data.get(line_items_key, []):
            if not item.get('calculation'):
                calc_strings_ok = False
                break
        if not calc_strings_ok:
            break

    if calc_strings_ok:
        points += SCORING_RUBRIC["overall_quality"]["calculation_strings"]
        results['calculation_strings'] = {"achieved": SCORING_RUBRIC["overall_quality"]["calculation_strings"], "possible": SCORING_RUBRIC["overall_quality"]["calculation_strings"]}
    else:
        results['calculation_strings'] = {"achieved": 0, "possible": SCORING_RUBRIC["overall_quality"]["calculation_strings"]}

    return points, results

def main():
    """Main function to run the evaluation script."""
    if len(sys.argv) != 3:
        print("Usage: python task_evaluation.py <submission_file.json> <answer_key_file.json>")
        sys.exit(1)

    submission_file = sys.argv[1]
    answer_key_file = sys.argv[2]

    submission_data, error = load_json_file(submission_file)
    if error:
        results = {"overall_score": 0, "passed": False, "notes": [error]}
        with open('test_results.json', 'w') as f:
            json.dump(results, f, indent=4)
        print(error)
        sys.exit(1)

    answer_key_data, error = load_json_file(answer_key_file)
    if error:
        results = {"overall_score": 0, "passed": False, "notes": [error]}
        with open('test_results.json', 'w') as f:
            json.dump(results, f, indent=4)
        print(error)
        sys.exit(1)

    total_achieved_points = 0
    detailed_results = {}
    notes = []

    # Evaluate Part 1
    p1_points, p1_results = evaluate_part1(submission_data.get('part_1_initial_budget', {}), answer_key_data.get('part_1_initial_budget', {}))
    total_achieved_points += p1_points
    detailed_results['part_1_initial_budget'] = {"achieved_points": p1_points, "possible_points": SCORING_RUBRIC["part_1_initial_budget"]["possible_points"], "breakdown": p1_results}

    # Evaluate Part 2
    p2_points, p2_results, critical_failure = evaluate_part2(submission_data.get('part_2_vendor_analysis', {}), answer_key_data.get('part_2_vendor_analysis', {}))
    total_achieved_points += p2_points
    detailed_results['part_2_vendor_analysis'] = {"achieved_points": p2_points, "possible_points": SCORING_RUBRIC["part_2_vendor_analysis"]["possible_points"], "breakdown": p2_results}
    if critical_failure:
        notes.append("Critical Failure: Incorrect vendor selected. This demonstrates a lack of analytical skill and attention to detail required for the role.")

    # Evaluate Part 3
    p3_points, p3_results = evaluate_part3(submission_data.get('part_3_final_budget', {}), answer_key_data.get('part_3_final_budget', {}))
    total_achieved_points += p3_points
    detailed_results['part_3_final_budget'] = {"achieved_points": p3_points, "possible_points": SCORING_RUBRIC["part_3_final_budget"]["possible_points"], "breakdown": p3_results}

    # Evaluate Overall Quality
    overall_points, overall_results = evaluate_overall(submission_data)
    total_achieved_points += overall_points
    detailed_results['overall_quality'] = {"achieved_points": overall_points, "possible_points": SCORING_RUBRIC["overall_quality"]["possible_points"], "breakdown": overall_results}

    # Calculate final score and pass/fail status
    overall_score = (total_achieved_points / SCORING_RUBRIC["total_possible_points"]) * 100
    passed = overall_score >= 80 and not critical_failure

    # Compile final results
    final_results = {
        "candidate_name": submission_data.get("candidate_name", "N/A"),
        "total_possible_points": SCORING_RUBRIC["total_possible_points"],
        "total_achieved_points": total_achieved_points,
        "overall_score": round(overall_score, 2),
        "passed": passed,
        "notes": notes,
        "detailed_results": detailed_results
    }

    # Save results to file
    with open('test_results.json', 'w') as f:
        json.dump(final_results, f, indent=4)

    print(f"Evaluation complete. Results saved to 'test_results.json'.")

if __name__ == "__main__":
    main()
```

