### `task_evaluation.py`

```python
import sys
import json

def evaluate_submission(submission_path, key_path):
    """
    Reads a candidate's submission and an answer key, scores the submission,
    and saves the detailed results to a JSON file.

    Args:
        submission_path (str): The file path for the candidate's submission JSON.
        key_path (str): The file path for the answer key JSON.
    """
    # --- 1. Read and Parse Input Files ---
    try:
        with open(submission_path, 'r') as f:
            submission_data = json.load(f)
        with open(key_path, 'r') as f:
            key_data = json.load(f)
    except FileNotFoundError as e:
        print(f"Error: File not found - {e}. Please check the file paths.", file=sys.stderr)
        sys.exit(1)
    except json.JSONDecodeError as e:
        print(f"Error: Invalid JSON format in a file - {e}. Please check the file contents.", file=sys.stderr)
        sys.exit(1)

    # --- 2. Initialize Scoring Variables and Results Structure ---
    score = 0
    total_questions = 0
    results = {
        "candidate_name": submission_data.get("exam_candidate_name", "N/A"),
        "overall_score": 0.0,
        "summary": {},
        "details": {}
    }

    # --- 3. Compare Submission to Answer Key ---
    # Iterate through the main sections of the answer key (e.g., "part_1_data_analysis").
    # This ensures all questions are checked, even if missing from the submission.
    for part_key, part_value in key_data.items():
        # We only care about the dictionary sections that contain questions.
        if isinstance(part_value, dict):
            results["details"][part_key] = {}
            submission_part = submission_data.get(part_key, {})

            # Iterate through each question in the current section.
            for question_key, correct_answer in part_value.items():
                total_questions += 1
                candidate_answer = submission_part.get(question_key)
                is_correct = False

                # Apply comparison logic based on the data type of the correct answer.
                if isinstance(correct_answer, str):
                    # For strings, compare case-insensitively and ignore leading/trailing whitespace.
                    if isinstance(candidate_answer, str):
                        is_correct = candidate_answer.strip().lower() == correct_answer.strip().lower()
                elif isinstance(correct_answer, float):
                    # For floats, check if the values are close enough to account for precision.
                    if isinstance(candidate_answer, (int, float)):
                        is_correct = abs(float(candidate_answer) - correct_answer) < 0.001
                else:
                    # For integers and other types, a direct comparison is sufficient.
                    is_correct = (candidate_answer == correct_answer)

                if is_correct:
                    score += 1

                # Store detailed results for this question.
                results["details"][part_key][question_key] = {
                    "candidate_answer": candidate_answer,
                    "correct_answer": correct_answer,
                    "is_correct": is_correct
                }

    # --- 4. Calculate Final Score and Create Summary ---
    if total_questions > 0:
        overall_score = (score / total_questions) * 100
    else:
        overall_score = 0.0

    results["overall_score"] = round(overall_score, 2)
    results["summary"] = {
        "correct_answers": score,
        "total_questions": total_questions,
        "score_percentage": round(overall_score, 2)
    }

    # --- 5. Save Results to File ---
    output_filename = "test_results.json"
    with open(output_filename, 'w') as f:
        json.dump(results, f, indent=4)

    print(f"Evaluation complete. Results saved to '{output_filename}'")


if __name__ == "__main__":
    # --- Command-Line Argument Handling ---
    if len(sys.argv) != 3:
        print("Usage: python task_evaluation.py <submission_file.json> <key_file.json>", file=sys.stderr)
        sys.exit(1)

    submission_file_path = sys.argv[1]
    key_file_path = sys.argv[2]

    evaluate_submission(submission_file_path, key_file_path)
```

### How to Use the Script

1.  **Save the code:** Save the script above as `task_evaluation.py`.
2.  **Prepare the files:** Make sure you have the candidate's submission file (e.g., `test_submission.json`) and the answer key file (e.g., `answer_key.json`) in the same directory as the script.
3.  **Run from the command line:** Open your terminal or command prompt, navigate to the directory containing the files, and run the script by providing the submission and key files as arguments.

    ```bash
    python task_evaluation.py test_submission.json answer_key.json
    ```

4.  **Check the output:** The script will create a new file named `test_results.json` in the same directory. This file will contain a detailed breakdown of the candidate's performance and their overall score.

### Example `test_results.json` Output

If a candidate got 8 out of 10 questions correct, the output file would look like this:

