```python
import json
import sys
import math

def load_json_file(filepath):
    """Loads a JSON file and returns its content."""
    try:
        with open(filepath, 'r') as f:
            return json.load(f)
    except FileNotFoundError:
        print(f"Error: File not found at '{filepath}'")
        sys.exit(1)
    except json.JSONDecodeError:
        print(f"Error: Could not decode JSON from '{filepath}'. Please ensure it is a valid JSON file.")
        sys.exit(1)

def transform_to_dict(data_list, key_field='partNumber'):
    """Transforms a list of dicts into a dict keyed by a specific field."""
    if not isinstance(data_list, list):
        return None, f"Expected a list but got {type(data_list).__name__}"

    transformed_dict = {}
    for item in data_list:
        if not isinstance(item, dict):
             return None, f"Expected items in list to be dictionaries, but found {type(item).__name__}"
        if key_field not in item:
            return None, f"Key '{key_field}' not found in one of the list items."
        transformed_dict[item[key_field]] = item
    return transformed_dict, None

def evaluate_submission(submission_path, answer_key_path):
    """
    Compares a candidate's submission JSON with an answer key JSON and scores it.
    """
    # Load files
    submission_data = load_json_file(submission_path)
    answer_key_data = load_json_file(answer_key_path)

    # Check for the main list key
    if 'standardCostList' not in submission_data:
        print("Error: Submission file is missing the 'standardCostList' key.")
        sys.exit(1)
    if 'standardCostList' not in answer_key_data:
        print("Error: Answer key file is missing the 'standardCostList' key.")
        sys.exit(1)

    # Transform lists to dictionaries for easy lookup
    submitted_items, s_err = transform_to_dict(submission_data['standardCostList'])
    if s_err:
        print(f"Error in submission file structure: {s_err}")
        sys.exit(1)

    answer_key_items, a_err = transform_to_dict(answer_key_data['standardCostList'])
    if a_err:
        print(f"Error in answer key file structure: {a_err}")
        sys.exit(1)

    # Initialize scoring
    total_points_achieved = 0
    total_points_possible = 0
    evaluation_breakdown = {}

    fields_to_check = {
        'selectedSupplier': 'string',
        'rawMaterialCostUSD': 'number',
        'freightCostUSD': 'number',
        'standardLandedCostUSD': 'number',
        'notes': 'string'
    }

    # Iterate through the answer key to ensure all required parts are checked
    for part_number, correct_item in answer_key_items.items():
        part_max_points = len(fields_to_check)
        total_points_possible += part_max_points
        part_points_achieved = 0
        field_comparison = {}

        submitted_item = submitted_items.get(part_number)

        if not submitted_item:
            evaluation_breakdown[part_number] = {
                "status": "Part missing from submission",
                "points_achieved": 0,
                "max_points": part_max_points
            }
            continue

        # Compare each field for the current part
        for field, field_type in fields_to_check.items():
            submitted_value = submitted_item.get(field)
            correct_value = correct_item.get(field)
            is_correct = False

            if submitted_value is not None:
                if field_type == 'number':
                    # Use math.isclose for floating point comparison with a tolerance
                    if isinstance(submitted_value, (int, float)):
                        is_correct = math.isclose(submitted_value, correct_value, rel_tol=1e-9, abs_tol=0.01)
                elif field_type == 'string':
                    is_correct = (submitted_value == correct_value)

            if is_correct:
                part_points_achieved += 1
                status = "Correct"
            else:
                status = "Incorrect"

            field_comparison[field] = {
                "status": status,
                "submitted": submitted_value,
                "expected": correct_value
            }

        total_points_achieved += part_points_achieved
        evaluation_breakdown[part_number] = {
            "points_achieved": part_points_achieved,
            "max_points": part_max_points,
            "field_comparison": field_comparison
        }

    # Calculate overall score
    overall_score = (total_points_achieved / total_points_possible) * 100 if total_points_possible > 0 else 0

    # Prepare final results structure
    results = {
        "overall_score": round(overall_score, 2),
        "total_points_achieved": total_points_achieved,
        "total_points_possible": total_points_possible,
        "evaluation_breakdown": evaluation_breakdown
    }

    # Save results to file
    output_filename = 'test_results.json'
    with open(output_filename, 'w') as f:
        json.dump(results, f, indent=4)

    print(f"Evaluation complete. Results saved to '{output_filename}'")

def main():
    """Main function to handle command-line arguments and start evaluation."""
    if len(sys.argv) != 3:
        print("Usage: python task_evaluation.py <submission_file.json> <answer_key_file.json>")
        sys.exit(1)

    submission_file = sys.argv[1]
    answer_key_file = sys.argv[2]

    evaluate_submission(submission_file, answer_key_file)

if __name__ == "__main__":
    main()
```

