### `task_evaluation.py`

```python
import json
import argparse
import math
import sys

def compare_transaction_lists(submitted_list, key_list):
    """
    Compares two lists of dictionaries, ignoring the order of items in the list.
    Returns True if they are equivalent, False otherwise.
    """
    if not isinstance(submitted_list, list):
        return False
    if len(submitted_list) != len(key_list):
        return False

    # An empty list is a valid submission if the key is also empty
    if not key_list and not submitted_list:
        return True

    try:
        # Convert list of dicts to a set of frozensets for order-independent comparison
        submitted_set = {frozenset(item.items()) for item in submitted_list}
        key_set = {frozenset(item.items()) for item in key_list}
    except (AttributeError, TypeError):
        # This catches cases where items in the list are not dictionaries
        return False

    return submitted_set == key_set

def evaluate_submission(submission_data, key_data):
    """
    Evaluates the candidate's submission against the answer key.
    Returns a dictionary with the detailed scoring breakdown.
    """
    results = {
        "breakdown": {},
        "total_score": 0
    }

    # --- 1. Critical Thinking & Identification (35 points) ---
    critical_thinking_score = 0
    critical_thinking_details = {}

    # 1a. Capital Expenditure Identification (20 points)
    submitted_capex = submission_data.get("identified_transactions", {}).get("excluded_capital_expenditures", [])
    key_capex = key_data.get("identified_transactions", {}).get("excluded_capital_expenditures", [])
    capex_correct = compare_transaction_lists(submitted_capex, key_capex)

    if capex_correct:
        critical_thinking_details["capital_expenditure_identification"] = {
            "score": 20, "max_score": 20, "comment": "Correctly identified and listed the capital expenditure."
        }
        critical_thinking_score += 20
    else:
        critical_thinking_details["capital_expenditure_identification"] = {
            "score": 0, "max_score": 20, "comment": "Failed to correctly identify and list the capital expenditure."
        }

    # 1b. Non-Recurring Expense Handling (15 points)
    submitted_non_recurring = submission_data.get("identified_transactions", {}).get("excluded_non_recurring_expenses", [])
    key_non_recurring = key_data.get("identified_transactions", {}).get("excluded_non_recurring_expenses", [])
    non_recurring_identified = compare_transaction_lists(submitted_non_recurring, key_non_recurring)

    submitted_mr_2025 = submission_data.get("expense_schedule", {}).get("2025_proposed", {}).get("maintenance_repairs", -1)
    key_mr_2025 = key_data.get("expense_schedule", {}).get("2025_proposed", {}).get("maintenance_repairs", 0)
    mr_calc_correct = math.isclose(submitted_mr_2025, key_mr_2025, rel_tol=1e-9, abs_tol=0.01)

    if non_recurring_identified and mr_calc_correct:
        critical_thinking_details["non_recurring_expense_handling"] = {
            "score": 15, "max_score": 15, "comment": "Correctly identified non-recurring expense and used the correct baseline for the 2025 M&R projection."
        }
        critical_thinking_score += 15
    elif non_recurring_identified and not mr_calc_correct:
        critical_thinking_details["non_recurring_expense_handling"] = {
            "score": 0, "max_score": 15, "comment": "Identified the non-recurring expense but failed to use the correct baseline for the 2025 M&R projection."
        }
    else:
        critical_thinking_details["non_recurring_expense_handling"] = {
            "score": 0, "max_score": 15, "comment": "Failed to identify the non-recurring expense."
        }

    pass_fail_status = "Pass" if critical_thinking_score == 35 else "Fail"
    results["breakdown"]["critical_thinking"] = {
        "score": critical_thinking_score,
        "max_score": 35,
        "status": pass_fail_status,
        "details": critical_thinking_details
    }
    results["total_score"] += critical_thinking_score

    # --- 2. Accuracy of 2024 Actuals (30 points) ---
    actuals_2024_score = 0
    actuals_2024_details = {}

    # 2a. Correct 2024 Income (10 points)
    submitted_income_2024 = submission_data.get("income_schedule", {}).get("2024_actuals", {})
    key_income_2024 = key_data.get("income_schedule", {}).get("2024_actuals", {})
    income_2024_correct = True
    for key, value in key_income_2024.items():
        if not math.isclose(submitted_income_2024.get(key, -1), value, rel_tol=1e-9, abs_tol=0.01):
            income_2024_correct = False
            break

    if income_2024_correct:
        actuals_2024_details["2024_income_schedule"] = {"score": 10, "max_score": 10, "comment": "2024 income schedule is correct."}
        actuals_2024_score += 10
    else:
        actuals_2024_details["2024_income_schedule"] = {"score": 0, "max_score": 10, "comment": "2024 income schedule contains errors."}

    # 2b. Correct 2024 Expenses (20 points)
    submitted_expenses_2024 = submission_data.get("expense_schedule", {}).get("2024_actuals", {})
    key_expenses_2024 = key_data.get("expense_schedule", {}).get("2024_actuals", {})
    expense_2024_points = 20
    expense_2024_comments = []

    for key, value in key_expenses_2024.items():
        if not math.isclose(submitted_expenses_2024.get(key, -1), value, rel_tol=1e-9, abs_tol=0.01):
            expense_2024_points = max(0, expense_2024_points - 5)
            expense_2024_comments.append(f"Incorrect value for 2024 expense: '{key}'.")

    if not expense_2024_comments:
        expense_2024_comments.append("2024 expense schedule is correct.")

    actuals_2024_details["2024_expense_schedule"] = {
        "score": expense_2024_points, "max_score": 20, "comment": " ".join(expense_2024_comments)
    }
    actuals_2024_score += expense_2024_points

    results["breakdown"]["accuracy_2024_actuals"] = {
        "score": actuals_2024_score, "max_score": 30, "details": actuals_2024_details
    }
    results["total_score"] += actuals_2024_score

    # --- 3. Accuracy of 2025 Projections (35 points) ---
    projections_2025_score = 0
    projections_2025_details = {}

    # 3a. Correct 2025 Income & Summary (15 points)
    submitted_summary = submission_data.get("budget_summary", {})
    key_summary = key_data.get("budget_summary", {})
    income_summary_points = 15
    income_summary_comments = []

    if not math.isclose(submitted_summary.get("gross_potential_rent", -1), key_summary.get("gross_potential_rent"), rel_tol=1e-9, abs_tol=0.01):
        income_summary_points -= 5
        income_summary_comments.append("Incorrect Gross Potential Rent (-5 pts).")
    if not math.isclose(submitted_summary.get("effective_gross_income", -1), key_summary.get("effective_gross_income"), rel_tol=1e-9, abs_tol=0.01):
        income_summary_points -= 5
        income_summary_comments.append("Incorrect Effective Gross Income (-5 pts).")

    if income_summary_points == 15:
        is_fully_correct = True
        for key, value in key_summary.items():
            if not math.isclose(submitted_summary.get(key, -1), value, rel_tol=1e-9, abs_tol=0.01):
                is_fully_correct = False; break
        if is_fully_correct:
            submitted_income_2025 = submission_data.get("income_schedule", {}).get("2025_proposed", {})
            key_income_2025 = key_data.get("income_schedule", {}).get("2025_proposed", {})
            for key, value in key_income_2025.items():
                if not math.isclose(submitted_income_2025.get(key, -1), value, rel_tol=1e-9, abs_tol=0.01):
                    is_fully_correct = False; break
        if is_fully_correct:
            income_summary_comments.append("2025 income schedule and budget summary are correct.")
        else:
            income_summary_points = 10
            income_summary_comments.append("GPR and EGI were correct, but other errors were found in the 2025 income/summary section (-5 pts).")

    projections_2025_details["2025_income_and_summary"] = {
        "score": max(0, income_summary_points), "max_score": 15, "comment": " ".join(income_summary_comments)
    }
    projections_2025_score += max(0, income_summary_points)

    # 3b. Correct 2025 Expenses (20 points)
    submitted_expenses_2025 = submission_data.get("expense_schedule", {}).get("2025_proposed", {})
    key_expenses_2025 = key_data.get("expense_schedule", {}).get("2025_proposed", {})
    expense_2025_points = 20
    expense_2025_comments = []

    for key, value in key_expenses_2025.items():
        if not math.isclose(submitted_expenses_2025.get(key, -1), value, rel_tol=1e-9, abs_tol=0.01):
            expense_2025_points = max(0, expense_2025_points - 5)
            expense_2025_comments.append(f"Incorrect value for 2025 expense: '{key}'.")

    if not expense_2025_comments:
        expense_2025_comments.append("2025 expense schedule is correct.")

    projections_2025_details["2025_expense_schedule"] = {
        "score": expense_2025_points, "max_score": 20, "comment": " ".join(expense_2025_comments)
    }
    projections_2025_score += expense_2025_points

    results["breakdown"]["accuracy_2025_projections"] = {
        "score": projections_2025_score, "max_score": 35, "details": projections_2025_details
    }
    results["total_score"] += projections_2025_score

    # Final overall score
    final_results = {
        "overall_score": float(results["total_score"]),
        "breakdown": results["breakdown"]
    }

    return final_results

def main():
    """
    Main function to run the evaluation script from the command line.
    """
    parser = argparse.ArgumentParser(description="Evaluate a property manager's practical exam submission.")
    parser.add_argument("submission_file", help="Path to the candidate's submission JSON file.")
    parser.add_argument("key_file", help="Path to the answer key JSON file.")
    args = parser.parse_args()

    try:
        with open(args.submission_file, 'r') as f:
            submission_data = json.load(f)
    except FileNotFoundError:
        print(f"Error: Submission file not found at '{args.submission_file}'", file=sys.stderr)
        sys.exit(1)
    except json.JSONDecodeError:
        print(f"Error: Could not decode JSON from '{args.submission_file}'. Please ensure it is a valid JSON file.", file=sys.stderr)
        sys.exit(1)

    try:
        with open(args.key_file, 'r') as f:
            key_data = json.load(f)
    except FileNotFoundError:
        print(f"Error: Answer key file not found at '{args.key_file}'", file=sys.stderr)
        sys.exit(1)
    except json.JSONDecodeError:
        print(f"Error: Could not decode JSON from '{args.key_file}'.", file=sys.stderr)
        sys.exit(1)

    # Perform evaluation
    evaluation_results = evaluate_submission(submission_data, key_data)

    # Save results to file
    output_filename = "test_results.json"
    try:
        with open(output_filename, 'w') as f:
            json.dump(evaluation_results, f, indent=2)
        print(f"Evaluation complete. Results saved to '{output_filename}'.")
        print(f"Overall Score: {evaluation_results['overall_score']}%")
    except IOError as e:
        print(f"Error writing results to '{output_filename}': {e}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()
```

An excellent choice for a practical exam. Here is the Python script `task_evaluation.py` to automatically score the candidate's submission based on the provided rubric.

This script is designed to be robust, providing clear, detailed feedback in the output file, which is invaluable for both the candidate and the evaluator.

### `task_evaluation.py`

```python
import sys
import json
import os

# --- Helper Functions ---

def load_json_file(filepath):
    """Loads a JSON file and returns its content. Handles errors."""
    if not os.path.exists(filepath):
        return None, f"Error: File not found at '{filepath}'"
    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            return json.load(f), None
    except json.JSONDecodeError:
        return None, f"Error: Invalid JSON format in '{filepath}'. The file could not be parsed."
    except Exception as e:
        return None, f"An unexpected error occurred while reading '{filepath}': {e}"

def compare_floats(f1, f2, tolerance=0.01):
    """Compares two floats, allowing for a small tolerance (e.g., for currency)."""
    if f1 is None or f2 is None:
        return False
    return abs(f1 - f2) <= tolerance

# --- Evaluation Functions based on Rubric ---

def evaluate_summary(submission_summary, key_summary):
    """Scores the budget_summary section. 30 points total."""
    score = 0
    details = {}

    # total_opex check (10 pts)
    if compare_floats(submission_summary.get('total_opex'), key_summary['total_opex']):
        score += 10
        details['total_opex'] = "Correct (10/10 pts)"
    else:
        details['total_opex'] = f"Incorrect (0/10 pts). Expected {key_summary['total_opex']}, got {submission_summary.get('total_opex')}"

    # total_capex check (10 pts)
    if compare_floats(submission_summary.get('total_capex'), key_summary['total_capex']):
        score += 10
        details['total_capex'] = "Correct (10/10 pts)"
    else:
        details['total_capex'] = f"Incorrect (0/10 pts). Expected {key_summary['total_capex']}, got {submission_summary.get('total_capex')}"

    # total_budget check (10 pts)
    if compare_floats(submission_summary.get('total_budget'), key_summary['total_budget']):
        score += 10
        details['total_budget'] = "Correct (10/10 pts)"
    else:
        details['total_budget'] = f"Incorrect (0/10 pts). Expected {key_summary['total_budget']}, got {submission_summary.get('total_budget')}"

    return score, details

def evaluate_cost_reduction(submission_reduction, key_reduction):
    """Scores the cost_reduction_item section. 25 points total."""
    score = 0
    details = {}

    # removed_item_id check (15 pts)
    if submission_reduction.get('removed_item_id') == key_reduction['removed_item_id']:
        score += 15
        details['removed_item_id'] = "Correct (15/15 pts)"

        # cost_savings check (10 pts) - only if ID is correct
        if compare_floats(submission_reduction.get('cost_savings'), key_reduction['cost_savings']):
            score += 10
            details['cost_savings'] = "Correct (10/10 pts)"
        else:
            details['cost_savings'] = f"Incorrect (0/10 pts). Expected {key_reduction['cost_savings']}, got {submission_reduction.get('cost_savings')}"
    else:
        details['removed_item_id'] = f"Incorrect (0/15 pts). Expected '{key_reduction['removed_item_id']}', got '{submission_reduction.get('removed_item_id')}'"
        details['cost_savings'] = "Not evaluated as removed_item_id was incorrect (0/10 pts)."

    return score, details

def evaluate_items_array(submission_items, key_items, cost_key_name, section_name):
    """Generic function to evaluate OPEX or CAPEX arrays."""
    points_map = {'opex': {'count': 5, 'content': 5, 'cost': 10},
                  'capex': {'count': 5, 'content': 5, 'cost': 5}}

    score = 0
    details = {}

    # Convert lists to dicts for easy lookup, handling potential missing item_id
    submission_dict = {item.get('item_id'): item for item in submission_items if item.get('item_id')}
    key_dict = {item['item_id']: item for item in key_items}

    # 1. Count check
    if len(submission_items) == len(key_items):
        score += points_map[section_name]['count']
        details['item_count'] = f"Correct ({points_map[section_name]['count']}/{points_map[section_name]['count']} pts)"
    else:
        details['item_count'] = f"Incorrect (0/{points_map[section_name]['count']} pts). Expected {len(key_items)} items, got {len(submission_items)}"
        details['item_content'] = f"Not evaluated due to incorrect item count (0/{points_map[section_name]['content']} pts)"
        details['item_costs'] = f"Not evaluated due to incorrect item count (0/{points_map[section_name]['cost']} pts)"
        return score, details

    # 2. Content check (item_ids)
    submission_ids = set(submission_dict.keys())
    key_ids = set(key_dict.keys())
    if submission_ids == key_ids:
        score += points_map[section_name]['content']
        details['item_content'] = f"Correct ({points_map[section_name]['content']}/{points_map[section_name]['content']} pts)"
    else:
        details['item_content'] = f"Incorrect (0/{points_map[section_name]['content']} pts). Missing: {key_ids - submission_ids}. Unexpected: {submission_ids - key_ids}"
        details['item_costs'] = f"Not evaluated due to incorrect item content (0/{points_map[section_name]['cost']} pts)"
        return score, details

    # 3. Cost check
    all_costs_correct = True
    cost_errors = []
    for item_id, key_item in key_dict.items():
        submission_item = submission_dict[item_id]
        if not compare_floats(submission_item.get(cost_key_name), key_item[cost_key_name]):
            all_costs_correct = False
            cost_errors.append(f"Item '{item_id}': Expected cost {key_item[cost_key_name]}, got {submission_item.get(cost_key_name)}")

    if all_costs_correct:
        score += points_map[section_name]['cost']
        details['item_costs'] = f"Correct ({points_map[section_name]['cost']}/{points_map[section_name]['cost']} pts)"
    else:
        details['item_costs'] = f"Incorrect (0/{points_map[section_name]['cost']} pts). Errors: {'; '.join(cost_errors)}"

    return score, details

def check_data_types(submission_data):
    """Checks that all monetary values are numbers, not strings. 5 points."""
    errors = []

    for key, value in submission_data.get('budget_summary', {}).items():
        if not isinstance(value, (int, float)):
            errors.append(f"budget_summary.{key} is not a number")

    cost_savings = submission_data.get('cost_reduction_item', {}).get('cost_savings')
    if cost_savings is not None and not isinstance(cost_savings, (int, float)):
        errors.append("cost_reduction_item.cost_savings is not a number")

    for i, item in enumerate(submission_data.get('opex_items', [])):
        if not isinstance(item.get('annual_cost'), (int, float)):
            errors.append(f"opex_items[{i}].annual_cost is not a number")

    for i, item in enumerate(submission_data.get('capex_items', [])):
        if not isinstance(item.get('cost'), (int, float)):
            errors.append(f"capex_items[{i}].cost is not a number")

    if not errors:
        return 5, {"data_types": "Correct - all monetary values are numbers (5/5 pts)"}
    else:
        return 0, {"data_types": f"Incorrect - some monetary values are strings (0/5 pts). Errors: {', '.join(errors)}"}

# --- Main Execution ---

def main():
    """Main function to run the evaluation script."""
    if len(sys.argv) != 3:
        print("Usage: python task_evaluation.py <submission_file.json> <answer_key_file.json>")
        sys.exit(1)

    submission_file = sys.argv[1]
    answer_key_file = sys.argv[2]

    # Load submission file
    submission_data, error = load_json_file(submission_file)
    if error:
        results = {
            "overall_score": 0,
            "evaluation_error": error,
            "breakdown": {
                "JSON Format & Validity": {
                    "score": 0,
                    "max_score": 10,
                    "details": {"validity": "File is not valid JSON or could not be read (0/5 pts)"}
                }
            }
        }
        with open('test_results.json', 'w', encoding='utf-8') as f:
            json.dump(results, f, indent=4)
        print(f"Evaluation failed: {error}")
        sys.exit(1)

    # Load answer key file
    answer_key_data, error = load_json_file(answer_key_file)
    if error:
        print(f"Critical Error: Could not load answer key. {error}")
        sys.exit(1)

    # --- Start Scoring ---
    total_score = 0
    results_breakdown = {}

    # 1. JSON Format & Validity (10 pts)
    format_score = 5  # 5 points for being valid JSON (already passed)
    format_details = {"validity": "Correct - File is valid JSON (5/5 pts)"}
    type_score, type_details = check_data_types(submission_data)
    format_score += type_score
    format_details.update(type_details)
    total_score += format_score
    results_breakdown["JSON Format & Validity"] = {
        "score": format_score, "max_score": 10, "details": format_details
    }

    # 2. Budget Summary (30 pts)
    summary_score, summary_details = evaluate_summary(
        submission_data.get('budget_summary', {}), answer_key_data['budget_summary']
    )
    total_score += summary_score
    results_breakdown["Budget Summary"] = {
        "score": summary_score, "max_score": 30, "details": summary_details
    }

    # 3. Cost Reduction (25 pts)
    reduction_score, reduction_details = evaluate_cost_reduction(
        submission_data.get('cost_reduction_item', {}), answer_key_data['cost_reduction_item']
    )
    total_score += reduction_score
    results_breakdown["Cost Reduction Item"] = {
        "score": reduction_score, "max_score": 25, "details": reduction_details
    }

    # 4. OPEX Items (20 pts)
    opex_score, opex_details = evaluate_items_array(
        submission_data.get('opex_items', []), answer_key_data['opex_items'], 'annual_cost', 'opex'
    )
    total_score += opex_score
    results_breakdown["OPEX Items Array"] = {
        "score": opex_score, "max_score": 20, "details": opex_details
    }

    # 5. CAPEX Items (15 pts)
    capex_score, capex_details = evaluate_items_array(
        submission_data.get('capex_items', []), answer_key_data['capex_items'], 'cost', 'capex'
    )
    total_score += capex_score
    results_breakdown["CAPEX Items Array"] = {
        "score": capex_score, "max_score": 15, "details": capex_details
    }

    # Finalize results
    final_results = {
        "overall_score": total_score,
        "breakdown": results_breakdown
    }

    # Save results to file
    with open('test_results.json', 'w', encoding='utf-8') as f:
        json.dump(final_results, f, indent=4)

    print(f"Evaluation complete. Results saved to 'test_results.json'. Overall Score: {total_score}/100")

if __name__ == "__main__":
    main()
